-- ALPHA CAPITALIS live CMS + localization deployment
-- Generated from the verified local production snapshot on 2026-08-25.
-- Target: MySQL 8 / utf8mb4. Take a database backup before importing.
-- This file is idempotent: it can be run more than once.
-- It changes only the schema listed below and the explicitly selected CMS rows.

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

-- Schema normally supplied by the two pending Laravel migrations.
DROP PROCEDURE IF EXISTS `ac_apply_20260825_schema`;
DELIMITER $$
CREATE PROCEDURE `ac_apply_20260825_schema`()
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM `information_schema`.`COLUMNS`
        WHERE `TABLE_SCHEMA` = DATABASE()
          AND `TABLE_NAME` = 'contact_messages'
          AND `COLUMN_NAME` = 'form_type'
    ) THEN
        ALTER TABLE `contact_messages`
            ADD COLUMN `form_type` VARCHAR(64) NULL AFTER `status`;
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM `information_schema`.`STATISTICS`
        WHERE `TABLE_SCHEMA` = DATABASE()
          AND `TABLE_NAME` = 'contact_messages'
          AND `INDEX_NAME` = 'contact_messages_form_status_created_index'
    ) THEN
        ALTER TABLE `contact_messages`
            ADD INDEX `contact_messages_form_status_created_index` (`form_type`, `status`, `created_at`);
    END IF;
END$$
DELIMITER ;
CALL `ac_apply_20260825_schema`();
DROP PROCEDURE `ac_apply_20260825_schema`;

ALTER TABLE `content_blog_posts` MODIFY `published_at` DATETIME NULL;

UPDATE `contact_messages`
SET `form_type` = CASE
    WHEN JSON_VALID(`payload`) AND NULLIF(TRIM(JSON_UNQUOTE(JSON_EXTRACT(`payload`, '$.form_type'))), '') IS NOT NULL
        THEN TRIM(JSON_UNQUOTE(JSON_EXTRACT(`payload`, '$.form_type')))
    WHEN `subject` = 'EU Fondovi upitnik' THEN 'eu_funds_questionnaire'
    ELSE 'contact'
END
WHERE `form_type` IS NULL OR TRIM(`form_type`) = '';

UPDATE `content_blog_posts`
SET `published_at` = `created_at`
WHERE `is_active` = 1 AND `published_at` IS NULL;

START TRANSACTION;

-- Enable English while preserving Croatian as the default locale.
UPDATE `languages`
SET `is_active` = 1,
    `is_default` = 0
WHERE `code` = 'en';

UPDATE `languages`
SET `is_active` = 1,
    `is_default` = 1
WHERE `code` = 'hr';

