SELECT `parent`.`id`, 'hr', 'Vi vodite poslovanje. Mi brinemo da brojke prate vaš rast.', NULL, NULL, NULL, NULL, '{\"news\": {\"title\": \"Rokovi, novosti i savjeti za sigurnije poslovanje.\", \"all_posts_url\": \"/blog\", \"all_posts_label\": \"Pogledaj sve objave\", \"excerpt_fallback\": \"Saznajte aktualne informacije, rokove i stručne savjete za sigurnije poslovne odluke.\", \"category_fallback\": \"Novosti\", \"post_action_label\": \"Opširnije\"}, \"values\": {\"intro\": \"ALPHA CAPITALIS pruža vam sigurnost u poslovanju, jasnoću u financijama i partnera koji vam pomaže donositi bolje odluke, smanjiti rizike i ostvariti održiv rast.\", \"items\": [{\"text\": \"Višegodišnje iskustvo u širokom spektru industrija i najviši standardi profesionalne izvrsnosti.\", \"title\": \"Stručnost i iskustvo\"}, {\"text\": \"Neovisni smo, objektivni i posvećeni najvišim profesionalnim i etičkim načelima.\", \"title\": \"Neovisnost i povjerenje\"}, {\"text\": \"Ulažemo u vaše ciljeve i pružamo konkretne smjernice koje donose mjerljive rezultate.\", \"title\": \"Partner u rastu\"}], \"title\": \"Stvaramo vrijednost za naše klijente u svim fazama razvoja poslovanja.\"}, \"process\": {\"items\": [{\"text\": \"Razumijemo vaše ciljeve, izazove i okruženje kako bismo identificirali ključne prilike.\", \"title\": \"Upoznajemo vaš posao\"}, {\"text\": \"Analiziramo podatke i procese te kreiramo strategiju i konkretne korake prema ciljevima.\", \"title\": \"Analiziramo i planiramo\"}, {\"text\": \"Provodimo dogovorene aktivnosti uz kontinuirano praćenje i pravovremene prilagodbe.\", \"title\": \"Provodimo i pratimo\"}, {\"text\": \"Ostvarujemo mjerljive rezultate koji jačaju vašu poziciju i donose dugoročnu vrijednost.\", \"title\": \"Donosimo vrijednost\"}], \"title\": \"Jednostavan proces. Jasni koraci.\"}, \"services\": [{\"key\": \"audit\", \"url\": \"/revizija\", \"text\": \"Neovisna provjera financijskih izvještaja koja povećava povjerenje vlasnika, investitora i partnera.\", \"title\": \"Revizija\", \"bullets\": [\"Pomažemo vlasnicima, investitorima i upravi da imaju potpunu sigurnost u financijske izvještaje.\", \"Revizija smanjuje rizik pogrešnih odluka jer potvrđuje da su podaci točni, potpuni i u skladu s propisima.\", \"Kroz neovisnu provjeru dobivate jasnu sliku stvarnog financijskog stanja poduzeća, što jača povjerenje banaka, partnera i regulatora.\"], \"subtitle\": \"sigurnost i povjerenje u brojke\", \"image_alt\": \"Potpisivanje poslovnog dokumenta za stolom\", \"action_label\": \"SAZNAJTE VIŠE\"}, {\"key\": \"accounting\", \"url\": \"/racunovodstvo\", \"text\": \"Precizno vođenje knjiga i pravovremeno izvještavanje koje oslobađa menadžment za strateške odluke.\", \"title\": \"Računovodstvo\", \"bullets\": [\"Omogućujemo da vaše poslovanje bude financijski uredno, pregledno i uvijek spremno za odluke.\", \"To znači da u svakom trenutku imate točne podatke o prihodima, troškovima i rezultatu, bez kašnjenja i nejasnoća.\", \"Umjesto da reagirate na probleme, možete upravljati poslovanjem na temelju pouzdanih informacija.\"], \"subtitle\": \"kontrola i jasnoća poslovanja\", \"image_alt\": \"Rad na financijskim podacima na prijenosnom računalu\", \"action_label\": \"SAZNAJTE VIŠE\"}, {\"key\": \"advisory\", \"url\": \"/savjetovanje\", \"text\": \"Financijsko i porezno savjetovanje te pribavljanje kapitala - sve na jednom mjestu.\", \"title\": \"Savjetovanje\", \"bullets\": [\"Pomažemo društvima, investitorima i poduzetnicima u donošenju kvalitetnih odluka, upravljanju rizicima i stvaranju dugoročne vrijednosti.\", \"Pružamo podršku u procjenama vrijednosti, due diligence postupcima, M&A procesima i strukturiranju financiranja.\", \"EU fondovi, bankovni krediti i porezne olakšice povezani su u okviru pribavljanja financiranja.\"], \"subtitle\": \"rast, optimizacija i bolji financijski izbor\", \"image_alt\": \"Poslovni razgovor tijekom savjetovanja\", \"action_label\": \"SAZNAJTE VIŠE\"}], \"blog_source\": \"latest\", \"contact_cta\": {\"text\": \"Dogovorite uvodni sastanak s našim stručnjacima i pretvorite izazove u jasne, izvedive korake.\", \"title\": \"Razgovarajmo o sljedećoj fazi vašeg poslovanja.\", \"status\": \"Termin razgovora prilagođavamo vama.\", \"button_url\": \"/contact\", \"card_title\": \"Vrijeme je za pravi korak.\", \"button_label\": \"Dogovorite sastanak\"}, \"items_limit\": 6}', '2026-07-08 09:46:33', '2026-08-25 07:03:05'
FROM `content_blocks` AS `parent`
WHERE `parent`.`code` = 'home-alpha-services'
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `subtitle` = VALUES(`subtitle`), `body_html` = VALUES(`body_html`), `cta_label` = VALUES(`cta_label`), `cta_url` = VALUES(`cta_url`), `payload` = VALUES(`payload`), `updated_at` = VALUES(`updated_at`);

