SELECT `parent`.`id`, 'en', 'You run your business. We make sure your numbers keep pace with your growth.', NULL, NULL, NULL, NULL, '{\"news\": {\"title\": \"Deadlines, news and advice for safer business operations.\", \"all_posts_url\": \"/blog\", \"all_posts_label\": \"View all posts\", \"excerpt_fallback\": \"Read the latest deadlines, updates and expert advice for safer business decisions.\", \"category_fallback\": \"News\", \"post_action_label\": \"Read more\"}, \"values\": {\"intro\": \"ALPHA CAPITALIS provides you with security in your business, clarity in your finances, and a partner who helps you make better decisions, reduce risks, and achieve sustainable growth.\", \"items\": [{\"text\": \"Years of experience across a wide range of industries, combined with the highest standards of professional excellence.\", \"title\": \"Expertise and experience\"}, {\"text\": \"We are independent, objective, and committed to the highest professional and ethical standards.\", \"title\": \"Independence and trust\"}, {\"text\": \"We invest in your goals and provide practical guidance that delivers measurable results.\", \"title\": \"A partner in your growth\"}], \"title\": \"Creating value for our clients at every stage of business growth.\"}, \"process\": {\"items\": [{\"text\": \"We take the time to understand your goals, challenges and business environment to identify the opportunities that matter most.\", \"title\": \"Getting to know your business\"}, {\"text\": \"We analyse your data and processes, then develop a strategy and clear action steps aligned with your goals.\", \"title\": \"Analysing and planning\"}, {\"text\": \"We carry out the agreed activities, with continuous monitoring and timely adjustments along the way.\", \"title\": \"Delivering and monitoring\"}, {\"text\": \"We deliver measurable results that strengthen your position and create long-term value.\", \"title\": \"Creating value\"}], \"title\": \"We work as a team. Together, we move forward.\"}, \"services\": [{\"key\": \"audit\", \"url\": \"/audit\", \"text\": \"An independent review of financial statements that builds trust among owners, investors and partners.\", \"title\": \"Audit\", \"bullets\": [\"We help owners, investors and management gain confidence in financial statements.\", \"Audit reduces the risk of wrong decisions by confirming that data is accurate, complete and compliant.\", \"Through independent review you gain a clear view of the company financial position, strengthening trust with banks, partners and regulators.\"], \"subtitle\": \"confidence and trust in numbers\", \"image_alt\": \"Independent audit and financial statement review\", \"action_label\": \"LEARN MORE\"}, {\"key\": \"accounting\", \"url\": \"/accounting\", \"text\": \"Accurate bookkeeping and timely reporting that empower management to make strategic decisions.\", \"title\": \"Accounting\", \"bullets\": [\"We help keep your business financially organized, transparent and ready for decisions.\", \"That means accurate data on revenue, costs and results at any moment, without delays or uncertainty.\", \"Instead of reacting to problems, you can manage the business based on reliable information.\"], \"subtitle\": \"control and clarity in business\", \"image_alt\": \"Accounting and financial reporting\", \"action_label\": \"LEARN MORE\"}, {\"key\": \"advisory\", \"url\": \"/advisory\", \"text\": \"Financial and tax advisory, along with capital raising — all in one place.\", \"title\": \"Advisory\", \"bullets\": [\"We help companies, investors and entrepreneurs make better decisions, manage risk and create long-term value.\", \"We support valuations, due diligence, M&A processes and financing structuring.\", \"EU funds, bank loans and tax incentives are connected within the capital raising framework.\"], \"subtitle\": \"growth, optimisation and smarter financial decisions\", \"image_alt\": \"Business and financial advisory\", \"action_label\": \"LEARN MORE\"}], \"blog_source\": \"latest\", \"contact_cta\": {\"text\": \"Arrange an introductory meeting with our experts and turn challenges into clear, actionable steps.\", \"title\": \"Let’s talk about the next phase of your business.\", \"status\": \"We will arrange the meeting at a time that suits you.\", \"button_url\": \"/contact\", \"card_title\": \"It’s time for the right step.\", \"button_label\": \"Schedule a meeting\"}, \"items_limit\": 6}', '2026-07-08 09:46:33', '2026-08-25 07:03:05'
FROM `content_blocks` AS `parent`
WHERE `parent`.`code` = 'home-alpha-services'
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `subtitle` = VALUES(`subtitle`), `body_html` = VALUES(`body_html`), `cta_label` = VALUES(`cta_label`), `cta_url` = VALUES(`cta_url`), `payload` = VALUES(`payload`), `updated_at` = VALUES(`updated_at`);

INSERT INTO `content_service_page_translations` (`service_page_id`, `locale`, `title`, `slug`, `meta_title`, `meta_description`, `payload`, `created_at`, `updated_at`)
SELECT `parent`.`id`, 'hr', 'Revizija', 'revizija', 'Revizija', 'Revizija financijskih izvještaja, konsolidiranih izvještaja, uvidi, ESG i specijalizirani revizorski angažmani.', '{\"hero\": {\"intro\": \"Povjerenje u financijske informacije počinje neovisnom i stručnom revizijom.\", \"cta_url\": \"\", \"cta_label\": \"\", \"image_alt\": \"Revizija financijskih izvještaja\", \"brand_title\": \"ALPHA CAPITALIS\", \"subtitle_lead\": \"Revizija\", \"subtitle_accent\": \"\"}, \"value\": {\"intro\": \"Provedena revizija stvara dodanu vrijednost za upravu, vlasnike, banke i investitore jer pomaže u pravovremenom uočavanju slabosti, boljem upravljanju rizicima i kvalitetnijem odlučivanju.\", \"title\": \"Što revizija donosi društvu\", \"kicker\": \"VRIJEDNOST\", \"benefits\": [\"povećano povjerenje vlasnika, banaka i investitora\", \"smanjenje regulatornih i poslovnih rizika\", \"povećanje transparentnosti financijskih informacija\", \"pravovremeno uočavanje slabosti u procesima i kontrolama\", \"sigurnija podloga za donošenje poslovnih odluka\"], \"conclusion\": \"Revizija nije samo formalnost niti trošak. Ona je ulaganje u stabilnost, odgovorno poslovanje i dugoročnu vrijednost društva.\"}, \"meeting\": {\"intro\": \"Javite nam se - procijenit ćemo vaše potrebe i predložiti pristup koji odgovara veličini i specifičnostima vašeg poslovanja.\", \"title\": \"Razgovarajmo o vašem revizorskom angažmanu\", \"kicker\": \"KONTAKT\", \"status\": \"Termin razgovora prilagođavamo vama.\", \"submit\": \"Pošalji\", \"form_labels\": {\"email\": \"Email\", \"phone\": \"Broj telefona\", \"company\": \"Tvrtka\", \"message\": \"Poruka\", \"subject\": \"Naslov poruke\", \"last_name\": \"Prezime\", \"first_name\": \"Ime\"}, \"visit_lines\": [\"Ul. Roberta Frangeša Mihanovića 9,\", \"10110 Zagreb / Sky Office, 19. kat\"], \"visit_title\": \"Posjetite nas\", \"button_label\": \"Dogovorite sastanak\", \"contact_title\": \"Kontaktirajte nas\", \"direct_email_label\": \"Email\", \"direct_phone_label\": \"Telefon\"}, \"approach\": {\"body\": [\"Svaki revizijski angažman počinjemo s razumijevanjem vašeg poslovanja - ne s checklistom. Planiramo reviziju prema specifičnim rizicima vaše industrije i veličine, komuniciramo otvoreno kroz cijeli proces i zaključujemo jasnim mišljenjem bez iznenađenja.\"], \"intro\": \"Svaki revizijski angažman počinjemo s razumijevanjem vašeg poslovanja - ne s checklistom. Planiramo reviziju prema specifičnim rizicima vaše industrije i veličine, komuniciramo otvoreno kroz cijeli proces i zaključujemo jasnim mišljenjem bez iznenađenja.\", \"title\": \"Naš pristup\", \"kicker\": \"PRISTUP\", \"body_html\": \"<p>Svaki revizijski angažman počinjemo s razumijevanjem vašeg poslovanja - ne s checklistom. Planiramo reviziju prema specifičnim rizicima vaše industrije i veličine, komuniciramo otvoreno kroz cijeli proces i zaključujemo jasnim mišljenjem bez iznenađenja.</p>\"}, \"obligors\": {\"note\": \"Provedena revizija stvara dodanu vrijednost kako za upravu, tako i za vlasnike, banke i investitore, stoga ju društva mogu ugovoriti i dobrovoljno, kako bi unaprijedili svoje poslovanje.\", \"intro\": \"\", \"title\": \"Obveznici revizije\", \"kicker\": \"OBVEZNICI\", \"thresholds\": [\"prihodi iznad 30 mil. EUR\", \"imovina iznad 15 mil. EUR\", \"više od 25 zaposlenih\"], \"display_mode\": \"list\", \"primary_items\": [\"srednja i velika trgovačka društva\", \"društva od javnog interesa\", {\"text\": \"dionička društva, komanditna društva, društva s ograničenom odgovornošću koja u godini koja prethodi reviziji prelaze barem dva od sljedeća tri uvjeta:\", \"children\": [\"ukupna aktiva 2.500.000 eura\", \"ukupni prihod 5.000.000 eura\", \"prosječan broj zaposlenika tijekom poslovne godine iznosi najmanje 25\"], \"children_text\": \"ukupna aktiva 2.500.000 eura\\nukupni prihod 5.000.000 eura\\nprosječan broj zaposlenika tijekom poslovne godine iznosi najmanje 25\"}, \"društva uključena u statusne promjene\", \"korisnike EU sredstava kada je to propisano pravilima financiranja\", \"neprofitne organizacije koje su u prethodnoj godini ostvarile ukupan prihod veći od 398.168,43 eura do uključivo 1.327.228,08 eura (podliježu revizijskom uvidu)\", \"neprofitne organizacije koje su u prethodnoj godini ostvarile ukupan prihod veći od 1.327.228,08 eura (podliježu reviziji)\"], \"primary_title\": \"Revizija je zakonska obveza za:\", \"thresholds_intro\": \"Prag za obveznu reviziju primjenjuje se kada su zadovoljena 2 od 3 kriterija u 2 uzastopne godine:\", \"thresholds_title\": \"Prag za obveznu reviziju\"}, \"overview\": {\"body\": [\"Revizija pruža neovisnu i objektivnu procjenu financijskih informacija, povećava transparentnost i pouzdanost poslovanja te pomaže u prepoznavanju potencijalnih rizika.\", \"Neovisna revizija daje Vam sigurnost da odluke donosite na temelju pouzdanih informacija. Uz stručan i objektivan pristup, Vaše poslovanje sagledavamo šire od samih brojki.\"], \"intro\": \"\", \"title\": \"Zašto Vam je revizija bitna?\", \"kicker\": \"REVIZIJA\", \"body_html\": \"<p>Revizija pruža neovisnu i objektivnu procjenu financijskih informacija, povećava transparentnost i pouzdanost poslovanja te pomaže u prepoznavanju potencijalnih rizika.</p><p>Neovisna revizija daje Vam sigurnost da odluke donosite na temelju pouzdanih informacija. Uz stručan i objektivan pristup, Vaše poslovanje sagledavamo šire od samih brojki.</p>\", \"highlight_title\": \"Zašto Vam je revizija bitna?\"}, \"services\": {\"intro\": \"\", \"items\": [{\"text\": \"Revizija financijskih izvještaja u skladu sa Zakonom o reviziji i Međunarodnim revizijskim standardima. Neovisno i objektivno revizorsko mišljenje za veću vjerodostojnost financijskih informacija.\", \"title\": \"Revizija financijskih izvještaja\"}, {\"text\": \"Revizija konsolidiranih financijskih izvještaja grupa društava s fokusom na kvalitetu procesa konsolidacije i transparentnost izvještavanja.\", \"title\": \"Konsolidirani financijski izvještaji\"}, {\"text\": \"Uvid u financijske izvještaje i pregledi financijskih informacija koji pružaju ograničeno uvjerenje o pouzdanosti financijskih podataka.\", \"title\": \"Pregledi i uvidi\"}, {\"text\": \"Angažmani s izražavanjem ograničenog uvjerenja o izvještajima o održivosti i drugim nefinancijskim informacijama sukladno regulatornim zahtjevima i dobrim praksama.\", \"title\": \"Održivost i ESG\"}, {\"text\": \"Revizija financijskih izvještaja za posebne namjene, revizija EU projekata, revizija statusnih promjena i kapitala te ostali angažmani prilagođeni specifičnim potrebama klijenata.\", \"title\": \"Specijalizirani revizorski angažmani\"}, {\"text\": \"Procjena informacijskih sustava i IT kontrola s ciljem povećanja sigurnosti, pouzdanosti i učinkovitosti poslovnih procesa.\", \"title\": \"IT revizija\"}], \"title\": \"Naše revizijske usluge\", \"kicker\": \"USLUGE\"}, \"blog_section\": {\"intro\": \"Članci, novosti i stručni uvidi vezani uz reviziju, financijsko izvještavanje, kontrole i usklađenost.\", \"title\": \"Stručni uvidi u reviziju, izvještavanje i usklađenost\", \"kicker\": \"BLOG\", \"all_posts_label\": \"Pogledaj sve objave\", \"post_action_label\": \"Opširnije\"}, \"video_section\": {\"intro\": \"\", \"title\": \"\"}}', '2026-03-29 06:29:31', '2026-08-25 08:27:49'
FROM `content_service_pages` AS `parent`
WHERE `parent`.`code` = 'audit'
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `slug` = VALUES(`slug`), `meta_title` = VALUES(`meta_title`), `meta_description` = VALUES(`meta_description`), `payload` = VALUES(`payload`), `updated_at` = VALUES(`updated_at`);

INSERT INTO `content_service_page_translations` (`service_page_id`, `locale`, `title`, `slug`, `meta_title`, `meta_description`, `payload`, `created_at`, `updated_at`)
SELECT `parent`.`id`, 'en', 'Audit', 'audit', 'Audit', 'Audit of financial statements, consolidated statements, review engagements, ESG, and specialized audit engagements.', '{\"hero\": {\"intro\": \"Trust in financial information begins with an independent and professional audit.\", \"cta_url\": \"\", \"cta_label\": \"\", \"image_alt\": \"Financial statement audit\", \"brand_title\": \"ALPHA CAPITALIS\", \"subtitle_lead\": \"Audit\", \"subtitle_accent\": \"\"}, \"value\": {\"intro\": \"A completed audit creates added value for management, owners, banks, and investors by helping detect weaknesses early, manage risks better, and make better-informed decisions.\", \"title\": \"What an audit brings to a company\", \"kicker\": \"VALUE\", \"benefits\": [\"increased confidence of owners, banks, and investors\", \"reduction of regulatory and business risks\", \"greater transparency of financial information\", \"timely identification of weaknesses in processes and controls\", \"a stronger basis for business decision-making\"], \"conclusion\": \"An audit is not merely a formality or a cost. It is an investment in stability, responsible business operations, and long-term value.\"}, \"meeting\": {\"intro\": \"If you need a statutory audit, a special-purpose audit, or an independent review of financial information, reach out to us. Together, we can define the engagement scope, timing, and next steps.\", \"title\": \"Let’s discuss your audit engagement\", \"kicker\": \"CONTACT\", \"status\": \"We arrange the meeting around your schedule.\", \"submit\": \"Send\", \"form_labels\": {\"email\": \"Email\", \"phone\": \"Phone number\", \"company\": \"Company\", \"message\": \"Message\", \"subject\": \"Subject\", \"last_name\": \"Last name\", \"first_name\": \"First name\"}, \"visit_lines\": [\"Ul. Roberta Frangeša Mihanovića 9,\", \"10110 Zagreb / Sky Office, 19th floor\"], \"visit_title\": \"Visit us\", \"button_label\": \"Schedule a meeting\", \"contact_title\": \"Contact us\", \"direct_email_label\": \"Email\", \"direct_phone_label\": \"Phone\"}, \"approach\": {\"body\": [\"Every audit engagement starts with understanding your business - not with a checklist. We plan the audit around the specific risks of your industry and size, communicate openly throughout the process, and conclude with a clear opinion without surprises.\"], \"intro\": \"Every audit engagement starts with understanding your business - not with a checklist. We plan the audit around the specific risks of your industry and size, communicate openly throughout the process, and conclude with a clear opinion without surprises.\", \"title\": \"Our approach\", \"kicker\": \"APPROACH\", \"body_html\": \"<p>Every audit engagement begins with understanding your business — not with a checklist. We plan the audit around the specific risks of your industry and the size of your business, communicate openly throughout the entire process, and conclude with a clear opinion — without surprises.</p>\"}, \"obligors\": {\"note\": \"An audit creates added value for management, owners, banks and investors alike. Companies may therefore also choose to engage an auditor voluntarily in order to strengthen and improve their business operations.\", \"intro\": \"\", \"title\": \"Companies subject to statutory audit\", \"kicker\": \"OBLIGATIONS\", \"thresholds\": [\"total assets above EUR 2,500,000\", \"net revenue above EUR 5,000,000\", \"an average of at least 25 workers during the financial year\"], \"display_mode\": \"list\", \"primary_items\": [\"medium-sized and large companies\", \"public-interest entities\", {\"text\": \"joint-stock companies, limited partnerships, and limited liability companies that in the year preceding the audit exceed at least two of the following three criteria:\", \"children\": [\"total assets of EUR 2,500,000\", \"total revenue of EUR 5,000,000\", \"an average number of employees during the financial year of at least 25\"], \"children_text\": \"total assets of EUR 2,500,000\\ntotal revenue of EUR 5,000,000\\nan average number of employees during the financial year of at least 25\"}, \"companies involved in status changes\", \"EU funds beneficiaries when required by financing rules\", \"non-profit organizations whose total revenue in the previous year exceeded EUR 398,168.43 up to and including EUR 1,327,228.08 (subject to review)\", \"non-profit organizations whose total revenue in the previous year exceeded EUR 1,327,228.08 (subject to audit)\"], \"primary_title\": \"Audit is a statutory obligation for:\", \"thresholds_intro\": \"If the company is not already subject to audit on another basis, the obligation applies when it exceeds two of the following three criteria in the year preceding the audit:\", \"thresholds_title\": \"Thresholds for joint-stock, limited liability, and limited partnership companies\"}, \"overview\": {\"body\": [\"Audit provides an independent and objective assessment of financial information, increases transparency and reliability, and helps identify potential risks.\", \"An independent audit gives you confidence that your decisions are based on reliable information. Through an expert and objective approach, we look beyond the numbers to understand the wider context of your business.\"], \"intro\": \"\", \"title\": \"Why is an audit important to you?\", \"kicker\": \"AUDIT\", \"body_html\": \"<p>Audit provides an independent and objective assessment of financial information, enhances the transparency and reliability of your business, and helps identify potential risks.</p><p></p><p>An independent audit gives you confidence that your decisions are based on reliable information. With a professional and objective approach, we look at your business beyond the numbers.</p>\", \"highlight_title\": \"Why does audit matter to you?\"}, \"services\": {\"intro\": \"\", \"items\": [{\"text\": \"Audit of financial statements in accordance with the Audit Act and International Standards on Auditing. An independent and objective audit opinion enhances the credibility of financial information.\", \"title\": \"Financial Statement Audit\"}, {\"text\": \"Audit of consolidated financial statements of groups of companies, with a focus on the quality of the consolidation process and transparency of reporting.\", \"title\": \"Consolidated Financial Statements\"}, {\"text\": \"Reviews of financial statements and other financial information providing limited assurance on the reliability of financial data.\", \"title\": \"Reviews and Assurance\"}, {\"text\": \"Limited assurance engagements on sustainability reports and other non-financial information in accordance with regulatory requirements and good practices.\", \"title\": \"Sustainability and ESG\"}, {\"text\": \"Audits of financial statements prepared for special purposes, EU-funded projects, corporate restructurings and capital, as well as other engagements tailored to clients’ specific needs.\", \"title\": \"Specialised Audit Engagements\"}, {\"text\": \"Assessment of information systems and IT controls aimed at enhancing the security, reliability and efficiency of business processes.\", \"title\": \"IT Audit\"}], \"title\": \"Our audit services\", \"kicker\": \"SERVICES\"}, \"blog_section\": {\"intro\": \"Articles, updates, and expert insights related to audit, financial reporting, controls, and compliance.\", \"title\": \"Expert insights into audit, reporting and compliance\", \"kicker\": \"BLOG\", \"all_posts_label\": \"View all posts\", \"post_action_label\": \"Read more\"}, \"video_section\": {\"intro\": \"\", \"title\": \"\"}}', '2026-03-29 06:29:31', '2026-08-25 06:33:37'
FROM `content_service_pages` AS `parent`
WHERE `parent`.`code` = 'audit'
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `slug` = VALUES(`slug`), `meta_title` = VALUES(`meta_title`), `meta_description` = VALUES(`meta_description`), `payload` = VALUES(`payload`), `updated_at` = VALUES(`updated_at`);

INSERT INTO `content_service_page_translations` (`service_page_id`, `locale`, `title`, `slug`, `meta_title`, `meta_description`, `payload`, `created_at`, `updated_at`)
SELECT `parent`.`id`, 'hr', 'EU fondovi', 'eu-fondovi', 'EU fondovi', 'EU fondovi, natječaji, HBOR i HAMAG instrumenti te poticaji za ulaganja na jednom mjestu.', '{\"hero\": {\"intro\": \"Pomažemo poduzetnicima u identifikaciji, prijavi i provedbi projekata financiranih iz EU i nacionalnih izvora — od odabira natječaja do ishođenja ugovora i administrativnog praćenja provedbe.\", \"image_alt\": \"Savjetovanje i podrška za EU fondove\", \"brand_title\": \"ALPHA CAPITALIS\", \"subtitle_lead\": \"EU fondovi\", \"subtitle_accent\": \"\"}, \"laws\": {\"cards\": [{\"lists\": [{\"items\": [\"prihvatljivost prijavitelja i investicijskog projekta\", \"visina ulaganja i planirana nova radna mjesta\", \"razdoblje korištenja poreznih pogodnosti\"], \"label\": \"Najčešća područja provjere\", \"items_text\": \"prihvatljivost prijavitelja i investicijskog projekta\\nvisina ulaganja i planirana nova radna mjesta\\nrazdoblje korištenja poreznih pogodnosti\"}], \"title\": \"Zakon o poticanju ulaganja\", \"summary\": \"Pomažemo pri analizi uvjeta za korištenje poreznih olakšica i potpora za nova ulaganja.\", \"primary_link\": {\"slug\": \"zakon-o-poticanju-ulaganja-2\", \"type\": \"blog\", \"label\": \"Više informacija\"}, \"secondary_link\": {\"path\": \"front-theme/documents/eu-fondovi/zakon-o-poticanju-ulaganja-brosura.pdf\", \"type\": \"pdf\", \"label\": \"Brošura\"}}, {\"lists\": [{\"items\": [\"održivi, inovativni i otporni turizam\", \"zelena i digitalna tranzicija\", \"razvoj turističkog proizvoda visoke dodane vrijednosti\"], \"label\": \"Fokus potpore\", \"items_text\": \"održivi, inovativni i otporni turizam\\nzelena i digitalna tranzicija\\nrazvoj turističkog proizvoda visoke dodane vrijednosti\"}], \"title\": \"Uredba o turizmu\", \"summary\": \"Analiziramo mogućnosti korištenja potpora za ulaganja u turističke djelatnosti kada su primjenjive na konkretan projekt.\", \"primary_link\": {\"url\": \"https://narodne-novine.nn.hr/clanci/sluzbeni/2024_04_39_678.html\", \"type\": \"external\", \"label\": \"Narodne novine\"}}, {\"lists\": [{\"items\": [\"vrsta istraživačko-razvojne aktivnosti\", \"prihvatljivi troškovi projekta\", \"dokumentacija potrebna za korištenje potpore\"], \"label\": \"Područja analize\", \"items_text\": \"vrsta istraživačko-razvojne aktivnosti\\nprihvatljivi troškovi projekta\\ndokumentacija potrebna za korištenje potpore\"}], \"title\": \"Istraživačko-razvojni projekti\", \"summary\": \"Savjetujemo o korištenju državne potpore za istraživačko-razvojne projekte i povezanim poreznim olakšicama.\", \"primary_link\": {\"url\": \"https://narodne-novine.nn.hr/clanci/sluzbeni/2024_12_152_2519.html\", \"type\": \"external\", \"label\": \"Zakon o izmjenama i dopunama\"}}], \"intro\": \"Porezne olakšice i državne potpore mogu biti važan dio ukupne financijske konstrukcije investicijskog projekta.\", \"title\": \"Porezne olakšice, zakoni i uredbe\", \"kicker\": \"ZAKONI I UREDBE\"}, \"calls\": {\"intro\": \"Aktualni pozivi povlače se iz postojeće baze natječaja i prikazuju odvojeno od opisa savjetodavne usluge.\", \"title\": \"Natječaji prema statusu\", \"groups\": [], \"kicker\": \"NATJEČAJI\", \"download_link\": {\"type\": \"none\", \"label\": \"\"}, \"view_all_label\": \"Pogledaj sve natječaje\"}, \"meeting\": {\"intro\": \"Javite nam se i zajedno ćemo procijeniti koji su izvori financiranja dostupni za vaš projekt te koji je najprikladniji put prijave i provedbe.\", \"title\": \"Razgovarajmo o vašem projektu\", \"kicker\": \"KONTAKT\", \"status\": \"Termin razgovora prilagođavamo vama.\", \"button_label\": \"Dogovorite sastanak\", \"contact_title\": \"Kontaktirajte nas\"}, \"process\": {\"intro\": \"\", \"items\": [{\"text\": \"Analiziramo vaše investicijske i razvojne prioritete te ih povezujemo s odgovarajućim natječajima, kreditnim linijama i instrumentima potpore.\", \"title\": \"Analiza i odabir natječaja\"}, {\"text\": \"Pripremamo projektnu logiku, proračun, obrasce i svu prateću dokumentaciju potrebnu za kvalitetnu i pravodobnu prijavu.\", \"title\": \"Izrada projektne prijave\"}, {\"text\": \"Nakon odobrenja sredstava preuzimamo administrativno praćenje, komunikaciju s tijelima, izvještavanje i projektnu koordinaciju.\", \"title\": \"Provedba i koordinacija projekta\"}, {\"text\": \"Savjetujemo o HBOR kreditima, HAMAG zajmovima i ostalim instrumentima koji mogu biti komplementarni bespovratnim sredstvima.\", \"title\": \"Financijski instrumenti\"}, {\"text\": \"Pomažemo pri korištenju Zakona o poticanju ulaganja, Uredbe o turizmu i Zakona o državnoj potpori za istraživačko-razvojne projekte.\", \"title\": \"Zakonski poticaji i olakšice\"}, {\"text\": \"Kontinuirano pratimo nove pozive i pravovremeno vas obavještavamo o prilikama relevantnim za vaše poslovanje.\", \"title\": \"Praćenje natječaja\"}], \"title\": \"Naše usluge\", \"kicker\": \"USLUGE\"}, \"approach\": {\"body\": [\"Svaki angažman započinjemo razumijevanjem vaših investicijskih i razvojnih ciljeva. Analiziramo prihvatljivost projekta, dostupne izvore financiranja, rokove, uvjete natječaja i potrebnu dokumentaciju kako bismo procijenili realne mogućnosti prijave.\", \"Nakon odabira odgovarajućeg izvora financiranja, vodimo klijenta kroz pripremu projektne prijave, komunikaciju s nadležnim tijelima i administrativno praćenje provedbe. Cilj je povećati kvalitetu prijave, smanjiti rizik pogrešaka i omogućiti klijentu jasniji, sigurniji proces financiranja.\"], \"title\": \"Naš pristup\", \"kicker\": \"PRISTUP\", \"body_html\": \"<p>Svaki angažman započinjemo razumijevanjem vaših investicijskih i razvojnih ciljeva. Analiziramo prihvatljivost projekta, dostupne izvore financiranja, rokove, uvjete natječaja i potrebnu dokumentaciju kako bismo procijenili realne mogućnosti prijave.</p><p>Nakon odabira odgovarajućeg izvora financiranja, vodimo klijenta kroz pripremu projektne prijave, komunikaciju s nadležnim tijelima i administrativno praćenje provedbe. Cilj je povećati kvalitetu prijave, smanjiti rizik pogrešaka i omogućiti klijentu jasniji, sigurniji proces financiranja.</p>\"}, \"overview\": {\"body\": [\"EU fondovi su instrumenti financiranja kojima Europska unija podupire razvoj poduzetništva, inovacija, digitalne i zelene tranzicije te infrastrukture. Poduzetnicima su na raspolaganju bespovratna sredstva iz Višegodišnjeg financijskog okvira 2021.–2027., a uz EU programe dostupni su i nacionalni instrumenti potpore — HBOR krediti, HAMAG zajmovi te porezne olakšice temeljem Zakona o poticanju ulaganja i istraživačko-razvojnim projektima.\"], \"intro\": \"\", \"title\": \"Što su EU fondovi?\", \"kicker\": \"EU FONDOVI\", \"body_html\": \"<p>EU fondovi su instrumenti financiranja kojima Europska unija podupire razvoj poduzetništva, inovacija, digitalne i zelene tranzicije te infrastrukture. Poduzetnicima su na raspolaganju bespovratna sredstva iz Višegodišnjeg financijskog okvira 2021.–2027., a uz EU programe dostupni su i nacionalni instrumenti potpore — HBOR krediti, HAMAG zajmovi te porezne olakšice temeljem Zakona o poticanju ulaganja i istraživačko-razvojnim projektima.</p>\"}, \"resources\": {\"cards\": [{\"body\": [\"Prvi korak je razumjeti investicijske i razvojne prioritete projekta. Upitnik nam pomaže procijeniti prihvatljivost ulaganja i povezati ga s dostupnim izvorima financiranja.\"], \"title\": \"Projektni upitnik\", \"eyebrow\": \"ALPHA CAPITALIS\", \"body_html\": \"<p>Prvi korak je razumjeti investicijske i razvojne prioritete projekta. Upitnik nam pomaže procijeniti prihvatljivost ulaganja i povezati ga s dostupnim izvorima financiranja.</p>\", \"primary_link\": {\"url\": \"/eu-fondovi/upitnik\", \"type\": \"external\", \"label\": \"Ispuni upitnik\"}}, {\"body\": [\"HBOR kreditni programi mogu biti izvor financiranja za ulaganja, modernizaciju proizvodnje, energetsku učinkovitost, održivi turizam i druge razvojne projekte.\"], \"title\": \"HBOR krediti\", \"groups\": [{\"items\": [{\"link\": {\"type\": \"none\"}, \"title\": \"kreditiranje investicija i modernizacije poslovanja\"}, {\"link\": {\"type\": \"none\"}, \"title\": \"kombiniranje kredita s bespovratnim sredstvima kada je primjenjivo\"}], \"label\": \"Primjena\"}], \"eyebrow\": \"HBOR\", \"body_html\": \"<p>HBOR kreditni programi mogu biti izvor financiranja za ulaganja, modernizaciju proizvodnje, energetsku učinkovitost, održivi turizam i druge razvojne projekte.</p>\"}, {\"body\": [\"HAMAG-BICRO zajmovi i jamstva mogu biti korisna dopuna financijskoj strukturi, posebno za male i srednje poduzetnike koji planiraju provedbu ulaganja.\"], \"title\": \"HAMAG zajmovi\", \"groups\": [{\"items\": [{\"link\": {\"type\": \"none\"}, \"title\": \"zajmovi i jamstva za poduzetničke investicije\"}, {\"link\": {\"type\": \"none\"}, \"title\": \"dopunsko financiranje provedbe projekta\"}], \"label\": \"Primjena\"}], \"eyebrow\": \"HAMAG-BICRO\", \"body_html\": \"<p>HAMAG-BICRO zajmovi i jamstva mogu biti korisna dopuna financijskoj strukturi, posebno za male i srednje poduzetnike koji planiraju provedbu ulaganja.</p>\"}], \"intro\": \"Uz bespovratna sredstva poduzetnicima su dostupni i krediti, zajmovi te drugi instrumenti koji mogu biti komplementarni investicijskom planu.\", \"title\": \"HBOR, HAMAG i ostali izvori potpore\", \"kicker\": \"PROGRAMI I INSTRUMENTI\"}, \"blog_section\": {\"intro\": \"Aktualni natječaji, programske novosti i korisni savjeti za pripremu, prijavu i provedbu projekata financiranih iz EU fondova.\", \"title\": \"Objave iz kategorije :category\", \"all_posts_label\": \"Pogledaj sve objave\", \"post_action_label\": \"Opširnije\"}, \"testimonials\": {\"intro\": \"\", \"title\": \"Povjerenje gradimo kroz konkretne rezultate\", \"kicker\": \"PREPORUKE KLIJENATA\"}, \"video_section\": {\"intro\": \"\", \"title\": \"\"}, \"source_modules\": {\"intro\": \"Natječaji, financijski instrumenti i porezne olakšice prikazani su odvojeno od opisa usluge kako biste lakše pronašli relevantan izvor financiranja.\", \"items\": [{\"url\": \"#eu-funds-calls-open\", \"text\": \"Pregled trenutno otvorenih poziva s jasno označenim statusom i dostupnim detaljima.\", \"title\": \"Otvoreni natječaji\"}, {\"url\": \"#eu-funds-calls-pending\", \"text\": \"Pozivi koji su najavljeni i mogu biti relevantni za planiranje budućih ulaganja.\", \"title\": \"Natječaji u najavi\"}, {\"url\": \"#eu-funds-calls-closed\", \"text\": \"Arhivirani pozivi i programi koji mogu poslužiti kao orijentir za buduće cikluse financiranja.\", \"title\": \"Zatvoreni natječaji\"}, {\"url\": \"#eu-funds-programs\", \"text\": \"HBOR, HAMAG i drugi instrumenti koji mogu biti dopuna bespovratnim sredstvima.\", \"title\": \"Financijski instrumenti\"}, {\"url\": \"#eu-funds-laws\", \"text\": \"Poticaji, zakoni i uredbe koje mogu povećati isplativost planiranih ulaganja.\", \"title\": \"Porezne olakšice\"}, {\"url\": \"#eu-funds-programs\", \"text\": \"Kreditni izvori financiranja koji se mogu kombinirati s EU i nacionalnim potporama.\", \"title\": \"Bankovni krediti\"}], \"title\": \"Dostupni izvori financiranja\", \"kicker\": \"IZVORI FINANCIRANJA\"}}', '2026-03-31 07:24:03', '2026-08-25 08:27:49'
FROM `content_service_pages` AS `parent`
WHERE `parent`.`code` = 'eu-fondovi'
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `slug` = VALUES(`slug`), `meta_title` = VALUES(`meta_title`), `meta_description` = VALUES(`meta_description`), `payload` = VALUES(`payload`), `updated_at` = VALUES(`updated_at`);

INSERT INTO `content_service_page_translations` (`service_page_id`, `locale`, `title`, `slug`, `meta_title`, `meta_description`, `payload`, `created_at`, `updated_at`)
SELECT `parent`.`id`, 'en', 'EU Funds', 'eu-funds', 'EU Funds', 'EU funds, funding calls, investment incentives, and financing instruments in one place.', '{\"hero\": {\"intro\": \"We support businesses in identifying, applying for and implementing projects financed through EU and national funding sources — from selecting the right funding call to securing the grant agreement and managing the administrative requirements throughout implementation.\", \"image_alt\": \"EU funds advisory\", \"brand_title\": \"ALPHA CAPITALIS\", \"subtitle_lead\": \"EU Funds\", \"subtitle_accent\": \"\"}, \"laws\": {\"cards\": [{\"lists\": [{\"items\": [\"eligibility of the applicant and the investment project\", \"investment amount and planned creation of new jobs\", \"period during which tax incentives may be utilised\"], \"label\": \"Key areas we assess\", \"items_text\": \"eligibility of the applicant and the investment project\\ninvestment amount and planned creation of new jobs\\nperiod during which tax incentives may be utilised\"}], \"title\": \"Investment Promotion Act\", \"summary\": \"We help clients analyse the conditions for accessing tax incentives and support schemes for new investments.\", \"primary_link\": {\"slug\": \"zakon-o-poticanju-ulaganja-2\", \"type\": \"blog\", \"label\": \"More information\"}, \"secondary_link\": {\"path\": \"front-theme/documents/eu-fondovi/zakon-o-poticanju-ulaganja-brosura.pdf\", \"type\": \"pdf\", \"label\": \"Brochure\"}}, {\"lists\": [{\"items\": [\"sustainable, innovative and resilient tourism\", \"green and digital transition\", \"development of high-value-added tourism products\"], \"label\": \"Support focus\", \"items_text\": \"sustainable, innovative and resilient tourism\\ngreen and digital transition\\ndevelopment of high-value-added tourism products\"}], \"title\": \"Tourism Regulation\", \"summary\": \"We analyse opportunities to access support for investments in tourism activities where applicable to the specific project.\", \"primary_link\": {\"url\": \"https://narodne-novine.nn.hr/clanci/sluzbeni/2024_04_39_678.html\", \"type\": \"external\", \"label\": \"Official Gazette\"}}, {\"lists\": [{\"items\": [\"type of research and development activity\", \"eligible project costs\", \"documentation required to access the support\"], \"label\": \"Areas of analysis\", \"items_text\": \"type of research and development activity\\neligible project costs\\ndocumentation required to access the support\"}], \"title\": \"Research and Development Projects\", \"summary\": \"We advise clients on accessing state aid for research and development projects and related tax incentives.\", \"primary_link\": {\"url\": \"https://narodne-novine.nn.hr/clanci/sluzbeni/2024_12_152_2519.html\", \"type\": \"external\", \"label\": \"Act on Amendments\"}}], \"intro\": \"Tax incentives and state aid can form an important part of the overall financing structure of an investment project.\", \"title\": \"Tax incentives, legislation and regulations\", \"kicker\": \"ZAKONI I UREDBE\"}, \"calls\": {\"intro\": \"Current funding opportunities are drawn from our existing database and displayed separately from the description of our advisory services.\", \"title\": \"Funding calls by status\", \"groups\": [], \"kicker\": \"FUNDING CALLS\", \"download_link\": {\"type\": \"none\", \"label\": \"\"}, \"view_all_label\": \"View all funding calls\"}, \"meeting\": {\"intro\": \"Get in touch and together we will assess which sources of financing are available for your project and determine the most suitable approach to the application and implementation process.\", \"title\": \"Let’s talk about your project\", \"kicker\": \"KONTAKT\", \"status\": \"We will arrange the meeting at a time that suits you.\", \"button_label\": \"Schedule a meeting\", \"contact_title\": \"Contact us\"}, \"process\": {\"intro\": \"\", \"items\": [{\"text\": \"We analyse your investment and development priorities and match them with suitable funding calls, credit lines and support instruments.\", \"title\": \"Funding opportunity analysis and selection\"}, {\"text\": \"We prepare the project concept, budget, application forms and all supporting documentation required for a high-quality and timely application.\", \"title\": \"Project application preparation\"}, {\"text\": \"Once funding has been approved, we manage administrative monitoring, communication with the relevant authorities, reporting and project coordination.\", \"title\": \"Project implementation and coordination\"}, {\"text\": \"We advise on HBOR loans, HAMAG loans and other financing instruments that can complement grant funding.\", \"title\": \"Financial instruments\"}, {\"text\": \"We support clients in accessing incentives available under the Investment Promotion Act, the Tourism Regulation and the Act on State Aid for Research and Development Projects.\", \"title\": \"Statutory incentives and tax reliefs\"}, {\"text\": \"We continuously monitor new funding opportunities and keep you informed about programmes relevant to your business.\", \"title\": \"Funding call monitoring\"}], \"title\": \"Our services\", \"kicker\": \"USLUGE\"}, \"approach\": {\"body\": [\"Svaki angažman započinjemo razumijevanjem vaših investicijskih i razvojnih ciljeva. Analiziramo prihvatljivost projekta, dostupne izvore financiranja, rokove, uvjete natječaja i potrebnu dokumentaciju kako bismo procijenili realne mogućnosti prijave.\", \"Nakon odabira odgovarajućeg izvora financiranja, vodimo klijenta kroz pripremu projektne prijave, komunikaciju s nadležnim tijelima i administrativno praćenje provedbe. Cilj je povećati kvalitetu prijave, smanjiti rizik pogrešaka i omogućiti klijentu jasniji, sigurniji proces financiranja.\"], \"title\": \"Our approach\", \"kicker\": \"PRISTUP\", \"body_html\": \"<p>Every engagement begins with understanding your investment and development objectives. We analyse project eligibility, available funding sources, deadlines, funding conditions and required documentation to assess the realistic prospects of a successful application.</p><p></p><p>Once the appropriate source of funding has been identified, we guide the client through the preparation of the project application, communication with the relevant authorities and administrative monitoring of implementation. Our goal is to improve the quality of the application, reduce the risk of errors and provide the client with a clearer and more secure funding process.</p>\"}, \"overview\": {\"body\": [\"EU fondovi su instrumenti financiranja kojima Europska unija podupire razvoj poduzetništva, inovacija, digitalne i zelene tranzicije te infrastrukture. Poduzetnicima su na raspolaganju bespovratna sredstva iz Višegodišnjeg financijskog okvira 2021.–2027., a uz EU programe dostupni su i nacionalni instrumenti potpore — HBOR krediti, HAMAG zajmovi te porezne olakšice temeljem Zakona o poticanju ulaganja i istraživačko-razvojnim projektima.\"], \"intro\": \"\", \"title\": \"What are EU funds?\", \"kicker\": \"EU FONDOVI\", \"body_html\": \"<p>EU funds are financing instruments through which the European Union supports entrepreneurship, innovation, the digital and green transition, and infrastructure development. Businesses can access grants available under the 2021–2027 Multiannual Financial Framework. In addition to EU programmes, a range of national support instruments is also available, including HBOR loans, HAMAG loans and tax incentives under the Investment Promotion Act and legislation supporting research and development projects.</p>\"}, \"resources\": {\"cards\": [{\"body\": [\"Prvi korak je razumjeti investicijske i razvojne prioritete projekta. Upitnik nam pomaže procijeniti prihvatljivost ulaganja i povezati ga s dostupnim izvorima financiranja.\"], \"title\": \"Project Questionnaire\", \"eyebrow\": \"ALPHA CAPITALIS\", \"body_html\": \"<p>The first step is to understand the investment and development priorities of your project. The questionnaire helps us assess the eligibility of your investment and match it with available sources of financing.</p>\", \"primary_link\": {\"url\": \"/eu-fondovi/upitnik\", \"type\": \"external\", \"label\": \"Complete the questionnaire\"}}, {\"body\": [\"HBOR kreditni programi mogu biti izvor financiranja za ulaganja, modernizaciju proizvodnje, energetsku učinkovitost, održivi turizam i druge razvojne projekte.\"], \"title\": \"HBOR Loans\", \"groups\": [{\"items\": [{\"link\": {\"type\": \"none\"}, \"title\": \"financing investments and business modernisation\"}, {\"link\": {\"type\": \"none\"}, \"title\": \"combining loans with grants where applicable\"}], \"label\": \"Applications\"}], \"eyebrow\": \"HBOR\", \"body_html\": \"<p>HBOR loan programmes can provide financing for investments, production modernisation, energy efficiency, sustainable tourism and other development projects.</p>\"}, {\"body\": [\"HAMAG-BICRO zajmovi i jamstva mogu biti korisna dopuna financijskoj strukturi, posebno za male i srednje poduzetnike koji planiraju provedbu ulaganja.\"], \"title\": \"HAMAG Loans\", \"groups\": [{\"items\": [{\"link\": {\"type\": \"none\"}, \"title\": \"loans and guarantees for business investments\"}, {\"link\": {\"type\": \"none\"}, \"title\": \"supplementary financing for project implementation\"}], \"label\": \"Applications\"}], \"eyebrow\": \"HAMAG-BICRO\", \"body_html\": \"<p>HAMAG-BICRO loans and guarantees can be a useful addition to the financing structure, particularly for small and medium-sized enterprises planning new investments.</p>\"}], \"intro\": \"In addition to grants, businesses can access loans, guarantees and other financial instruments that can complement their investment plans.\", \"title\": \"HBOR, HAMAG and other sources of support\", \"kicker\": \"PROGRAMI I INSTRUMENTI\"}, \"blog_section\": {\"intro\": \"Aktualni natječaji, programske novosti i korisni savjeti za pripremu, prijavu i provedbu projekata financiranih iz EU fondova.\", \"title\": \"Expert insights into finance, tax and transactions\", \"all_posts_label\": \"View all posts\", \"post_action_label\": \"Read more\"}, \"testimonials\": {\"intro\": \"\", \"title\": \"Povjerenje gradimo kroz konkretne rezultate\", \"kicker\": \"PREPORUKE KLIJENATA\"}, \"video_section\": {\"intro\": \"\", \"title\": \"\"}, \"source_modules\": {\"intro\": \"Funding calls, financial instruments and tax incentives are presented separately from our advisory services so that you can more easily identify the source of financing most relevant to your needs.\", \"items\": [{\"url\": \"#eu-funds-calls-open\", \"text\": \"An overview of currently open calls, with their status and key details clearly presented.\", \"title\": \"Open Funding Calls\"}, {\"url\": \"#eu-funds-calls-pending\", \"text\": \"Announced funding calls that may be relevant when planning future investments.\", \"title\": \"Upcoming Funding Calls\"}, {\"url\": \"#eu-funds-calls-closed\", \"text\": \"Archived calls and programmes that can serve as a reference for future funding cycles.\", \"title\": \"Closed Funding Calls\"}, {\"url\": \"#eu-funds-programs\", \"text\": \"HBOR, HAMAG and other instruments that can complement grant funding.\", \"title\": \"Financial Instruments\"}, {\"url\": \"#eu-funds-laws\", \"text\": \"Incentives, legislation and regulations that can improve the financial viability of planned investments.\", \"title\": \"Tax Incentives\"}, {\"url\": \"#eu-funds-programs\", \"text\": \"Debt financing that can be combined with EU and national support schemes.\", \"title\": \"Bank Loans\"}], \"title\": \"Available sources of financing\", \"kicker\": \"IZVORI FINANCIRANJA\"}}', '2026-03-31 07:24:03', '2026-08-25 06:41:27'
FROM `content_service_pages` AS `parent`
WHERE `parent`.`code` = 'eu-fondovi'
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `slug` = VALUES(`slug`), `meta_title` = VALUES(`meta_title`), `meta_description` = VALUES(`meta_description`), `payload` = VALUES(`payload`), `updated_at` = VALUES(`updated_at`);

INSERT INTO `content_service_page_translations` (`service_page_id`, `locale`, `title`, `slug`, `meta_title`, `meta_description`, `payload`, `created_at`, `updated_at`)
SELECT `parent`.`id`, 'hr', 'Računovodstvo', 'racunovodstvo', 'Računovodstvo', 'Računovodstvena podrška, vođenje poslovnih knjiga, obračun plaća i izvještavanje za svakodnevno poslovanje.', '{\"hero\": {\"intro\": \"Vi vodite poslovanje. Mi brinemo da Vaše brojke budu točne, pravovremene i spremne za svaku odluku.\", \"cta_url\": \"\", \"cta_label\": \"\", \"image_alt\": \"Računovodstvene i financijske usluge\", \"brand_title\": \"ALPHA CAPITALIS\", \"subtitle_lead\": \"Računovodstvo\", \"subtitle_accent\": \"\"}, \"videos\": [], \"meeting\": {\"intro\": \"Svaki klijent dobiva računovođu koji poznaje vaš sektor i veličinu poslovanja. Javite se za besplatnu procjenu.\", \"title\": \"Razgovarajmo o vašem računovodstvu\", \"kicker\": \"KONTAKT\", \"status\": \"Termin razgovora prilagođavamo vama.\", \"submit\": \"Pošalji\", \"form_labels\": {\"email\": \"Email\", \"phone\": \"Broj telefona\", \"company\": \"Tvrtka\", \"message\": \"Poruka\", \"subject\": \"Naslov poruke\", \"last_name\": \"Prezime\", \"first_name\": \"Ime\"}, \"visit_lines\": [\"Ul. Roberta Frangeša Mihanovića 9,\", \"10110 Zagreb / Sky Office, 19. kat\"], \"visit_title\": \"Posjetite nas\", \"button_label\": \"Dogovorite sastanak\", \"contact_title\": \"Kontaktirajte nas\", \"direct_email_label\": \"Email\", \"direct_phone_label\": \"Telefon\"}, \"approach\": {\"body\": [\"Nismo samo servis za vođenje knjiga. Razumijemo vaše poslovanje i proaktivno upozoravamo na porezne prilike, regulatorne promjene i financijske rizike. Vaš računovođa dostupan je kada trebate - ne samo u sezoni godišnjih obračuna.\"], \"intro\": \"Nismo samo servis za vođenje knjiga. Razumijemo vaše poslovanje i proaktivno upozoravamo na porezne prilike, regulatorne promjene i financijske rizike. Vaš računovođa dostupan je kada trebate - ne samo u sezoni godišnjih obračuna.\", \"title\": \"Naš pristup\", \"kicker\": \"PRISTUP\", \"body_html\": \"<p>Nismo samo servis za vođenje knjiga. Razumijemo vaše poslovanje i proaktivno upozoravamo na porezne prilike, regulatorne promjene i financijske rizike. Vaš računovođa dostupan je kada trebate - ne samo u sezoni godišnjih obračuna.</p>\"}, \"overview\": {\"body\": [\"Mirnije poslovanje počinje jasnim i pouzdanim brojkama. Ažurne financijske informacije daju Vam kontrolu nad poslovanjem, pomažu prepoznati prilike i rizike te donijeti sigurnije odluke.\", \"Uz ALPHA CAPITALIS ne dobivate samo računovodstvenu uslugu, već pouzdanog partnera koji razumije Vaše poslovanje i prati Vas kroz svakodnevne izazove i planove rasta.\"], \"intro\": \"\", \"title\": \"Zašto Vam je računovodstvo bitno?\", \"kicker\": \"RAČUNOVODSTVO\", \"body_html\": \"<p><strong>Mirnije poslovanje počinje jasnim i pouzdanim brojkama.</strong> Ažurne financijske informacije daju Vam kontrolu nad poslovanjem, pomažu prepoznati prilike i rizike te donijeti sigurnije odluke.</p>\", \"highlight_title\": \"Zašto Vam je računovodstvo bitno?\", \"partner_body_html\": \"<p>Uz ALPHA CAPITALIS ne dobivate samo računovodstvenu uslugu, već pouzdanog partnera koji razumije Vaše poslovanje i prati Vas kroz svakodnevne izazove i planove rasta.</p>\"}, \"services\": {\"intro\": \"\", \"items\": [{\"text\": \"Vođenje poslovnih knjiga, financijski izvještaji i godišnji obračuni prema hrvatskim propisima i MSFI.\", \"title\": \"Financijsko računovodstvo\"}, {\"text\": \"Kompletan obračun plaća, naknada i putnih troškova. Prijave poreza i doprinosa. JOPPD obrasci.\", \"title\": \"Obračun plaća\"}, {\"text\": \"Izrada i predaja svih poreznih prijava: PDV, porez na dobit i godišnji obračun. Pravovremeno i bez propusta.\", \"title\": \"Porezne prijave\"}, {\"text\": \"Prilagođeni financijski izvještaji za menadžment - jasni, vizualni i fokusirani na bitne pokazatelje.\", \"title\": \"Upravljačko izvještavanje\"}, {\"text\": \"Podrška pri osnivanju društva, izboru pravnog oblika i uspostavi računovodstvenog sustava od prvog dana.\", \"title\": \"Osnivanje i registracija\"}, {\"text\": \"Izrada konsolidiranih financijskih izvještaja za grupe društava. Usklađivanje internih transakcija i eliminacija.\", \"title\": \"Konsolidacija\"}], \"title\": \"Naše računovodstvene usluge\", \"kicker\": \"USLUGE\"}, \"blog_section\": {\"empty\": \"Novosti iz ove kategorije uskoro će biti dostupne.\", \"intro\": \"Pratite novosti, stručne članke i praktične uvide vezane uz računovodstvo, izvještavanje i svakodnevno financijsko upravljanje.\", \"title\": \"Stručni uvidi u računovodstvo, izvještavanje i poslovne brojke\", \"kicker\": \"NOVOSTI\", \"all_posts_label\": \"Pogledaj sve objave\", \"post_action_label\": \"Opširnije\"}, \"intro_section\": {\"body\": [\"Isplata i obračun plaća stvaraju Vam administrativne probleme? Sumnjate u ispravnost financijskih izvještaja ili pak smatrate da ste bili podložni nekom obliku računovodstvene prijevare? Potrebna Vam je kvalitetna priprema i kontrola financijskih izvještaja? Tim ALPHA CAPITALIS ima rješenje za Vaše probleme.\", \"Usluge Računovodstva:\"], \"items\": [\"Vođenje poslovnih knjiga\", \"Obračun plaća\", \"Izvještavanje\", \"Rent-a-računovođa\", \"Računovodstvo za strane investitore\", \"Registracija trgovačkih društava\", \"Forenzičko računovodstvo\"], \"title\": \"Usluge Računovodstva\", \"kicker\": \"RAČUNOVODSTVO\", \"video_url\": \"\", \"video_title\": \"\"}, \"video_section\": {\"intro\": \"\", \"title\": \"\"}, \"detail_sections\": [{\"icon\": \"book-open\", \"slug\": \"vodenje-poslovnih-knjiga\", \"intro\": \"Kroz uredno i pravodobno vođenje poslovnih knjiga osiguravamo pouzdanu evidenciju poslovnih promjena, pregled obveza i kvalitetnu podlogu za financijsko odlučivanje.\", \"items\": [\"Evidentiranje knjigovodstvene dokumentacije u poslovne knjige: glavne knjige, knjige ulaznih i izlaznih računa, blagajne i izvoda.\", \"Analitičko praćenje poslovnih promjena na salda kontima dobavljača, kupaca, mjestima troška te profitnim centrima.\", \"Izrada i obračun PDV prijava (mjesečno / kvartalno) te izvještavanje za potrebe porezne uprave preko sustava e-Porezna.\", \"Dodatne usluge uključuju izdavanje računa, plaćanje računa internet bankarstvom, izradu kompenzacija i cesija te pripremu dokumentacije za natječaje, poticaje, kredite i leasing.\"], \"quote\": \"Pouzdano vođene poslovne knjige daju jasnu sliku poslovanja, obveza i novčanih tokova.\", \"title\": \"Vođenje poslovnih knjiga\", \"cta_url\": \"#accounting-sastanak\", \"cta_text\": \"Za više informacija, slobodno nas kontaktirajte\", \"cta_label\": \"Pošaljite upit\", \"list_title\": \"Vođenje poslovnih knjiga odnosi se na sljedeće:\"}, {\"icon\": \"file-lines\", \"slug\": \"obracun-placa\", \"intro\": \"Ovom uslugom prepuštate brigu oko plaća našim stručnim ljudima koji ažurno i aktivno prate aktualne promjene zakona poreza na dohodak i zakona o radu, za koje vas pravodobno informiramo.\", \"items\": [\"Pružamo potpuno individualno savjetovanje o obračunu plaća, prikupljanje i obradu podataka s naglaskom na čuvanju povjerljivih osobnih podataka.\", \"Obračunavamo neoporezive isplate (božićnice, uskrsnice, regresi i otpremnine), plaću u naravi, bolovanje na teret društva i HZZO-a, honorare vanjskih suradnika te putne naloge.\", \"Izrada poreznih i statističkih izvještaja o isplatama plaća i drugih primitaka (JOPPD, IP).\", \"Prijava i odjava zaposlenika na mirovinsko i zdravstveno osiguranje.\"], \"quote\": \"Točan i pravodoban obračun plaća smanjuje rizik pogrešaka i administrativno opterećenje.\", \"title\": \"Obračun plaća\", \"cta_url\": \"#accounting-sastanak\", \"cta_text\": \"Za više informacija, slobodno nas kontaktirajte\", \"cta_label\": \"Pošaljite upit\"}, {\"icon\": \"chart-line\", \"slug\": \"izvjestavanje\", \"intro\": \"Pripremamo obvezne i upravljačke izvještaje koji osiguravaju zakonsku usklađenost, bolji pregled poslovanja i kvalitetnu podlogu za donošenje odluka.\", \"items\": [\"Na kraju poslovne godine potrebno je napraviti obvezno izvještavanje prema državi, koje se odnosi na godišnje izvještaje, a obvezni su po zakonu o računovodstvu, porezu na dobit, dohodak i dodanu vrijednost.\", \"Obvezni godišnji izvještaji su: godišnja prijava poreza na dobit (PD), bilanca stanja i statistički izvještaj (GFI-POD), račun dobiti i gubitka (RDG) i popratni izvještaj (šuma i turističke zajednice).\", \"Za donošenje važnih poslovnih odluka potrebne su točne i pravodobne informacije analizirane u izvještajima. Za potrebe naših klijenata kreiramo tjedne, mjesečne, tromjesečne i godišnje izvještaje u standardnim formatima.\", \"Za upravljanje likvidnošću radimo tjedni i mjesečni izvještaj plaćenih računa (otvorene stavke kupaca i dobavljača), te praćenje strukture troškova na mjesečnoj razini.\", \"Za potrebe izvještavanja moguće je uspostaviti praćenje profitabilnosti po projektima, odjelima, centrima ili praćenje troškova po mjestima.\"], \"quote\": \"Kvalitetno izvještavanje pretvara zakonsku obvezu u alat za upravljanje poslovanjem.\", \"title\": \"Izvještavanje\", \"cta_url\": \"#accounting-sastanak\", \"cta_text\": \"Za više informacija, slobodno nas kontaktirajte\", \"cta_label\": \"Pošaljite upit\", \"downloads\": [{\"url\": \"https://alphacapitalis.com/wp-content/uploads/2019/07/manipulacija-financijskim-izvjestajima-alpha-capitalis-akademija-predavanje-18-06-2019.pdf\", \"label\": \"Preuzmi\", \"title\": \"Manipulacija financijskim izvještajima\"}, {\"url\": \"https://alphacapitalis.com/wp-content/uploads/2019/07/analiza-financijskih-izvjestaja-alpha-capitalis-akademija-predavanje-18-06-2019.pdf\", \"label\": \"Preuzmi\", \"title\": \"Analiza financijskih izvještaja\"}]}, {\"icon\": \"briefcase\", \"slug\": \"rent-a-racunovoda\", \"intro\": \"Kupili ste novi računovodstveni sustav te želite prenijeti poslovanje pouzdano i sigurno? Želite dodatno obučiti zaposlenike kako bi bili sigurni da mogu samostalno rješavati sve zadatke? Poslovanje vam raste i trebate računovođu na određeni kratki period?\", \"items\": [\"Ova usluga omogućuje upravo to, unajmljivanje računovođe s ciljem rješavanja tih kratkoročnih problema.\", \"Naši ljudi su stručnjaci s dugogodišnjim iskustvom u različitim sustavima, te organiziranjem i uspostavljanjem sustava u nekoliko cijenjenih društava.\", \"U slučaju manjka računovodstvenog kadra nudimo mogućnost „najma“ računovodstvenog djelatnika kako bi društvo nastavilo poslovati do uspostavljanja stabilnog poslovanja.\"], \"quote\": \"Kada vam treba brzo računovodstveno pojačanje, uključujemo se bez prekida poslovanja.\", \"title\": \"Rent-a-računovođa\", \"cta_url\": \"#accounting-sastanak\", \"cta_text\": \"Za više informacija, slobodno nas kontaktirajte\", \"cta_label\": \"Pošaljite upit\"}, {\"icon\": \"user-group\", \"slug\": \"racunovodstvo-za-strane-investitore\", \"intro\": \"Strani ste investitor s kapitalom i idejom, ali niste u mogućnosti obavljati sve procese nužne za vođenje poslovanja u Hrvatskoj? Naše računovodstvo će vam pomoći i s ovim problemom kroz sljedeće usluge:\", \"items\": [\"Osnivanje trgovačkog društva.\", \"Vođenje svih poslovnih knjiga trgovačkog društva.\", \"Upravljanje društvom.\", \"Zaprimanje pošte i pružanje adrese sjedišta društva.\", \"Zastupanje društva pred poreznom upravom.\", \"Redovito izvještavanje menadžmenta o stanju poslovanja.\"], \"quote\": \"Stranim investitorima omogućujemo stabilan lokalni operativni i računovodstveni oslonac.\", \"title\": \"Računovodstvo za strane investitore\", \"cta_url\": \"#accounting-sastanak\", \"cta_text\": \"Za više informacija, slobodno nas kontaktirajte\", \"cta_label\": \"Pošaljite upit\"}, {\"icon\": \"building-columns\", \"slug\": \"registracija-trgovackih-drustava\", \"intro\": \"Cjelokupni proces registracije društva još uvijek nije toliko jednostavan koliko se teži da bude. Pružamo vam podršku i vodimo vas kroz cijeli proces formiranja bilo kojeg pravnog oblika za obnašanje vaše buduće poslovne djelatnosti.\", \"items\": [\"Prvi korak pri registraciji trgovačkog društva je davanje imena društvu. Ime društva ne smije već biti korišteno od strane postojećih trgovačkih društava. Stoga, potrebno je imati unaprijed pripremljenu listu prihvatljivih imena ako je primarno ime već korišteno.\", \"Posjet javnom bilježniku. Prijavu za upis u sudski registar i niz dodatnih dokumenata potrebno je ovjeriti kod javnog bilježnika.\", \"Osim dokumentacije ovjerene kod javnoga bilježnika, u FINI-i će trebati dostaviti još nekoliko dokumenata poput popisa članova društva, popisa članova ovlaštenih za zastupanje društva i potvrde o uplati osnivačkog pologa.\", \"Preuzimanje dodatne dokumentacije u FINI, nakon čega se mora izraditi pečat i otvoriti račun u banci.\", \"Prijava društva u poreznoj upravi sa svom pripadajućom dokumentacijom.\", \"Najkasnije 15 dana od početka obavljanja djelatnosti društvo treba prijaviti u HZZO i HZMO.\"], \"quote\": \"Vodimo vas kroz registraciju društva korak po korak, uz jasnu pripremu dokumentacije i procesa.\", \"title\": \"Registracija trgovačkih društava\", \"cta_url\": \"#accounting-sastanak\", \"cta_text\": \"Za više informacija, slobodno nas kontaktirajte\", \"cta_label\": \"Pošaljite upit\", \"list_title\": \"Navodimo ključne korake kod registracije trgovačkog društva:\"}, {\"icon\": \"magnifying-glass\", \"slug\": \"forenzicko-racunovodstvo\", \"intro\": \"Poslovanje se brzo mijenja, a prijetnje u obliku prijevare, korupcije i pranja novca te njihove moguće posljedice za ugled i financije, ali i pravne posljedice, dio su svakodnevice.\", \"items\": [\"Imali ste krađu, nestala je ključna računovodstvena dokumentacija, menadžment manipulira financijskim izvještajima ili osjećate da ste žrtva korporativne prijevare.\", \"Član ste nadzornog odbora i vjerujete da menadžment manipulira financijskim izvještajima.\", \"Preuzeli ste poslovanje i želite napraviti primopredaju i utvrditi početno stanje.\", \"U procesu ste arbitraže ili sudskog spora i potrebno je neovisno vještačenje financijske i računovodstvene dokumentacije.\"], \"quote\": \"Neovisan pogled izvana ključan je za objektivno sagledavanje sumnji, rizika i financijskih nepravilnosti.\", \"title\": \"Forenzičko računovodstvo\", \"cta_url\": \"#accounting-sastanak\", \"cta_text\": \"Za više informacija, slobodno nas kontaktirajte\", \"cta_label\": \"Pošaljite upit\", \"after_list\": [\"Naše forenzičko računovodstvo pomaže u rješavanju gore navedenih problema. Ključ uspješnog provođenja forenzičkog računovodstva leži u eksternom pogledu na cijelu situaciju. U prijevodu, zaposlenici organizacije često neće potpuno racionalno i objektivno sagledati sve aspekte poslovanja te je nužan neovisan pogled „izvana“.\"], \"list_title\": \"Kada vam je potrebno forenzičko računovodstvo?\"}], \"editorial_section\": {\"cards\": [{\"body\": \"U potpunosti razumijemo Vašu brigu o netočnosti financijskih izvještaja. Osim što taj problem zadaje uznemirenost među ljudima te manjak povjerenja, financijska šteta koju može prouzročiti je i više nego očita. Naši računovodstveni stručnjaci s dugogodišnjom ekspertizom u tom području rado će preuzeti izradu Vaših financijskih izvještaja te Vam omogućiti fokus na primarne aktivnosti poslovanja.\", \"icon\": \"file-lines\", \"title\": \"Vodimo brigu o točnosti Vaših financijskih izvještaja\"}, {\"body\": \"Sve naše usluge računovodstva provodimo u skladu s računovodstvenim politikama društva, hrvatskim i međunarodnim računovodstvenim standardima (HSFI i MSFI) te poreznim i drugim zakonima.\", \"icon\": \"scale-balanced\", \"title\": \"Pratimo računovodstvene standarde, zakonske propise i standarde financijskog izvještavanja\"}, {\"body\": \"Naša usluga usmjerena je Vama kao podrška u financijskim aktivnostima Vašeg društva. Od samog osnivanja društva uz Vas smo kako bismo Vam pomogli u donošenju financijskih odluka na temelju točnih i ažurnih podataka, prilagođenih računovodstvenim standardima i zakonskim zahtjevima.\", \"icon\": \"chart-line\", \"title\": \"Pružamo podršku kod donošenja financijskih odluka\"}, {\"body\": \"Djelujemo kao Vaši financijski savjetnici te u skladu sa specifičnim financijskim potrebama prilagođavamo svoju ulogu u cilju zadovoljavanja istih. U nastojanju da osiguramo kvalitetnu uslugu i zadovoljstvo klijenta, uveli smo ISO standard upravljanja kvalitetom 9001:2015. Nadalje, naš tim posjeduje stručne certifikate i kontinuirano se educira kroz vanjske i interne edukacije kako bi za naše klijente bio kompas kroz svijet financija.\", \"icon\": \"book-open\", \"title\": \"Kroz kontinuirani razvoj osiguravamo kvalitetu usluge\"}], \"title\": \"Prepustite nam računovodstvo\", \"eyebrow\": \"ALPHA CAPITALIS\", \"subtitle\": \"Vi se fokusirajte na kvalitetno i predano vođenje poslovanja, ostvarenje dobiti i stvaranje nove ekonomske vrijednosti.\"}, \"bookkeeping_section\": {\"slug\": \"vodenje-poslovnih-knjiga\", \"intro\": \"Kroz uredno i pravodobno vođenje poslovnih knjiga osiguravamo pouzdanu evidenciju poslovnih promjena, pregled obveza i kvalitetnu podlogu za financijsko odlučivanje.\", \"items\": [\"Evidentiranje knjigovodstvene dokumentacije u poslovne knjige: glavne knjige, knjige ulaznih i izlaznih računa, blagajne i izvoda.\", \"Analitičko praćenje poslovnih promjena na salda kontima dobavljača, kupaca, mjestima troška te profitnim centrima.\", \"Izrada i obračun PDV prijava (mjesečno / kvartalno) te izvještavanje za potrebe porezne uprave preko sustava e-Porezna.\", \"Dodatne usluge uključuju izdavanje računa, plaćanje računa internet bankarstvom, izradu kompenzacija i cesija te pripremu dokumentacije za natječaje, poticaje, kredite i leasing.\"], \"title\": \"Vođenje poslovnih knjiga\", \"cta_url\": \"#accounting-sastanak\", \"cta_text\": \"Za više informacija o vođenju poslovnih knjiga i modelu suradnje, slobodno nas kontaktirajte.\", \"cta_label\": \"Pošaljite upit\", \"list_title\": \"Vođenje poslovnih knjiga odnosi se na sljedeće:\"}}', '2026-03-31 13:12:47', '2026-08-25 08:31:40'
FROM `content_service_pages` AS `parent`
WHERE `parent`.`code` = 'racunovodstvo'
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `slug` = VALUES(`slug`), `meta_title` = VALUES(`meta_title`), `meta_description` = VALUES(`meta_description`), `payload` = VALUES(`payload`), `updated_at` = VALUES(`updated_at`);

INSERT INTO `content_service_page_translations` (`service_page_id`, `locale`, `title`, `slug`, `meta_title`, `meta_description`, `payload`, `created_at`, `updated_at`)
SELECT `parent`.`id`, 'en', 'Accounting', 'accounting', 'Accounting', 'Accounting support, bookkeeping, payroll processing, and reporting for day-to-day business operations.', '{\"hero\": {\"intro\": \"You run your business. We make sure your numbers are accurate, timely and ready for every decision.\", \"cta_url\": \"\", \"cta_label\": \"\", \"image_alt\": \"Accounting and financial services\", \"brand_title\": \"ALPHA CAPITALIS\", \"subtitle_lead\": \"Accounting\", \"subtitle_accent\": \"\"}, \"videos\": [], \"meeting\": {\"intro\": \"Every client gets an accountant who understands their sector and company size. Reach out for a free assessment.\", \"title\": \"Let’s discuss your accounting\", \"kicker\": \"CONTACT\", \"status\": \"We arrange the meeting around your schedule.\", \"submit\": \"Send\", \"form_labels\": {\"email\": \"Email\", \"phone\": \"Phone number\", \"company\": \"Company\", \"message\": \"Message\", \"subject\": \"Subject\", \"last_name\": \"Last name\", \"first_name\": \"First name\"}, \"visit_lines\": [\"Ul. Roberta Frangeša Mihanovića 9,\", \"10110 Zagreb / Sky Office, 19th floor\"], \"visit_title\": \"Visit us\", \"button_label\": \"Schedule a meeting\", \"contact_title\": \"Contact us\", \"direct_email_label\": \"Email\", \"direct_phone_label\": \"Phone\"}, \"approach\": {\"body\": [\"We are not only a bookkeeping service. We understand your business and proactively point out tax opportunities, regulatory changes, and financial risks. Your accountant is available when you need them - not only during annual closing season.\"], \"intro\": \"We are not only a bookkeeping service. We understand your business and proactively point out tax opportunities, regulatory changes, and financial risks. Your accountant is available when you need them - not only during annual closing season.\", \"title\": \"Our approach\", \"kicker\": \"APPROACH\", \"body_html\": \"<p>We are more than just a bookkeeping service. We understand your business and proactively alert you to tax opportunities, regulatory changes and financial risks. Your accountant is available when you need them — not just during the annual reporting season.</p>\"}, \"overview\": {\"body\": [\"Calmer business operations begin with clear and reliable numbers. Up-to-date financial information gives you control over your business, helps you identify opportunities and risks, and supports more confident decisions.\", \"With ALPHA CAPITALIS, you get more than an accounting service - you get a reliable partner who understands your business and supports you through everyday challenges and growth plans.\"], \"intro\": \"\", \"title\": \"Why is accounting important to you?\", \"kicker\": \"ACCOUNTING\", \"body_html\": \"<p>Greater peace of mind starts with clear and reliable numbers. Up-to-date financial information gives you greater control over your business, helps you identify opportunities and risks, and enables you to make more confident decisions.</p>\", \"highlight_title\": \"Why does accounting matter to you?\", \"partner_body_html\": \"<p>With ALPHA CAPITALIS, you get more than just accounting services — you gain a reliable partner who understands your business and supports you through everyday challenges and your plans for growth.</p>\"}, \"services\": {\"intro\": \"\", \"items\": [{\"text\": \"Bookkeeping, financial statements and annual accounts in accordance with Croatian regulations and IFRS.\", \"title\": \"Financial Accounting\"}, {\"text\": \"Support with tax planning, compliance, tax reviews, transfer pricing, tax audits and transactions.\", \"title\": \"Tax Advisory\"}, {\"text\": \"Complete payroll, benefits and travel expense calculations, including tax and contribution filings and JOPPD forms.\", \"title\": \"Payroll\"}, {\"text\": \"Preparation and submission of all tax returns, including VAT, corporate income tax and annual tax filings. Timely and accurate.\", \"title\": \"Tax Returns\"}, {\"text\": \"Tailored financial reports for management — clear, visual and focused on key performance indicators.\", \"title\": \"Management Reporting\"}, {\"text\": \"Support with company formation, choosing the appropriate legal structure and setting up the accounting system from day one.\", \"title\": \"Company Formation & Registration\"}], \"title\": \"Our accounting services\", \"kicker\": \"SERVICES\"}, \"blog_section\": {\"empty\": \"Posts from this category will be available soon.\", \"intro\": \"Explore updates, articles, and practical insights related to accounting, reporting, and day-to-day financial operations.\", \"title\": \"Expert insights into accounting, reporting and business figures\", \"kicker\": \"INSIGHTS\", \"all_posts_label\": \"View all posts\", \"post_action_label\": \"Read more\"}, \"intro_section\": {\"body\": [\"Are payroll processing and salary calculations creating administrative pressure? Do you question the accuracy of your financial statements, or suspect exposure to some form of accounting irregularity or fraud? Do you need reliable preparation and control of your financial reports? The ALPHA CAPITALIS team has a solution.\", \"Accounting services:\"], \"items\": [\"Bookkeeping\", \"Payroll processing\", \"Reporting\", \"Rent-an-accountant\", \"Accounting for foreign investors\", \"Company registration support\", \"Forensic accounting\"], \"title\": \"Accounting services\", \"kicker\": \"ACCOUNTING\", \"video_url\": \"\", \"video_title\": \"\"}, \"video_section\": {\"intro\": \"\", \"title\": \"\"}, \"detail_sections\": [{\"icon\": \"book-open\", \"slug\": \"bookkeeping\", \"intro\": \"With timely and structured bookkeeping, we provide reliable records of business changes, better visibility into obligations, and a stronger basis for financial decision-making.\", \"items\": [\"Recording accounting documentation in the core books: general ledger, incoming and outgoing invoice ledgers, cash records, and bank statements.\", \"Analytical monitoring of business changes across supplier and customer balances, cost centers, and profit centers.\", \"Preparing and filing VAT returns (monthly / quarterly), including reporting through the e-Tax administration system.\", \"Additional services include invoice issuance, internet banking payment support, compensation and assignment documentation, and preparation of documents for grants, incentives, loans, and leasing.\"], \"quote\": \"Reliable bookkeeping gives management a clearer view of operations, obligations, and cash flow.\", \"title\": \"Bookkeeping\", \"cta_url\": \"#accounting-sastanak\", \"cta_text\": \"For more information, feel free to contact us.\", \"cta_label\": \"Send an inquiry\", \"list_title\": \"Bookkeeping covers the following activities:\"}, {\"icon\": \"file-lines\", \"slug\": \"payroll-processing\", \"intro\": \"By using this service, you hand over payroll administration to our experts who continuously monitor legislative changes related to personal income tax and labor law and keep you informed on time.\", \"items\": [\"We provide fully individualized payroll advisory, data collection, and processing with a strong focus on safeguarding confidential personal data.\", \"We calculate non-taxable payments, benefits in kind, sick leave charged to the company and the public health fund, external contractor fees, and travel expenses.\", \"Preparation of tax and statistical payroll reports and other payment-related filings.\", \"Registration and deregistration of employees with pension and health insurance authorities.\"], \"quote\": \"Accurate and timely payroll processing reduces risk, protects confidentiality, and eases the administrative burden.\", \"title\": \"Payroll processing\", \"cta_url\": \"#accounting-sastanak\", \"cta_text\": \"For more information, feel free to contact us.\", \"cta_label\": \"Send an inquiry\"}, {\"icon\": \"chart-line\", \"slug\": \"reporting\", \"intro\": \"We prepare statutory and management reports that support compliance, provide better visibility into business performance, and create a strong basis for decision-making.\", \"items\": [\"Year-end statutory reporting required by accounting, profit tax, income tax, and VAT regulations.\", \"Mandatory annual reports including the corporate income tax return, balance sheet, statistical report, profit and loss statement, and related accompanying reports.\", \"Weekly, monthly, quarterly, and annual reports tailored to client needs and prepared in standard formats.\", \"Liquidity reporting through weekly and monthly overviews of paid invoices, open customer and supplier items, and monthly cost tracking.\", \"Profitability tracking by project, department, center, or cost location where needed for reporting purposes.\"], \"quote\": \"High-quality reporting turns a legal obligation into a practical management tool.\", \"title\": \"Reporting\", \"cta_url\": \"#accounting-sastanak\", \"cta_text\": \"For more information, feel free to contact us.\", \"cta_label\": \"Send an inquiry\", \"downloads\": [{\"url\": \"https://alphacapitalis.com/wp-content/uploads/2019/07/manipulacija-financijskim-izvjestajima-alpha-capitalis-akademija-predavanje-18-06-2019.pdf\", \"label\": \"Download\", \"title\": \"Financial statement manipulation\"}, {\"url\": \"https://alphacapitalis.com/wp-content/uploads/2019/07/analiza-financijskih-izvjestaja-alpha-capitalis-akademija-predavanje-18-06-2019.pdf\", \"label\": \"Download\", \"title\": \"Financial statement analysis\"}]}, {\"icon\": \"briefcase\", \"slug\": \"rent-an-accountant\", \"intro\": \"Have you introduced a new accounting system, need temporary support during growth, or want to train your staff for more independent day-to-day work?\", \"items\": [\"This service gives you access to a temporary accountant to solve short-term operational challenges.\", \"Our experts have extensive experience across different systems and in setting up accounting processes in established companies.\", \"Where there is a shortage of accounting staff, we provide interim support so the company can continue operating until a stable solution is in place.\"], \"quote\": \"When you need quick and reliable accounting reinforcement, we step in without disrupting operations.\", \"title\": \"Rent-an-accountant\", \"cta_url\": \"#accounting-sastanak\", \"cta_text\": \"For more information, feel free to contact us.\", \"cta_label\": \"Send an inquiry\"}, {\"icon\": \"user-group\", \"slug\": \"accounting-for-foreign-investors\", \"intro\": \"If you are a foreign investor with capital and an idea but cannot independently manage all the processes required to run a business in Croatia, our accounting team can support you through the following services:\", \"items\": [\"Company formation support.\", \"Full bookkeeping for the company.\", \"Company management support.\", \"Mail handling and registered office address services.\", \"Representation before the tax authorities.\", \"Regular management reporting on business performance.\"], \"quote\": \"We provide foreign investors with stable local operational and accounting support from setup onward.\", \"title\": \"Accounting for foreign investors\", \"cta_url\": \"#accounting-sastanak\", \"cta_text\": \"For more information, feel free to contact us.\", \"cta_label\": \"Send an inquiry\"}, {\"icon\": \"building-columns\", \"slug\": \"company-registration-support\", \"intro\": \"The company registration process is still not as simple as it aims to be. We support you through the entire setup process of the legal form best suited to your future business activity.\", \"items\": [\"Choosing a company name that is available and compliant, with alternative acceptable names prepared in advance.\", \"Visiting a notary public to certify the court registry application and related documents.\", \"Submitting additional required documents to FINA, including member lists, authorized representatives, and proof of initial capital payment.\", \"Collecting additional documentation through FINA, making a company seal, and opening a bank account.\", \"Registering the company with the tax authority and filing all required documentation.\", \"Registering with health and pension insurance institutions within the legally prescribed deadline after business commencement.\"], \"quote\": \"We guide you through registration step by step, with a clear process and properly prepared documentation.\", \"title\": \"Company registration support\", \"cta_url\": \"#accounting-sastanak\", \"cta_text\": \"For more information, feel free to contact us.\", \"cta_label\": \"Send an inquiry\", \"list_title\": \"Key steps in company registration include:\"}, {\"icon\": \"magnifying-glass\", \"slug\": \"forensic-accounting\", \"intro\": \"Business environments change quickly, and threats such as fraud, corruption, and money laundering, together with their financial, legal, and reputational consequences, are part of today’s reality.\", \"items\": [\"You experienced theft, missing accounting records, management manipulation of financial statements, or suspect corporate fraud.\", \"You are a supervisory board member and believe management is manipulating financial statements.\", \"You have taken over a business and want a proper handover and a verified opening position.\", \"You are involved in arbitration or litigation and require an independent expert review of financial and accounting documentation.\"], \"quote\": \"An external, independent perspective is essential for an objective review of risks, suspicions, and irregularities.\", \"title\": \"Forensic accounting\", \"cta_url\": \"#accounting-sastanak\", \"cta_text\": \"For more information, feel free to contact us.\", \"cta_label\": \"Send an inquiry\", \"after_list\": [\"Our forensic accounting services help resolve the issues described above. Successful forensic accounting depends on an independent external view, since internal employees often cannot assess every aspect of the situation with full objectivity.\"], \"list_title\": \"When might you need forensic accounting?\"}], \"editorial_section\": {\"cards\": [{\"body\": \"We fully understand the concern caused by inaccurate financial reporting. Beyond the loss of trust and internal uncertainty it creates, the financial damage can be significant. Our accounting specialists with years of experience are ready to take over the preparation of your financial statements so you can remain focused on your core business activities.\", \"icon\": \"file-lines\", \"title\": \"We safeguard the accuracy of your financial statements\"}, {\"body\": \"All of our accounting services are delivered in line with the company’s accounting policies, Croatian and international accounting standards (HSFI and IFRS), and applicable tax and other legal requirements.\", \"icon\": \"scale-balanced\", \"title\": \"We follow accounting standards, legal requirements, and financial reporting rules\"}, {\"body\": \"Our service is designed as direct support for your company’s financial activities. From the very beginning of your business, we help you make financial decisions based on accurate and timely data aligned with accounting standards and legal obligations.\", \"icon\": \"chart-line\", \"title\": \"We support your financial decision-making\"}, {\"body\": \"We act as your financial advisors and adapt our role to your specific financial needs. To ensure service quality and client satisfaction, we introduced the ISO 9001:2015 quality management standard. Our team also holds professional certifications and continuously develops through internal and external education so we can remain a reliable guide through the world of finance.\", \"icon\": \"book-open\", \"title\": \"Continuous development helps us ensure service quality\"}], \"title\": \"Leave your accounting to us\", \"eyebrow\": \"ALPHA CAPITALIS\", \"subtitle\": \"Stay focused on leading the business with quality, commitment, profitability, and long-term value creation.\"}, \"bookkeeping_section\": {\"slug\": \"bookkeeping\", \"intro\": \"With timely and structured bookkeeping, we provide reliable records of business changes, better visibility into obligations, and a stronger basis for financial decision-making.\", \"items\": [\"Recording accounting documentation in the core books: general ledger, incoming and outgoing invoice ledgers, cash records, and bank statements.\", \"Analytical monitoring of business changes across supplier and customer balances, cost centers, and profit centers.\", \"Preparing and filing VAT returns (monthly / quarterly), including reporting through the e-Tax administration system.\", \"Additional services include invoice issuance, internet banking payment support, compensation and assignment documentation, and preparation of documents for grants, incentives, loans, and leasing.\"], \"title\": \"Bookkeeping\", \"cta_url\": \"#accounting-sastanak\", \"cta_text\": \"For more information about bookkeeping support and the right collaboration model, feel free to contact us.\", \"cta_label\": \"Send an inquiry\", \"list_title\": \"Bookkeeping covers the following activities:\"}}', '2026-03-31 13:12:47', '2026-08-25 06:34:19'
FROM `content_service_pages` AS `parent`
WHERE `parent`.`code` = 'racunovodstvo'
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `slug` = VALUES(`slug`), `meta_title` = VALUES(`meta_title`), `meta_description` = VALUES(`meta_description`), `payload` = VALUES(`payload`), `updated_at` = VALUES(`updated_at`);

INSERT INTO `content_service_page_translations` (`service_page_id`, `locale`, `title`, `slug`, `meta_title`, `meta_description`, `payload`, `created_at`, `updated_at`)
SELECT `parent`.`id`, 'hr', 'Savjetovanje', 'savjetovanje', 'Savjetovanje', 'Financijsko i porezno savjetovanje, pribavljanje financiranja, due diligence, procjene vrijednosti i M&A savjetovanje.', '{\"ma\": {\"title\": \"Prodaja i kupnja poduzeća (M&A)\", \"kicker\": \"M&A SAVJETOVANJE\", \"pandea\": {\"body\": [\"ALPHA CAPITALIS je član Pandea Global M&A, globalne mreže za akvizicije koja povezuje investitore i prodavatelje različitih biznisa. Pandea Global M&A djeluje s naglaskom na spajanja, preuzimanja, pripajanja, dokapitalizacije i različite vrste joint venture-a, s ciljem plasiranja lokalnih projekata na međunarodno financijsko tržište.\", \"Svojim klijentima i partnerima omogućujemo pristup širokoj mreži međunarodnih investitora. Lokalnim društvima otvaramo pristup prekograničnim transakcijama, a za međunarodne investitore djelujemo kao one stop shop i lokalni partner.\", \"Ako imate projekt za koji vam je potreban investitor ili prodajete postojeći biznis, možete nam se obratiti kako bismo vaš slučaj prezentirali međunarodnim investitorima.\"], \"title\": \"ALPHA CAPITALIS je član Pandea Global M&A\", \"logo_alt\": \"Pandea Global M&A\", \"body_html\": \"<p>ALPHA CAPITALIS je član Pandea Global M&amp;A, globalne mreže za akvizicije koja povezuje investitore i prodavatelje različitih biznisa. Pandea Global M&amp;A djeluje s naglaskom na spajanja, preuzimanja, pripajanja, dokapitalizacije i različite vrste joint venture-a, s ciljem plasiranja lokalnih projekata na međunarodno financijsko tržište.</p><p>Svojim klijentima i partnerima omogućujemo pristup širokoj mreži međunarodnih investitora. Lokalnim društvima otvaramo pristup prekograničnim transakcijama, a za međunarodne investitore djelujemo kao one stop shop i lokalni partner.</p><p>Ako imate projekt za koji vam je potreban investitor ili prodajete postojeći biznis, možete nam se obratiti kako bismo vaš slučaj prezentirali međunarodnim investitorima.</p>\"}, \"meeting\": {\"intro\": \"Javite nam se i zajedno ćemo procijeniti koji oblik savjetodavne podrške najbolje odgovara vašim ciljevima, fazi poslovanja i konkretnom izazovu.\", \"title\": \"Razgovarajmo o vašim poslovnim odlukama\", \"kicker\": \"KONTAKT\", \"status\": \"Termin razgovora prilagođavamo vama.\", \"button_label\": \"Dogovorite sastanak\", \"contact_title\": \"Kontaktirajte nas\"}, \"help_items\": [\"analizi poslovanja i pripremi društva za prodaju\", \"procjeni vrijednosti poduzeća\", \"strukturiranju transakcije\", \"pripremi transakcijske dokumentacije\", \"identifikaciji potencijalnih kupaca ili investitora\", \"analizi ciljanih društava za akviziciju\", \"podršci tijekom dubinskog snimanja i pregovora\", \"pripremi i provedbi procesa zaključenja transakcije\"], \"help_title\": \"U okviru usluge pomažemo u:\", \"hero_intro\": \"Podrška u procesima spajanja i preuzimanja — od strateškog pozicioniranja do pregovaranja i zatvaranja transakcije.\", \"meta_title\": \"Prodaja i kupnja poduzeća (M&A)\", \"show_pandea\": true, \"blog_section\": {\"intro\": \"Zadnje objave i novosti iz područja financija, poreza, transakcija i savjetovanja.\", \"title\": \"Stručni uvidi u financije, poreze i transakcije\", \"kicker\": \"OBJAVE\", \"all_posts_label\": \"Pogledaj sve objave\", \"post_action_label\": \"Opširnije\"}, \"approach_body\": [\"Proces započinjemo razumijevanjem ciljeva vlasnika ili investitora te analizom financijskog i poslovnog položaja društva. Kroz strukturirani proces, financijsku analizu i koordinaciju svih aktivnosti pomažemo klijentima donijeti informirane odluke i uspješno realizirati transakciju.\"], \"overview_body\": [\"Prodaja i kupnja poduzeća predstavljaju složene poslovne procese koji uključuju prijenos vlasništva, pronalazak odgovarajućih partnera i strukturiranje transakcije s ciljem ostvarivanja optimalne vrijednosti za sve uključene strane.\"], \"services_body\": [\"Pružamo stručnu podršku vlasnicima i investitorima kroz cijeli proces prodaje ili kupnje poduzeća – od početne analize i pripreme transakcije do pregovora i zaključenja posla. Naš pristup usmjeren je na učinkovito upravljanje procesom, zaštitu interesa klijenta i ostvarenje najboljih mogućih uvjeta transakcije.\"], \"approach_title\": \"Naš pristup\", \"hero_image_alt\": \"Prodaja i kupnja poduzeća — stručna savjetodavna podrška\", \"overview_title\": \"Što je prodaja i kupnja poduzeća?\", \"services_title\": \"Naše usluge\", \"help_items_text\": \"analizi poslovanja i pripremi društva za prodaju\\nprocjeni vrijednosti poduzeća\\nstrukturiranju transakcije\\npripremi transakcijske dokumentacije\\nidentifikaciji potencijalnih kupaca ili investitora\\nanalizi ciljanih društava za akviziciju\\npodršci tijekom dubinskog snimanja i pregovora\\npripremi i provedbi procesa zaključenja transakcije\", \"meta_description\": \"Podrška u procesima spajanja i preuzimanja — od strateškog pozicioniranja do pregovaranja i zatvaranja transakcije.\", \"approach_body_html\": \"<p>Proces započinjemo razumijevanjem ciljeva vlasnika ili investitora te analizom financijskog i poslovnog položaja društva. Kroz strukturirani proces, financijsku analizu i koordinaciju svih aktivnosti pomažemo klijentima donijeti informirane odluke i uspješno realizirati transakciju.</p>\", \"overview_body_html\": \"<p>Prodaja i kupnja poduzeća predstavljaju složene poslovne procese koji uključuju prijenos vlasništva, pronalazak odgovarajućih partnera i strukturiranje transakcije s ciljem ostvarivanja optimalne vrijednosti za sve uključene strane.</p>\", \"services_body_html\": \"<p>Pružamo stručnu podršku vlasnicima i investitorima kroz cijeli proces prodaje ili kupnje poduzeća – od početne analize i pripreme transakcije do pregovora i zaključenja posla. Naš pristup usmjeren je na učinkovito upravljanje procesom, zaštitu interesa klijenta i ostvarenje najboljih mogućih uvjeta transakcije.</p>\"}, \"tax\": {\"title\": \"Porezno savjetovanje\", \"kicker\": \"POREZNO SAVJETOVANJE\", \"meeting\": {\"intro\": \"Javite nam se i zajedno ćemo procijeniti koji oblik savjetodavne podrške najbolje odgovara vašim ciljevima, fazi poslovanja i konkretnom izazovu.\", \"title\": \"Razgovarajmo o vašim poslovnim odlukama\", \"kicker\": \"KONTAKT\", \"status\": \"Termin razgovora prilagođavamo vama.\", \"button_label\": \"Dogovorite sastanak\", \"contact_title\": \"Kontaktirajte nas\"}, \"help_items\": [\"poreznom planiranju i optimizaciji\", \"analizi poreznih rizika i usklađenosti poslovanja\", \"pripremi poreznih mišljenja i stručnih tumačenja\", \"podršci kod poreznih nadzora\", \"PDV savjetovanju i međunarodnim poreznim pitanjima\", \"transfernim cijenama i povezanim transakcijama\", \"poreznom savjetovanju kod poslovnih restrukturiranja i M&A transakcija\"], \"help_title\": \"U okviru usluge pomažemo u:\", \"hero_intro\": \"Podrška u poreznom planiranju, usklađenosti, poreznim pregledima, transfernim cijenama, poreznim nadzorima i transakcijama.\", \"meta_title\": \"Porezno savjetovanje\", \"blog_section\": {\"intro\": \"Zadnje objave i novosti iz područja financija, poreza, transakcija i savjetovanja.\", \"title\": \"Stručni uvidi u financije, poreze i transakcije\", \"kicker\": \"OBJAVE\", \"all_posts_label\": \"Pogledaj sve objave\", \"post_action_label\": \"Opširnije\"}, \"approach_body\": [\"Svaki angažman započinjemo razumijevanjem poslovnog modela, financijske i porezne pozicije klijenta te specifičnih poslovnih okolnosti. Analiziramo relevantne propise i poreznu praksu kako bismo preporučili rješenja koja su zakonita, praktično provediva i usmjerena na smanjenje rizika te stvaranje dugoročne vrijednosti.\"], \"overview_body\": [\"Porezno savjetovanje obuhvaća stručnu podršku u razumijevanju i upravljanju poreznim obvezama, procjeni poreznih rizika i donošenju poslovnih odluka usklađenih s važećim propisima. Cilj je osigurati poreznu učinkovitost, usklađenost poslovanja i dugoročnu održivost.\"], \"services_body\": [\"Pružamo porezno savjetovanje pravnim i fizičkim osobama kroz analizu porezne pozicije, planiranje poslovnih aktivnosti i podršku u svakodnevnim poreznim pitanjima, kao i kod složenijih poslovnih transakcija. Naš pristup temelji se na povezivanju poreznih propisa, poslovnih ciljeva i praktične primjene.\"], \"approach_title\": \"Naš pristup\", \"hero_image_alt\": \"Porezno savjetovanje — stručna savjetodavna podrška\", \"overview_title\": \"Što je porezno savjetovanje?\", \"services_title\": \"Naše usluge\", \"help_items_text\": \"poreznom planiranju i optimizaciji\\nanalizi poreznih rizika i usklađenosti poslovanja\\npripremi poreznih mišljenja i stručnih tumačenja\\npodršci kod poreznih nadzora\\nPDV savjetovanju i međunarodnim poreznim pitanjima\\ntransfernim cijenama i povezanim transakcijama\\nporeznom savjetovanju kod poslovnih restrukturiranja i M&A transakcija\", \"meta_description\": \"Podrška u poreznom planiranju, usklađenosti, poreznim pregledima, transfernim cijenama, poreznim nadzorima i transakcijama.\", \"approach_body_html\": \"<p>Svaki angažman započinjemo razumijevanjem poslovnog modela, financijske i porezne pozicije klijenta te specifičnih poslovnih okolnosti. Analiziramo relevantne propise i poreznu praksu kako bismo preporučili rješenja koja su zakonita, praktično provediva i usmjerena na smanjenje rizika te stvaranje dugoročne vrijednosti.</p>\", \"overview_body_html\": \"<p>Porezno savjetovanje obuhvaća stručnu podršku u razumijevanju i upravljanju poreznim obvezama, procjeni poreznih rizika i donošenju poslovnih odluka usklađenih s važećim propisima. Cilj je osigurati poreznu učinkovitost, usklađenost poslovanja i dugoročnu održivost.</p>\", \"services_body_html\": \"<p>Pružamo porezno savjetovanje pravnim i fizičkim osobama kroz analizu porezne pozicije, planiranje poslovnih aktivnosti i podršku u svakodnevnim poreznim pitanjima, kao i kod složenijih poslovnih transakcija. Naš pristup temelji se na povezivanju poreznih propisa, poslovnih ciljeva i praktične primjene.</p>\"}, \"hero\": {\"intro\": \"Savjetovanje (Advisory) pruža stručnu podršku društvima, investitorima i poduzetnicima u donošenju financijskih i strateških odluka te stvaranju dugoročne vrijednosti.\", \"cta_url\": \"\", \"cta_label\": \"\", \"image_alt\": \"Stručno financijsko i strateško savjetovanje\", \"brand_title\": \"ALPHA CAPITALIS\", \"subtitle_lead\": \"Savjetovanje\", \"subtitle_accent\": \"\"}, \"zopu\": {\"title\": \"Zakon o poticanju ulaganja\", \"kicker\": \"ZAKON O POTICANJU ULAGANJA\", \"meeting\": {\"intro\": \"Javite nam se i zajedno ćemo procijeniti koji oblik savjetodavne podrške najbolje odgovara vašim ciljevima, fazi poslovanja i konkretnom izazovu.\", \"title\": \"Razgovarajmo o vašim poslovnim odlukama\", \"kicker\": \"KONTAKT\", \"status\": \"Termin razgovora prilagođavamo vama.\", \"button_label\": \"Dogovorite sastanak\", \"contact_title\": \"Kontaktirajte nas\"}, \"help_items\": [\"analizi mogućnosti korištenja potpora\", \"procjeni prihvatljivosti investicijskog projekta\", \"pripremi investicijske dokumentacije i prijavne dokumentacije\", \"definiranju ključnih pokazatelja ulaganja\", \"komunikaciji s nadležnim institucijama\", \"praćenju provedbe investicijskih aktivnosti\"], \"help_title\": \"U okviru usluge pomažemo u:\", \"hero_intro\": \"Podrška u korištenju poreznih olakšica i poticaja za investicijske projekte temeljem ZoPU-a.\", \"meta_title\": \"Zakon o poticanju ulaganja\", \"blog_section\": {\"intro\": \"Zadnje objave i novosti iz područja financija, poreza, transakcija i savjetovanja.\", \"title\": \"Stručni uvidi u financije, poreze i transakcije\", \"kicker\": \"OBJAVE\", \"all_posts_label\": \"Pogledaj sve objave\", \"post_action_label\": \"Opširnije\"}, \"approach_body\": [\"Proces započinjemo razumijevanjem poslovnih ciljeva klijenta i planirane investicije. Analiziramo potencijalne mogućnosti ostvarivanja potpora te strukturiramo projekt na način koji omogućuje učinkovitu provedbu ulaganja i dugoročnu poslovnu vrijednost.\"], \"overview_body\": [\"Zakon o poticanju ulaganja predstavlja okvir za korištenje dostupnih potpora namijenjenih poticanju investicija, otvaranju novih radnih mjesta i povećanju konkurentnosti društava. Kroz različite oblike potpora omogućuje se smanjenje troškova ulaganja i stvaranje povoljnijih uvjeta za razvoj poslovanja.\"], \"services_body\": [\"Pružamo stručnu podršku društvima u pripremi i provedbi investicijskih projekata koji mogu ostvariti pravo na potpore prema Zakonu o poticanju ulaganja. Naš pristup obuhvaća analizu prihvatljivosti projekta, pripremu potrebne dokumentacije te podršku kroz cijeli proces realizacije ulaganja.\"], \"approach_title\": \"Naš pristup\", \"hero_image_alt\": \"Zakon o poticanju ulaganja — stručna savjetodavna podrška\", \"overview_title\": \"Što je Zakon o poticanju ulaganja?\", \"services_title\": \"Naše usluge\", \"help_items_text\": \"analizi mogućnosti korištenja potpora\\nprocjeni prihvatljivosti investicijskog projekta\\npripremi investicijske dokumentacije i prijavne dokumentacije\\ndefiniranju ključnih pokazatelja ulaganja\\nkomunikaciji s nadležnim institucijama\\npraćenju provedbe investicijskih aktivnosti\", \"meta_description\": \"Podrška u korištenju poreznih olakšica i poticaja za investicijske projekte temeljem ZoPU-a.\", \"approach_body_html\": \"<p>Proces započinjemo razumijevanjem poslovnih ciljeva klijenta i planirane investicije. Analiziramo potencijalne mogućnosti ostvarivanja potpora te strukturiramo projekt na način koji omogućuje učinkovitu provedbu ulaganja i dugoročnu poslovnu vrijednost.</p>\", \"overview_body_html\": \"<p>Zakon o poticanju ulaganja predstavlja okvir za korištenje dostupnih potpora namijenjenih poticanju investicija, otvaranju novih radnih mjesta i povećanju konkurentnosti društava. Kroz različite oblike potpora omogućuje se smanjenje troškova ulaganja i stvaranje povoljnijih uvjeta za razvoj poslovanja.</p>\", \"services_body_html\": \"<p>Pružamo stručnu podršku društvima u pripremi i provedbi investicijskih projekata koji mogu ostvariti pravo na potpore prema Zakonu o poticanju ulaganja. Naš pristup obuhvaća analizu prihvatljivosti projekta, pripremu potrebne dokumentacije te podršku kroz cijeli proces realizacije ulaganja.</p>\"}, \"pandea\": {\"body\": [\"ALPHA CAPITALIS je član Pandea Global M&A, globalne mreže za akvizicije koja povezuje investitore i prodavatelje različitih biznisa. Pandea Global M&A djeluje s naglaskom na spajanja, preuzimanja, pripajanja, dokapitalizacije i različite vrste joint venture-a, s ciljem plasiranja lokalnih projekata na međunarodno financijsko tržište.\", \"Svojim klijentima i partnerima omogućujemo pristup širokoj mreži međunarodnih investitora. Lokalnim društvima otvaramo pristup prekograničnim transakcijama, a za međunarodne investitore djelujemo kao one stop shop i lokalni partner.\", \"Ako imate projekt za koji vam je potreban investitor ili prodajete postojeći biznis, možete nam se obratiti kako bismo vaš slučaj prezentirali međunarodnim investitorima.\"], \"title\": \"ALPHA CAPITALIS je član Pandea Global M&A\", \"logo_alt\": \"Pandea Global M&A\", \"body_html\": \"<p>ALPHA CAPITALIS je član Pandea Global M&amp;A, globalne mreže za akvizicije koja povezuje investitore i prodavatelje različitih biznisa. Pandea Global M&amp;A djeluje s naglaskom na spajanja, preuzimanja, pripajanja, dokapitalizacije i različite vrste joint venture-a, s ciljem plasiranja lokalnih projekata na međunarodno financijsko tržište.</p><p>Svojim klijentima i partnerima omogućujemo pristup širokoj mreži međunarodnih investitora. Lokalnim društvima otvaramo pristup prekograničnim transakcijama, a za međunarodne investitore djelujemo kao one stop shop i lokalni partner.</p><p>Ako imate projekt za koji vam je potreban investitor ili prodajete postojeći biznis, možete nam se obratiti kako bismo vaš slučaj prezentirali međunarodnim investitorima.</p>\"}, \"funding\": {\"cards\": [{\"url\": \"/eu-fondovi\", \"text\": \"EU bespovratna sredstva, nacionalni instrumenti potpore i projektna podrška od identifikacije poziva do provedbe.\", \"title\": \"EU fondovi\"}, {\"url\": \"/savjetovanje/pribavljanje-financiranja/bankovni-krediti\", \"text\": \"Strukturiranje kreditnih zahtjeva i podrška u pregovorima s financijskim institucijama.\", \"title\": \"Bankovni krediti\"}, {\"url\": \"/savjetovanje/pribavljanje-financiranja/zakon-o-poticanju-ulaganja\", \"text\": \"Podrška u korištenju poreznih olakšica i poticaja za investicijske projekte temeljem ZoPU-a.\", \"title\": \"Zakon o poticanju ulaganja\"}], \"intro\": \"Pribavljanje financiranja obuhvaća podršku društvima u pronalasku odgovarajućih izvora kapitala za rast poslovanja, investicije i ostvarenje strateških ciljeva.\", \"title\": \"Pribavljanje financiranja\", \"meeting\": {\"intro\": \"Javite nam se i zajedno ćemo procijeniti koji oblik savjetodavne podrške najbolje odgovara vašim ciljevima, fazi poslovanja i konkretnom izazovu.\", \"title\": \"Razgovarajmo o vašim poslovnim odlukama\", \"kicker\": \"KONTAKT\", \"status\": \"Termin razgovora prilagođavamo vama.\", \"button_label\": \"Dogovorite sastanak\", \"contact_title\": \"Kontaktirajte nas\"}, \"services\": [{\"text\": \"Analiziramo vaše investicijske i razvojne prioritete te ih povezujemo s odgovarajućim natječajima, kreditnim linijama i instrumentima potpore.\", \"title\": \"Analiza i odabir natječaja\"}, {\"text\": \"Pripremamo projektnu logiku, proračun, obrasce i svu prateću dokumentaciju potrebnu za kvalitetnu i pravodobnu prijavu.\", \"title\": \"Izrada projektne prijave\"}, {\"text\": \"Nakon odobrenja sredstava preuzimamo administrativno praćenje, komunikaciju s tijelima, izvještavanje i projektnu koordinaciju.\", \"title\": \"Provedba i koordinacija projekta\"}, {\"text\": \"Savjetujemo o HBOR kreditima, HAMAG zajmovima i ostalim instrumentima koji mogu biti komplementarni bespovratnim sredstvima.\", \"title\": \"Financijski instrumenti\"}, {\"text\": \"Pomažemo pri korištenju Zakona o poticanju ulaganja, Uredbe o turizmu i Zakona o državnoj potpori za istraživačko-razvojne projekte.\", \"title\": \"Zakonski poticaji i olakšice\"}, {\"text\": \"Kontinuirano pratimo nove pozive i pravovremeno vas obavještavamo o prilikama relevantnim za vaše poslovanje.\", \"title\": \"Praćenje natječaja\"}], \"hero_intro\": \"Podrška u strukturiranju i pribavljanju bankovnog financiranja, EU bespovratnih sredstava, poticajnih kredita i private equity kapitala.\", \"meta_title\": \"Pribavljanje financiranja\", \"blog_section\": {\"intro\": \"Zadnje objave i novosti iz područja financija, poreza, transakcija i savjetovanja.\", \"title\": \"Stručni uvidi u financije, poreze i transakcije\", \"kicker\": \"OBJAVE\", \"all_posts_label\": \"Pogledaj sve objave\", \"post_action_label\": \"Opširnije\"}, \"approach_body\": [\"Svaki savjetodavni angažman započinjemo razumijevanjem poslovnog konteksta, ciljeva i ključnih rizika. Analiziramo financijske podatke, tržišni položaj, porezne i regulatorne okolnosti te specifičnosti projekta kako bismo predložili rješenja koja su jasna, provediva i usmjerena na stvaranje dugoročne vrijednosti.\", \"Naš pristup spaja strateško razmišljanje i praktičnu provedbu — od početne analize do konkretnih odluka, dokumentacije, komunikacije s dionicima i provedbe projekta.\"], \"overview_body\": [\"EU fondovi su instrumenti financiranja kojima Europska unija podupire razvoj poduzetništva, inovacija, digitalne i zelene tranzicije te infrastrukture. Poduzetnicima su na raspolaganju bespovratna sredstva iz Višegodišnjeg financijskog okvira 2021.–2027., a uz EU programe dostupni su i nacionalni instrumenti potpore — HBOR krediti, HAMAG zajmovi te porezne olakšice temeljem Zakona o poticanju ulaganja i istraživačko-razvojnim projektima.\"], \"advisory_cards\": [], \"approach_title\": \"Naš pristup\", \"hero_image_alt\": \"Pribavljanje financiranja — stručna savjetodavna podrška\", \"overview_title\": \"EU fondovi\", \"services_title\": \"Usluge EU fondova\", \"meta_description\": \"Podrška u strukturiranju i pribavljanju bankovnog financiranja, EU bespovratnih sredstava, poticajnih kredita i private equity kapitala.\", \"approach_body_html\": \"<p>Svaki savjetodavni angažman započinjemo razumijevanjem poslovnog konteksta, ciljeva i ključnih rizika. Analiziramo financijske podatke, tržišni položaj, porezne i regulatorne okolnosti te specifičnosti projekta kako bismo predložili rješenja koja su jasna, provediva i usmjerena na stvaranje dugoročne vrijednosti.</p><p>Naš pristup spaja strateško razmišljanje i praktičnu provedbu — od početne analize do konkretnih odluka, dokumentacije, komunikacije s dionicima i provedbe projekta.</p>\"}, \"meeting\": {\"intro\": \"Javite nam se i zajedno ćemo procijeniti koji oblik savjetodavne podrške najbolje odgovara vašim ciljevima, fazi poslovanja i konkretnom izazovu.\", \"title\": \"Razgovarajmo o vašim poslovnim odlukama\", \"kicker\": \"KONTAKT\", \"status\": \"Termin razgovora prilagođavamo vama.\", \"button_label\": \"Dogovorite sastanak\", \"contact_title\": \"Kontaktirajte nas\"}, \"approach\": {\"body\": [\"Svaki savjetodavni angažman započinjemo razumijevanjem poslovnog konteksta, ciljeva i ključnih rizika. Analiziramo financijske podatke, tržišni položaj, porezne i regulatorne okolnosti te specifičnosti projekta kako bismo predložili rješenja koja su jasna, provediva i usmjerena na stvaranje dugoročne vrijednosti.\", \"Naš pristup spaja strateško razmišljanje i praktičnu provedbu — od početne analize do konkretnih odluka, dokumentacije, komunikacije s dionicima i provedbe projekta.\"], \"title\": \"Naš pristup\", \"kicker\": \"NAŠ PRISTUP\", \"body_html\": \"<p>Svaki savjetodavni angažman započinjemo razumijevanjem poslovnog konteksta, ciljeva i ključnih rizika. Analiziramo financijske podatke, tržišni položaj, porezne i regulatorne okolnosti te specifičnosti projekta kako bismo predložili rješenja koja su jasna, provediva i usmjerena na stvaranje dugoročne vrijednosti.</p><p>Naš pristup spaja strateško razmišljanje i praktičnu provedbu — od početne analize do konkretnih odluka, dokumentacije, komunikacije s dionicima i provedbe projekta.</p>\"}, \"overview\": {\"body\": [\"Savjetovanje (Advisory) pruža stručnu podršku društvima, investitorima i poduzetnicima u donošenju strateških financijskih odluka kroz usluge spajanja i preuzimanja, procjene vrijednosti, dubinska snimanja, pribavljanje kapitala i financijsko restrukturiranje, s ciljem upravljanja rizicima i stvaranja dugoročne vrijednosti.\"], \"title\": \"Što je savjetovanje?\", \"kicker\": \"ŠTO JE SAVJETOVANJE?\", \"body_html\": \"<p>Savjetovanje (Advisory) pruža stručnu podršku društvima, investitorima i poduzetnicima u donošenju strateških financijskih odluka kroz usluge spajanja i preuzimanja, procjene vrijednosti, dubinska snimanja, pribavljanje kapitala i financijsko restrukturiranje, s ciljem upravljanja rizicima i stvaranja dugoročne vrijednosti.</p>\"}, \"financial\": {\"title\": \"Financijsko savjetovanje\", \"meeting\": {\"intro\": \"Javite nam se i zajedno ćemo procijeniti koji oblik savjetodavne podrške najbolje odgovara vašim ciljevima, fazi poslovanja i konkretnom izazovu.\", \"title\": \"Razgovarajmo o vašim poslovnim odlukama\", \"kicker\": \"KONTAKT\", \"status\": \"Termin razgovora prilagođavamo vama.\", \"button_label\": \"Dogovorite sastanak\", \"contact_title\": \"Kontaktirajte nas\"}, \"help_items\": [\"analizi poslovanja i financijskih pokazatelja\", \"izradi financijskih modela i projekcija\", \"planiranju novčanih tokova i potreba za kapitalom\", \"optimizaciji izvora i strukture financiranja\", \"pripremi investicijskih i upravljačkih podloga\", \"procjeni rizika i scenarija razvoja poslovanja\"], \"hero_intro\": \"Financijsko savjetovanje pomaže vlasnicima, upravama i investitorima donositi kvalitetnije odluke na temelju pouzdanih analiza, realnih projekcija i jasnog razumijevanja financijskog položaja društva.\", \"meta_title\": \"Financijsko savjetovanje\", \"blog_section\": {\"intro\": \"Zadnje objave i novosti iz područja financija, poreza, transakcija i savjetovanja.\", \"title\": \"Stručni uvidi u financije, poreze i transakcije\", \"kicker\": \"OBJAVE\", \"all_posts_label\": \"Pogledaj sve objave\", \"post_action_label\": \"Opširnije\"}, \"approach_body\": [\"Proces započinjemo razumijevanjem poslovnog modela, ciljeva i ključnih izazova. Financijske podatke povezujemo s poslovnim kontekstom kako bismo preporuke pretvorili u jasne i provedive korake.\"], \"overview_body\": [\"Financijsko savjetovanje pomaže vlasnicima, upravama i investitorima donositi kvalitetnije odluke na temelju pouzdanih analiza, realnih projekcija i jasnog razumijevanja financijskog položaja društva.\"], \"services_body\": [\"Pružamo stručnu podršku pri planiranju rasta, strukturiranju financiranja, financijskom modeliranju i pripremi važnih poslovnih odluka. Svaki angažman prilagođavamo konkretnom cilju, dostupnim podacima i fazi razvoja društva.\"], \"approach_title\": \"Naš pristup\", \"hero_image_alt\": \"Financijsko savjetovanje — stručna savjetodavna podrška\", \"overview_title\": \"Što je financijsko savjetovanje?\", \"services_title\": \"Naše usluge\", \"help_items_text\": \"analizi poslovanja i financijskih pokazatelja\\nizradi financijskih modela i projekcija\\nplaniranju novčanih tokova i potreba za kapitalom\\noptimizaciji izvora i strukture financiranja\\npripremi investicijskih i upravljačkih podloga\\nprocjeni rizika i scenarija razvoja poslovanja\", \"meta_description\": \"Financijsko savjetovanje pomaže vlasnicima, upravama i investitorima donositi kvalitetnije odluke na temelju pouzdanih analiza, realnih projekcija i jasnog razumijevanja financijskog položaja društva.\", \"approach_body_html\": \"<p>Proces započinjemo razumijevanjem poslovnog modela, ciljeva i ključnih izazova. Financijske podatke povezujemo s poslovnim kontekstom kako bismo preporuke pretvorili u jasne i provedive korake.</p>\", \"overview_body_html\": \"<p>Financijsko savjetovanje pomaže vlasnicima, upravama i investitorima donositi kvalitetnije odluke na temelju pouzdanih analiza, realnih projekcija i jasnog razumijevanja financijskog položaja društva.</p>\", \"services_body_html\": \"<p>Pružamo stručnu podršku pri planiranju rasta, strukturiranju financiranja, financijskom modeliranju i pripremi važnih poslovnih odluka. Svaki angažman prilagođavamo konkretnom cilju, dostupnim podacima i fazi razvoja društva.</p>\"}, \"bank_loans\": {\"title\": \"Bankovni krediti\", \"kicker\": \"BANKOVNI KREDITI\", \"meeting\": {\"intro\": \"Javite nam se i zajedno ćemo procijeniti koji oblik savjetodavne podrške najbolje odgovara vašim ciljevima, fazi poslovanja i konkretnom izazovu.\", \"title\": \"Razgovarajmo o vašim poslovnim odlukama\", \"kicker\": \"KONTAKT\", \"status\": \"Termin razgovora prilagođavamo vama.\", \"button_label\": \"Dogovorite sastanak\", \"contact_title\": \"Kontaktirajte nas\"}, \"help_items\": [\"analizi potreba za financiranjem\", \"pripremi financijskih projekcija i investicijskih podloga\", \"strukturiranju kreditnog zahtjeva\", \"komunikaciji i pregovorima s bankama\", \"analizi uvjeta financiranja\", \"odabiru najpovoljnije strukture kredita\"], \"help_title\": \"U okviru usluge pomažemo u:\", \"hero_intro\": \"Strukturiranje kreditnih zahtjeva i podrška u pregovorima s financijskim institucijama.\", \"meta_title\": \"Bankovni krediti\", \"blog_section\": {\"intro\": \"Zadnje objave i novosti iz područja financija, poreza, transakcija i savjetovanja.\", \"title\": \"Stručni uvidi u financije, poreze i transakcije\", \"kicker\": \"OBJAVE\", \"all_posts_label\": \"Pogledaj sve objave\", \"post_action_label\": \"Opširnije\"}, \"approach_body\": [\"Proces započinjemo detaljnom analizom poslovanja, postojećih obveza i planova razvoja društva. Na temelju razumijevanja poslovnog modela pripremamo kvalitetne financijske materijale i podržavamo klijenta kroz cijeli proces financiranja, s ciljem osiguranja održivog i učinkovitog kreditnog rješenja.\"], \"overview_body\": [\"Bankovni krediti predstavljaju jedan od najčešćih izvora financiranja poslovanja, investicija i razvoja društava. Omogućuju poduzetnicima i društvima osiguravanje potrebnih sredstava za rast, povećanje kapaciteta, financiranje projekata ili optimizaciju postojeće financijske strukture.\"], \"services_body\": [\"Pružamo podršku klijentima u procesu pribavljanja bankovnog financiranja, od analize financijskih potreba i pripreme dokumentacije do komunikacije s financijskim institucijama. Naš pristup usmjeren je na pronalazak optimalnih kreditnih rješenja koja odgovaraju poslovnim ciljevima i financijskim mogućnostima klijenta.\"], \"approach_title\": \"Naš pristup\", \"hero_image_alt\": \"Bankovni krediti — stručna savjetodavna podrška\", \"overview_title\": \"Što su bankovni krediti?\", \"services_title\": \"Naše usluge\", \"help_items_text\": \"analizi potreba za financiranjem\\npripremi financijskih projekcija i investicijskih podloga\\nstrukturiranju kreditnog zahtjeva\\nkomunikaciji i pregovorima s bankama\\nanalizi uvjeta financiranja\\nodabiru najpovoljnije strukture kredita\", \"meta_description\": \"Strukturiranje kreditnih zahtjeva i podrška u pregovorima s financijskim institucijama.\", \"approach_body_html\": \"<p>Proces započinjemo detaljnom analizom poslovanja, postojećih obveza i planova razvoja društva. Na temelju razumijevanja poslovnog modela pripremamo kvalitetne financijske materijale i podržavamo klijenta kroz cijeli proces financiranja, s ciljem osiguranja održivog i učinkovitog kreditnog rješenja.</p>\", \"overview_body_html\": \"<p>Bankovni krediti predstavljaju jedan od najčešćih izvora financiranja poslovanja, investicija i razvoja društava. Omogućuju poduzetnicima i društvima osiguravanje potrebnih sredstava za rast, povećanje kapaciteta, financiranje projekata ili optimizaciju postojeće financijske strukture.</p>\", \"services_body_html\": \"<p>Pružamo podršku klijentima u procesu pribavljanja bankovnog financiranja, od analize financijskih potreba i pripreme dokumentacije do komunikacije s financijskim institucijama. Naš pristup usmjeren je na pronalazak optimalnih kreditnih rješenja koja odgovaraju poslovnim ciljevima i financijskim mogućnostima klijenta.</p>\"}, \"valuations\": {\"title\": \"Procjena vrijednosti društva\", \"kicker\": \"PROCJENA VRIJEDNOSTI\", \"meeting\": {\"intro\": \"Javite nam se i zajedno ćemo procijeniti koji oblik savjetodavne podrške najbolje odgovara vašim ciljevima, fazi poslovanja i konkretnom izazovu.\", \"title\": \"Razgovarajmo o vašim poslovnim odlukama\", \"kicker\": \"KONTAKT\", \"status\": \"Termin razgovora prilagođavamo vama.\", \"button_label\": \"Dogovorite sastanak\", \"contact_title\": \"Kontaktirajte nas\"}, \"help_items\": [\"analizi poslovanja i financijskih pokazatelja društva\", \"izradi financijskih modela i projekcija\", \"procjeni budućih novčanih tokova i potencijala rasta\", \"primjeni odgovarajućih metoda vrednovanja\", \"podršci kod prodaje društva, akvizicija i dokapitalizacija\", \"pružanju stručne podloge za pregovore i strateške odluke\"], \"help_title\": \"U okviru usluge pomažemo u:\", \"hero_intro\": \"Procjena ekonomske vrijednosti društva kao podloga za prodaju, kupnju, dokapitalizaciju i druge strateške aktivnosti.\", \"meta_title\": \"Procjena vrijednosti društva\", \"blog_section\": {\"intro\": \"Zadnje objave i novosti iz područja financija, poreza, transakcija i savjetovanja.\", \"title\": \"Stručni uvidi u financije, poreze i transakcije\", \"kicker\": \"OBJAVE\", \"all_posts_label\": \"Pogledaj sve objave\", \"post_action_label\": \"Opširnije\"}, \"approach_body\": [\"Proces započinjemo razumijevanjem poslovnog modela, financijske pozicije i cilja procjene. Primjenom relevantnih tržišnih metoda vrednovanja, uključujući metodu diskontiranih novčanih tokova, usporedivih transakcija i usporedivih društava, izrađujemo procjenu koja pruža jasnu osnovu za donošenje kvalitetnih poslovnih odluka.\"], \"overview_body\": [\"Procjena vrijednosti predstavlja proces utvrđivanja ekonomske vrijednosti društva na temelju analize poslovanja, financijskih rezultata, tržišnih uvjeta i budućeg potencijala rasta. Koristi se kao podloga za donošenje odluka u procesima prodaje, kupnje, dokapitalizacije i drugih strateških aktivnosti.\"], \"services_body\": [\"Pružamo usluge procjene vrijednosti trgovačkih društava vlasnicima, investitorima i financijskim institucijama, prilagođavajući pristup svrsi i specifičnostima svakog pojedinog projekta. Naš cilj je pružiti objektivan i pouzdan uvid u vrijednost društva te ključne čimbenike koji na nju utječu.\"], \"approach_title\": \"Naš pristup\", \"hero_image_alt\": \"Procjena vrijednosti društva — stručna savjetodavna podrška\", \"overview_title\": \"Što je procjena vrijednosti?\", \"services_title\": \"Naše usluge\", \"help_items_text\": \"analizi poslovanja i financijskih pokazatelja društva\\nizradi financijskih modela i projekcija\\nprocjeni budućih novčanih tokova i potencijala rasta\\nprimjeni odgovarajućih metoda vrednovanja\\npodršci kod prodaje društva, akvizicija i dokapitalizacija\\npružanju stručne podloge za pregovore i strateške odluke\", \"meta_description\": \"Procjena ekonomske vrijednosti društva kao podloga za prodaju, kupnju, dokapitalizaciju i druge strateške aktivnosti.\", \"approach_body_html\": \"<p>Proces započinjemo razumijevanjem poslovnog modela, financijske pozicije i cilja procjene. Primjenom relevantnih tržišnih metoda vrednovanja, uključujući metodu diskontiranih novčanih tokova, usporedivih transakcija i usporedivih društava, izrađujemo procjenu koja pruža jasnu osnovu za donošenje kvalitetnih poslovnih odluka.</p>\", \"overview_body_html\": \"<p>Procjena vrijednosti predstavlja proces utvrđivanja ekonomske vrijednosti društva na temelju analize poslovanja, financijskih rezultata, tržišnih uvjeta i budućeg potencijala rasta. Koristi se kao podloga za donošenje odluka u procesima prodaje, kupnje, dokapitalizacije i drugih strateških aktivnosti.</p>\", \"services_body_html\": \"<p>Pružamo usluge procjene vrijednosti trgovačkih društava vlasnicima, investitorima i financijskim institucijama, prilagođavajući pristup svrsi i specifičnostima svakog pojedinog projekta. Naš cilj je pružiti objektivan i pouzdan uvid u vrijednost društva te ključne čimbenike koji na nju utječu.</p>\"}, \"blog_section\": {\"intro\": \"Zadnje objave i novosti iz područja financija, poreza, transakcija i savjetovanja.\", \"title\": \"Stručni uvidi u financije, poreze i transakcije\", \"kicker\": \"OBJAVE\", \"all_posts_label\": \"Pogledaj sve objave\", \"post_action_label\": \"Opširnije\"}, \"due_diligence\": {\"title\": \"Dubinska snimanja (Due Diligence)\", \"kicker\": \"DUE DILIGENCE\", \"meeting\": {\"intro\": \"Javite nam se i zajedno ćemo procijeniti koji oblik savjetodavne podrške najbolje odgovara vašim ciljevima, fazi poslovanja i konkretnom izazovu.\", \"title\": \"Razgovarajmo o vašim poslovnim odlukama\", \"kicker\": \"KONTAKT\", \"status\": \"Termin razgovora prilagođavamo vama.\", \"button_label\": \"Dogovorite sastanak\", \"contact_title\": \"Kontaktirajte nas\"}, \"help_items\": [\"analizi financijskih rezultata i poslovanja društva\", \"procjeni održivosti ostvarenih rezultata\", \"identifikaciji ključnih rizika i potencijalnih nepravilnosti\", \"analizi ključnih pokazatelja uspješnosti (KPI)\", \"razumijevanju poslovnog modela i tržišnog položaja\", \"prepoznavanju područja za unapređenje i stvaranje dodatne vrijednosti\"], \"help_title\": \"U okviru usluge pomažemo u:\", \"hero_intro\": \"Detaljna analiza poslovanja društva radi jasnog uvida u financijsko stanje, rizike i prilike prije važnih odluka ili transakcija.\", \"meta_title\": \"Dubinska snimanja (Due Diligence)\", \"blog_section\": {\"intro\": \"Zadnje objave i novosti iz područja financija, poreza, transakcija i savjetovanja.\", \"title\": \"Stručni uvidi u financije, poreze i transakcije\", \"kicker\": \"OBJAVE\", \"all_posts_label\": \"Pogledaj sve objave\", \"post_action_label\": \"Opširnije\"}, \"approach_body\": [\"Proces započinjemo detaljnom analizom dostupnih financijskih i poslovnih podataka. Kroz strukturirani pristup i razumijevanje poslovanja društva pružamo pouzdanu podlogu za donošenje informiranih odluka, smanjenje rizika i uspješnu realizaciju poslovnih ciljeva.\"], \"overview_body\": [\"Dubinsko snimanje predstavlja detaljnu analizu poslovanja društva s ciljem dobivanja jasnog i objektivnog uvida u financijsko stanje, poslovne rizike i potencijalnu vrijednost društva prije donošenja važnih poslovnih odluka ili provedbe transakcije.\"], \"services_body\": [\"Pružamo usluge dubinskog snimanja kupcima, prodavateljima i investitorima u procesima spajanja, preuzimanja i drugih poslovnih transakcija. Naš pristup usmjeren je na prepoznavanje ključnih čimbenika koji utječu na vrijednost društva te pravovremeno identificiranje rizika i prilika.\"], \"approach_title\": \"Naš pristup\", \"hero_image_alt\": \"Dubinska snimanja — stručna savjetodavna podrška\", \"overview_title\": \"Što je dubinsko snimanje (Due Diligence)?\", \"services_title\": \"Naše usluge\", \"help_items_text\": \"analizi financijskih rezultata i poslovanja društva\\nprocjeni održivosti ostvarenih rezultata\\nidentifikaciji ključnih rizika i potencijalnih nepravilnosti\\nanalizi ključnih pokazatelja uspješnosti (KPI)\\nrazumijevanju poslovnog modela i tržišnog položaja\\nprepoznavanju područja za unapređenje i stvaranje dodatne vrijednosti\", \"meta_description\": \"Detaljna analiza poslovanja društva radi jasnog uvida u financijsko stanje, rizike i prilike prije važnih odluka ili transakcija.\", \"approach_body_html\": \"<p>Proces započinjemo detaljnom analizom dostupnih financijskih i poslovnih podataka. Kroz strukturirani pristup i razumijevanje poslovanja društva pružamo pouzdanu podlogu za donošenje informiranih odluka, smanjenje rizika i uspješnu realizaciju poslovnih ciljeva.</p>\", \"overview_body_html\": \"<p>Dubinsko snimanje predstavlja detaljnu analizu poslovanja društva s ciljem dobivanja jasnog i objektivnog uvida u financijsko stanje, poslovne rizike i potencijalnu vrijednost društva prije donošenja važnih poslovnih odluka ili provedbe transakcije.</p>\", \"services_body_html\": \"<p>Pružamo usluge dubinskog snimanja kupcima, prodavateljima i investitorima u procesima spajanja, preuzimanja i drugih poslovnih transakcija. Naš pristup usmjeren je na prepoznavanje ključnih čimbenika koji utječu na vrijednost društva te pravovremeno identificiranje rizika i prilika.</p>\"}, \"service_cards\": [{\"url\": \"/savjetovanje/pribavljanje-financiranja\", \"text\": \"Podrška u strukturiranju i pribavljanju bankovnog financiranja, EU bespovratnih sredstava, poticajnih kredita i private equity kapitala.\", \"title\": \"Pribavljanje financiranja\"}, {\"url\": \"/savjetovanje/prodaja-i-kupnja-poduzeca\", \"text\": \"Podrška u procesima spajanja i preuzimanja — od strateškog pozicioniranja do pregovaranja i zatvaranja transakcije.\", \"title\": \"M&A savjetovanje\"}, {\"url\": \"/savjetovanje/dubinska-snimanja\", \"text\": \"Detaljna analiza poslovanja društva radi jasnog uvida u financijsko stanje, rizike i prilike prije važnih odluka ili transakcija.\", \"title\": \"Dubinska snimanja (Due Diligence)\"}, {\"url\": \"/savjetovanje/procjena-vrijednosti-drustva\", \"text\": \"Procjena ekonomske vrijednosti društva kao podloga za prodaju, kupnju, dokapitalizaciju i druge strateške aktivnosti.\", \"title\": \"Procjena vrijednosti društva\"}, {\"url\": \"/savjetovanje/porezno-savjetovanje\", \"text\": \"Podrška u poreznom planiranju, usklađenosti, poreznim pregledima, transfernim cijenama, poreznim nadzorima i transakcijama.\", \"title\": \"Porezno savjetovanje\"}], \"video_section\": {\"intro\": \"\", \"title\": \"\"}, \"services_intro\": {\"intro\": \"\", \"title\": \"Usluge savjetovanja\", \"kicker\": \"USLUGE SAVJETOVANJA\", \"card_action_label\": \"Opširnije\"}, \"source_modules\": {\"intro\": \"\", \"items\": [{\"url\": \"/eu-fondovi#eu-funds-calls\", \"text\": \"Pregled trenutno otvorenih natječaja i poziva za poduzetnike.\", \"title\": \"Otvoreni natječaji\"}, {\"url\": \"/eu-fondovi#eu-funds-calls\", \"text\": \"Arhiva zatvorenih poziva i programa koji su prethodno bili dostupni.\", \"title\": \"Zatvoreni natječaji\"}, {\"url\": \"/eu-fondovi#eu-funds-resources\", \"text\": \"HBOR krediti, HAMAG zajmovi i instrumenti koji mogu nadopuniti bespovratna sredstva.\", \"title\": \"Financijski instrumenti\"}, {\"url\": \"/eu-fondovi#eu-funds-laws\", \"text\": \"Poticaji, zakoni i porezne olakšice dostupni za investicijske projekte.\", \"title\": \"Porezne olakšice\"}, {\"url\": \"/savjetovanje/pribavljanje-financiranja#advisory-bankovni-krediti\", \"text\": \"Sažetak podrške pri pripremi i strukturiranju kreditnih zahtjeva.\", \"title\": \"Bankovni krediti\"}], \"title\": \"Dostupni izvori financiranja\", \"kicker\": \"DOSTUPNI IZVORI FINANCIRANJA\"}}', '2026-06-04 10:49:10', '2026-08-25 08:31:40'
FROM `content_service_pages` AS `parent`
WHERE `parent`.`code` = 'advisory'
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `slug` = VALUES(`slug`), `meta_title` = VALUES(`meta_title`), `meta_description` = VALUES(`meta_description`), `payload` = VALUES(`payload`), `updated_at` = VALUES(`updated_at`);

INSERT INTO `content_service_page_translations` (`service_page_id`, `locale`, `title`, `slug`, `meta_title`, `meta_description`, `payload`, `created_at`, `updated_at`)
SELECT `parent`.`id`, 'en', 'Advisory', 'advisory', 'Advisory', 'Financial and tax advisory, financing, due diligence, valuations, and M&A advisory.', '{\"ma\": {\"sale\": {\"body\": \"\", \"title\": \"Company Sale\"}, \"intro\": \"\", \"title\": \"Mergers & Acquisitions (M&A)\", \"pandea\": {\"body\": [\"ALPHA CAPITALIS is a member of Pandea Global M&A, a global acquisitions network connecting investors and sellers of various businesses.\", \"We provide clients and partners with access to a broad network of international investors and act as a local one-stop shop for cross-border transactions.\"], \"title\": \"ALPHA CAPITALIS is a member of Pandea Global M&A\", \"logo_alt\": \"Pandea Global M&A\", \"body_html\": \"<p>ALPHA CAPITALIS is a member of Pandea Global M&amp;A, a global M&amp;A network connecting investors with business owners and sellers across different markets. Pandea Global M&amp;A focuses on mergers, acquisitions, corporate combinations, recapitalisations and various forms of joint ventures, with the aim of bringing local opportunities to the international financial market.</p><p></p><p>We provide our clients and partners with access to a broad network of international investors. We help local companies access cross-border transactions, while acting as a one-stop shop and local partner for international investors.</p><p></p><p>If you have a project that requires an investor or you are considering the sale of an existing business, you can contact us to present your opportunity to international investors.</p>\"}, \"meeting\": {\"intro\": \"Our team will analyse your case and recommend the right approach.\", \"title\": \"Let’s Talk About Business Advisory\", \"kicker\": \"CONTACT\", \"status\": \"We arrange the meeting around your schedule.\", \"button_label\": \"Schedule a meeting\", \"contact_title\": \"Contact us\"}, \"help_items\": [\"Business analysis and preparation of the company for sale\", \"Company valuation\", \"Transaction structuring\", \"Preparation of transaction documentation\", \"Identification of potential buyers or investors\", \"Analysis of acquisition targets\", \"Support during due diligence and negotiations\", \"Preparation and execution of transaction closing\"], \"hero_intro\": \"Support throughout mergers and acquisitions — from strategic positioning to negotiations and transaction closing.\", \"meta_title\": \"Mergers & Acquisitions (M&A)\", \"acquisition\": {\"body\": \"\", \"title\": \"Company Acquisition\"}, \"show_pandea\": true, \"blog_section\": {\"intro\": \"Latest insights from finance, tax, transactions, and business advisory.\", \"title\": \"Expert insights into finance, tax and transactions\", \"kicker\": \"INSIGHTS\", \"all_posts_label\": \"View all posts\", \"post_action_label\": \"Read more\"}, \"approach_title\": \"Our approach\", \"hero_image_alt\": \"Mergers and acquisitions — expert advisory support\", \"overview_title\": \"What are mergers and acquisitions?\", \"services_title\": \"Our services\", \"help_items_text\": \"Business analysis and preparation of the company for sale\\nCompany valuation\\nTransaction structuring\\nPreparation of transaction documentation\\nIdentification of potential buyers or investors\\nAnalysis of acquisition targets\\nSupport during due diligence and negotiations\\nPreparation and execution of transaction closing\", \"meta_description\": \"Support throughout mergers and acquisitions — from strategic positioning to negotiations and transaction closing.\", \"approach_body_html\": \"<p>We begin by understanding the objectives of the business owner or investor and analysing the company’s financial and operational position. Through a structured process, financial analysis and coordination of all transaction activities, we help clients make informed decisions and successfully complete the transaction.</p>\", \"overview_body_html\": \"<p>The sale and acquisition of companies are complex business processes involving the transfer of ownership, identification of suitable counterparties and structuring of the transaction with the aim of achieving optimal value for all parties involved.</p>\", \"services_body_html\": \"<p>We provide professional support to business owners and investors throughout the entire sale or acquisition process — from initial analysis and transaction preparation to negotiations and closing. Our approach is focused on efficient process management, protecting the client’s interests and achieving the best possible transaction terms.</p>\"}, \"tax\": {\"cards\": [], \"title\": \"Tax Advisory\", \"meeting\": {\"intro\": \"Get in touch and together we will assess which form of advisory support best suits your objectives, stage of business and specific challenge.\", \"title\": \"Let’s talk about your business decisions\", \"kicker\": \"CONTACT\", \"status\": \"We will arrange the meeting at a time that suits you.\", \"button_label\": \"Schedule a meeting\", \"contact_title\": \"Contact us\"}, \"services\": [], \"help_items\": [\"tax planning and optimisation\", \"analysis of tax risks and business compliance\", \"preparation of tax opinions and expert interpretations\", \"support during tax audits\", \"VAT advisory and international tax matters\", \"transfer pricing and related-party transactions\", \"tax advisory for business restructurings and M&A transactions\"], \"hero_intro\": \"Support with tax planning, compliance, tax reviews, transfer pricing, tax audits and transactions.\", \"meta_title\": \"Tax Advisory | ALPHA CAPITALIS\", \"blog_section\": {\"intro\": \"Latest insights from finance, tax, transactions, and business advisory.\", \"title\": \"Expert insights into finance, tax and transactions\", \"kicker\": \"INSIGHTS\", \"all_posts_label\": \"View all posts\", \"post_action_label\": \"Read more\"}, \"approach_body\": [], \"overview_body\": [], \"approach_title\": \"Our approach\", \"hero_image_alt\": \"Tax advisory — expert advisory support\", \"overview_title\": \"What is tax advisory?\", \"services_title\": \"Our services\", \"help_items_text\": \"tax planning and optimisation\\nanalysis of tax risks and business compliance\\npreparation of tax opinions and expert interpretations\\nsupport during tax audits\\nVAT advisory and international tax matters\\ntransfer pricing and related-party transactions\\ntax advisory for business restructurings and M&A transactions\", \"meta_description\": \"Support with tax planning, compliance, tax reviews, transfer pricing, tax audits and transactions.\", \"approach_body_html\": \"\", \"overview_body_html\": \"\", \"services_body_html\": \"\"}, \"hero\": {\"intro\": \"Advisory includes expert support in financial, tax, and investment matters, helping companies, investors, and entrepreneurs make quality decisions, manage risk, and create long-term value.\", \"cta_url\": \"\", \"cta_label\": \"\", \"image_alt\": \"Expert financial and strategic advisory\", \"brand_title\": \"ALPHA CAPITALIS\", \"subtitle_lead\": \"Advisory\", \"subtitle_accent\": \"advisory\"}, \"zopu\": {\"help_items_text\": \"\", \"approach_body_html\": \"\", \"overview_body_html\": \"\", \"services_body_html\": \"\"}, \"pandea\": {\"body\": [\"ALPHA CAPITALIS is a member of Pandea Global M&A, a global acquisitions network connecting investors and sellers of various businesses.\", \"We provide clients and partners with access to a broad network of international investors and act as a local one-stop shop for cross-border transactions.\"], \"title\": \"ALPHA CAPITALIS is a member of Pandea Global M&A\", \"logo_alt\": \"Pandea Global M&A\", \"body_html\": \"<p>ALPHA CAPITALIS is a member of Pandea Global M&amp;A, a global acquisitions network connecting investors and sellers of various businesses.</p><p>We provide clients and partners with access to a broad network of international investors and act as a local one-stop shop for cross-border transactions.</p>\"}, \"funding\": {\"cards\": [{\"url\": \"/eu-fondovi\", \"text\": \"EU grants, national support instruments and end-to-end project support — from identifying suitable funding opportunities to project implementation.\", \"title\": \"EU Funds\"}, {\"url\": \"/savjetovanje/pribavljanje-financiranja/bankovni-krediti\", \"text\": \"Structuring loan applications and providing support in negotiations with banks and other financial institutions.\", \"title\": \"Bank Loans\"}], \"intro\": \"Securing financing involves supporting companies in identifying and accessing appropriate sources of capital to fund business growth, investments and strategic objectives.\", \"title\": \"Securing Financing\", \"meeting\": {\"intro\": \"Our team will analyse your case and recommend the right approach.\", \"title\": \"Let’s Talk About Business Advisory\", \"kicker\": \"CONTACT\", \"status\": \"We arrange the meeting around your schedule.\", \"button_label\": \"Schedule a meeting\", \"contact_title\": \"Contact us\"}, \"services\": [], \"hero_intro\": \"Support in structuring and securing bank financing, EU grants, preferential loans and private equity capital.\", \"meta_title\": \"Securing Financing\", \"blog_section\": {\"intro\": \"Latest insights from finance, tax, transactions, and business advisory.\", \"title\": \"Expert insights into finance, tax and transactions\", \"kicker\": \"INSIGHTS\", \"all_posts_label\": \"View all posts\", \"post_action_label\": \"Read more\"}, \"approach_body\": [], \"overview_body\": [], \"advisory_cards\": [], \"approach_title\": \"Our approach\", \"hero_image_alt\": \"Financing — expert advisory support\", \"overview_title\": \"EU Funds\", \"services_title\": \"Our Services\", \"meta_description\": \"Support in structuring and securing bank financing, EU grants, preferential loans and private equity capital.\", \"approach_body_html\": \"<p>Every advisory engagement begins with understanding the business context, objectives and key risks. We analyse financial data, market position, tax and regulatory considerations, and the specific characteristics of the project in order to propose solutions that are clear, practical and focused on creating long-term value.</p><p></p><p>Our approach combines strategic thinking with practical execution — from the initial analysis through to specific decisions, documentation, stakeholder communication and project implementation.</p>\"}, \"meeting\": {\"intro\": \"Our team will analyse your case and recommend the right approach.\", \"title\": \"Let’s Talk About Business Advisory\", \"kicker\": \"CONTACT\", \"status\": \"We arrange the meeting around your schedule.\", \"button_label\": \"Schedule a meeting\", \"contact_title\": \"Contact us\"}, \"approach\": {\"body\": [], \"title\": \"Our approach\", \"kicker\": \"OUR APPROACH\", \"body_html\": \"<p>Every advisory engagement begins with understanding the business context, objectives and key risks. We analyse financial data, market position, tax and regulatory considerations, and the specific characteristics of the project in order to propose solutions that are clear, practical and focused on creating long-term value.</p><p></p><p>Our approach combines strategic thinking with practical execution — from the initial analysis through to specific decisions, documentation, stakeholder communication and project implementation.</p>\"}, \"overview\": {\"body\": [\"Financial advisory includes strategic services related to value, capital, and transactions, from business valuation and financing structure to support in mergers and acquisitions.\"], \"title\": \"Why is advisory important to you?\", \"kicker\": \"WHAT IS BUSINESS ADVISORY?\", \"body_html\": \"<p>Advisory services help you make more confident and informed financial decisions at key moments in your business. Whether you are considering an acquisition, sale or investment, need a valuation, due diligence, capital raising or financial restructuring, expert support helps you identify opportunities, manage risks and create long-term value.</p>\"}, \"financial\": {\"title\": \"Financial Advisory\", \"meeting\": {\"intro\": \"Our team will analyse your case and recommend the right approach.\", \"title\": \"Let’s Talk About Business Advisory\", \"kicker\": \"CONTACT\", \"status\": \"We arrange the meeting around your schedule.\", \"button_label\": \"Schedule a meeting\", \"contact_title\": \"Contact us\"}, \"help_items\": [\"business and financial performance analysis\", \"financial models and projections\", \"cash-flow and capital requirement planning\", \"financing structure optimisation\", \"investment and management decision support\", \"risk and business scenario assessment\"], \"hero_intro\": \"Financial advisory helps owners, management teams, and investors make better decisions based on reliable analysis, realistic projections, and a clear understanding of the company’s financial position.\", \"meta_title\": \"Financial Advisory\", \"blog_section\": {\"intro\": \"Latest insights from finance, tax, transactions, and business advisory.\", \"title\": \"Expert insights into finance, tax and transactions\", \"kicker\": \"INSIGHTS\", \"all_posts_label\": \"View all posts\", \"post_action_label\": \"Read more\"}, \"approach_body\": [\"We begin by understanding the business model, goals, and key challenges, then connect financial data with business context to turn recommendations into clear, actionable steps.\"], \"overview_body\": [\"Financial advisory helps owners, management teams, and investors make better decisions based on reliable analysis, realistic projections, and a clear understanding of the company’s financial position.\"], \"services_body\": [\"We support growth planning, financing structures, financial modelling, and the preparation of important business decisions, adapting each engagement to the client’s objective and stage of development.\"], \"approach_title\": \"Our approach\", \"hero_image_alt\": \"Financial advisory — expert advisory support\", \"overview_title\": \"What is financial advisory?\", \"services_title\": \"Our services\", \"help_items_text\": \"business and financial performance analysis\\nfinancial models and projections\\ncash-flow and capital requirement planning\\nfinancing structure optimisation\\ninvestment and management decision support\\nrisk and business scenario assessment\", \"meta_description\": \"Financial advisory helps owners, management teams, and investors make better decisions based on reliable analysis, realistic projections, and a clear understanding of the company’s financial position.\", \"approach_body_html\": \"<p>We begin by understanding the business model, goals, and key challenges, then connect financial data with business context to turn recommendations into clear, actionable steps.</p>\", \"overview_body_html\": \"<p>Financial advisory helps owners, management teams, and investors make better decisions based on reliable analysis, realistic projections, and a clear understanding of the company’s financial position.</p>\", \"services_body_html\": \"<p>We support growth planning, financing structures, financial modelling, and the preparation of important business decisions, adapting each engagement to the client’s objective and stage of development.</p>\"}, \"bank_loans\": {\"body\": [], \"title\": \"Bank Loans\", \"meeting\": {\"intro\": \"Our team will analyse your case and recommend the right approach.\", \"title\": \"Let’s Talk About Business Advisory\", \"kicker\": \"CONTACT\", \"status\": \"We arrange the meeting around your schedule.\", \"button_label\": \"Schedule a meeting\", \"contact_title\": \"Contact us\"}, \"help_items\": [\"Financing needs analysis\", \"Preparation of financial projections and investment documentation\", \"Structuring loan applications\", \"Communication and negotiations with banks\", \"Analysis of financing terms\", \"Selection of the optimal loan structure\"], \"hero_intro\": \"Structuring loan applications and providing support in negotiations with financial institutions.\", \"meta_title\": \"Bank Loans\", \"blog_section\": {\"intro\": \"Latest insights from finance, tax, transactions, and business advisory.\", \"title\": \"Expert insights into finance, tax and transactions\", \"kicker\": \"INSIGHTS\", \"all_posts_label\": \"View all posts\", \"post_action_label\": \"Read more\"}, \"approach_title\": \"Our approach\", \"hero_image_alt\": \"Bank loans — expert advisory support\", \"overview_title\": \"What are bank loans?\", \"services_title\": \"Our services\", \"help_items_text\": \"Financing needs analysis\\nPreparation of financial projections and investment documentation\\nStructuring loan applications\\nCommunication and negotiations with banks\\nAnalysis of financing terms\\nSelection of the optimal loan structure\", \"meta_description\": \"Structuring loan applications and providing support in negotiations with financial institutions.\", \"approach_body_html\": \"<p>We begin the process with a detailed analysis of the company’s operations, existing financial obligations and development plans. Based on our understanding of the business model, we prepare high-quality financial documentation and support the client throughout the entire financing process, with the aim of securing a sustainable and efficient financing solution.</p>\", \"overview_body_html\": \"<p>Bank loans are one of the most common sources of financing for business operations, investments and corporate development. They enable entrepreneurs and companies to secure the funds needed for growth, capacity expansion, project financing or optimisation of their existing financial structure.</p>\", \"services_body_html\": \"<p>We support clients throughout the process of securing bank financing — from analysing financing needs and preparing documentation to communicating with financial institutions. Our approach is focused on identifying optimal financing solutions that are aligned with the client’s business objectives and financial capacity.</p>\"}, \"valuations\": {\"body\": [], \"title\": \"Company Valuation\", \"meeting\": {\"intro\": \"Our team will analyse your case and recommend the right approach.\", \"title\": \"Let’s Talk About Business Advisory\", \"kicker\": \"CONTACT\", \"status\": \"We arrange the meeting around your schedule.\", \"button_label\": \"Schedule a meeting\", \"contact_title\": \"Contact us\"}, \"methods\": [], \"help_items\": [\"Analysis of the company’s operations and financial performance\", \"Preparation of financial models and projections\", \"Assessment of future cash flows and growth potential\", \"Application of appropriate valuation methodologies\", \"Support in company sales, acquisitions and capital increases\", \"Expert support for negotiations and strategic decision-making\"], \"hero_intro\": \"An assessment of a company’s economic value as a basis for a sale, acquisition, capital increase and other strategic activities.\", \"meta_title\": \"Company Valuation\", \"blog_section\": {\"intro\": \"Latest insights from finance, tax, transactions, and business advisory.\", \"title\": \"Expert insights into finance, tax and transactions\", \"kicker\": \"INSIGHTS\", \"all_posts_label\": \"View all posts\", \"post_action_label\": \"Read more\"}, \"methods_title\": \"Valuation Methods\", \"approach_title\": \"Our approach\", \"hero_image_alt\": \"Business valuations — expert advisory support\", \"overview_title\": \"What is a company valuation?\", \"services_title\": \"Our services\", \"help_items_text\": \"Analysis of the company’s operations and financial performance\\nPreparation of financial models and projections\\nAssessment of future cash flows and growth potential\\nApplication of appropriate valuation methodologies\\nSupport in company sales, acquisitions and capital increases\\nExpert support for negotiations and strategic decision-making\", \"meta_description\": \"An assessment of a company’s economic value as a basis for a sale, acquisition, capital increase and other strategic activities.\", \"approach_body_html\": \"<p>We begin by understanding the business model, financial position and purpose of the valuation. Using relevant valuation methodologies, including discounted cash flow, comparable transactions and comparable company analysis, we prepare a valuation that provides a clear and reliable basis for informed business decisions.</p>\", \"overview_body_html\": \"<p>Company valuation is the process of determining the economic value of a business based on an analysis of its operations, financial performance, market conditions and future growth potential. It serves as a basis for decision-making in sales, acquisitions, capital increases and other strategic transactions.</p>\", \"services_body_html\": \"<p>We provide company valuation services to business owners, investors and financial institutions, tailoring our approach to the purpose and specific characteristics of each engagement. Our goal is to provide an objective and reliable assessment of the company’s value and the key factors that influence it.</p>\"}, \"blog_section\": {\"intro\": \"Latest insights from finance, tax, transactions, and business advisory.\", \"title\": \"Expert insights into finance, tax and transactions\", \"kicker\": \"INSIGHTS\", \"all_posts_label\": \"View all posts\", \"post_action_label\": \"Read more\"}, \"due_diligence\": {\"intro\": \"\", \"title\": \"Due Diligence\", \"closing\": \"\", \"meeting\": {\"intro\": \"Our team will analyse your case and recommend the right approach.\", \"title\": \"Let’s talk about your business decisions\", \"kicker\": \"CONTACT\", \"status\": \"We arrange the meeting around your schedule.\", \"button_label\": \"Schedule a meeting\", \"contact_title\": \"Contact us\"}, \"help_items\": [\"Analysis of financial performance and business operations\", \"Assessment of the sustainability of historical earnings\", \"Identification of key risks and potential irregularities\", \"Analysis of key performance indicators (KPIs)\", \"Assessment of the business model and market position\", \"Identification of opportunities for improvement and value creation\"], \"help_title\": \"\", \"hero_intro\": \"A detailed review of a company’s operations to provide a clear understanding of its financial position, risks and opportunities before major decisions or transactions.\", \"meta_title\": \"Due Diligence\", \"blog_section\": {\"intro\": \"Latest insights from finance, tax, transactions, and business advisory.\", \"title\": \"Expert insights into finance, tax and transactions\", \"kicker\": \"INSIGHTS\", \"all_posts_label\": \"View all posts\", \"post_action_label\": \"Read more\"}, \"approach_title\": \"Our approach\", \"hero_image_alt\": \"Due diligence — expert advisory support\", \"overview_title\": \"What is Due Diligence?\", \"services_title\": \"Our services\", \"help_items_text\": \"Analysis of financial performance and business operations\\nAssessment of the sustainability of historical earnings\\nIdentification of key risks and potential irregularities\\nAnalysis of key performance indicators (KPIs)\\nAssessment of the business model and market position\\nIdentification of opportunities for improvement and value creation\", \"meta_description\": \"A detailed review of a company’s operations to provide a clear understanding of its financial position, risks and opportunities before major decisions or transactions.\", \"approach_body_html\": \"<p>We begin with a detailed review of the available financial and business information. Through a structured approach and a thorough understanding of the company’s operations, we provide a reliable basis for informed decision-making, risk mitigation and the successful achievement of business objectives.</p>\", \"overview_body_html\": \"<p>Due diligence is a detailed review of a company’s business and financial information aimed at providing a clear and objective understanding of its financial position, business risks and potential value before an important business decision or transaction.</p>\", \"services_body_html\": \"<p>We provide due diligence services to buyers, sellers and investors in mergers, acquisitions and other business transactions. Our approach focuses on identifying the key factors that influence company value and recognising potential risks and opportunities at an early stage.</p>\"}, \"service_cards\": [{\"url\": \"/advisory/raising-finance\", \"text\": \"Support in structuring and securing bank financing, EU grants, preferential loans and private equity capital.\", \"title\": \"Securing Financing\"}, {\"url\": \"/advisory/due-diligence\", \"text\": \"A detailed review of a company’s operations to provide a clear understanding of its financial position, risks and opportunities before major decisions or transactions.\", \"title\": \"Due Diligence\"}, {\"url\": \"/advisory/company-valuation\", \"text\": \"An assessment of a company’s economic value as a basis for a sale, acquisition, capital increase and other strategic activities.\", \"title\": \"Company Valuation\"}, {\"url\": \"/advisory/sale-and-purchase-of-companies\", \"text\": \"Support throughout mergers and acquisitions — from strategic positioning to negotiations and transaction closing.\", \"title\": \"Mergers & Acquisitions (M&A)\"}, {\"url\": \"/advisory/tax-advisory\", \"text\": \"Support with tax planning, compliance, tax reviews, transfer pricing, tax audits and transactions.\", \"title\": \"Tax Advisory\"}], \"video_section\": {\"intro\": \"\", \"title\": \"\"}, \"services_intro\": {\"intro\": \"Our team combines transaction experience, financial analysis, and a structured delivery process to help clients prepare clearly and make better decisions.\", \"title\": \"Our services\", \"kicker\": \"BUSINESS ADVISORY SERVICES\", \"card_action_label\": \"Read more\"}, \"source_modules\": {\"intro\": \"Funding calls, financial instruments and tax incentives are presented separately from our advisory services so that you can more easily identify the source of financing most relevant to your needs.\", \"items\": [], \"title\": \"Available sources of financing\", \"kicker\": \"AVAILABLE FUNDING SOURCES\"}}', '2026-06-04 10:49:10', '2026-08-25 08:55:54'
FROM `content_service_pages` AS `parent`
WHERE `parent`.`code` = 'advisory'
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `slug` = VALUES(`slug`), `meta_title` = VALUES(`meta_title`), `meta_description` = VALUES(`meta_description`), `payload` = VALUES(`payload`), `updated_at` = VALUES(`updated_at`);

INSERT INTO `content_service_page_translations` (`service_page_id`, `locale`, `title`, `slug`, `meta_title`, `meta_description`, `payload`, `created_at`, `updated_at`)
SELECT `parent`.`id`, 'hr', 'Usluge', 'usluge', 'Usluge', 'Pregled usluga ALPHA CAPITALISA: revizija, računovodstvo i poslovno savjetovanje.', '{\"showcase\": {\"intro\": \"Kroz integrirani pristup reviziji, računovodstvu i financijskom savjetovanju stvaramo dodatnu vrijednost pomažući klijentima da posluju sigurnije, transparentnije i učinkovitije.\", \"outro\": [\"Kroz integrirani pristup reviziji, računovodstvu i financijskom savjetovanju stvaramo dodatnu vrijednost za klijente koji žele stabilan rast, jasnije odluke i pouzdanu podršku u ključnim poslovnim trenucima.\", \"Naša podrška omogućuje bolje upravljanje financijama, kvalitetnije strateško planiranje i sigurnije donošenje odluka.\"], \"title_lead\": \"Naše usluge\", \"card_action_label\": \"SAZNAJTE VIŠE\"}, \"video_section\": {\"intro\": \"\", \"title\": \"\"}, \"primary_pillars\": [{\"key\": \"audit\", \"url\": \"/revizija\", \"text\": \"Neovisna provjera financijskih izvještaja koja povećava povjerenje vlasnika, investitora i partnera.\", \"title\": \"Revizija\", \"bullets\": [\"Pomažemo vlasnicima, investitorima i upravi da imaju potpunu sigurnost u financijske izvještaje.\", \"Revizija smanjuje rizik pogrešnih odluka jer potvrđuje da su podaci točni, potpuni i u skladu s propisima.\", \"Kroz neovisnu provjeru dobivate jasnu sliku stvarnog financijskog stanja poduzeća, što jača povjerenje banaka, partnera i regulatora.\"], \"subtitle\": \"sigurnost i povjerenje u brojke\", \"image_alt\": \"Potpisivanje poslovnog dokumenta za stolom\", \"action_label\": \"Detaljnije\"}, {\"key\": \"accounting\", \"url\": \"/racunovodstvo\", \"text\": \"Precizno vođenje knjiga i pravovremeno izvještavanje koje oslobađa menadžment za strateške odluke.\", \"title\": \"Računovodstvo\", \"bullets\": [\"Omogućujemo da vaše poslovanje bude financijski uredno, pregledno i uvijek spremno za odluke.\", \"To znači da u svakom trenutku imate točne podatke o prihodima, troškovima i rezultatu, bez kašnjenja i nejasnoća.\", \"Umjesto da reagirate na probleme, možete upravljati poslovanjem na temelju pouzdanih informacija.\"], \"subtitle\": \"kontrola i jasnoća poslovanja\", \"image_alt\": \"Rad na financijskim podacima na prijenosnom računalu\", \"action_label\": \"Detaljnije\"}, {\"key\": \"advisory\", \"url\": \"/savjetovanje\", \"text\": \"Financijsko i porezno savjetovanje te pribavljanje kapitala - sve na jednom mjestu.\", \"title\": \"Savjetovanje\", \"bullets\": [\"Pomažemo društvima, investitorima i poduzetnicima u donošenju kvalitetnih odluka, upravljanju rizicima i stvaranju dugoročne vrijednosti.\", \"Pružamo podršku u procjenama vrijednosti, due diligence postupcima, M&A procesima i strukturiranju financiranja.\", \"EU fondovi, bankovni krediti i porezne olakšice povezani su u okviru pribavljanja financiranja.\"], \"subtitle\": \"rast, optimizacija i bolji financijski izbor\", \"image_alt\": \"Poslovni razgovor tijekom savjetovanja\", \"action_label\": \"Detaljnije\"}]}', '2026-07-08 13:29:21', '2026-08-25 08:27:49'
FROM `content_service_pages` AS `parent`
WHERE `parent`.`code` = 'services'
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `slug` = VALUES(`slug`), `meta_title` = VALUES(`meta_title`), `meta_description` = VALUES(`meta_description`), `payload` = VALUES(`payload`), `updated_at` = VALUES(`updated_at`);

INSERT INTO `content_service_page_translations` (`service_page_id`, `locale`, `title`, `slug`, `meta_title`, `meta_description`, `payload`, `created_at`, `updated_at`)
SELECT `parent`.`id`, 'en', 'Services', 'services', 'Services', 'Overview of ALPHA CAPITALIS services: audit, accounting, and business advisory.', '{\"showcase\": {\"intro\": \"Through an integrated approach to audit, accounting, and financial advisory, we create added value by helping our clients operate more securely, transparently, and efficiently.\", \"outro\": [\"Our support helps companies manage finance more clearly, plan strategically, and make safer decisions in key business moments.\"], \"title_lead\": \"Our services\", \"card_action_label\": \"LEARN MORE\"}, \"video_section\": {\"intro\": \"\", \"title\": \"\"}, \"primary_pillars\": [{\"key\": \"audit\", \"url\": \"/revizija\", \"text\": \"An independent review of financial statements that builds trust among owners, investors and partners.\", \"title\": \"Audit\", \"bullets\": [\"We help owners, investors, and management gain confidence in financial statements.\", \"Audit reduces the risk of wrong decisions by confirming that data is accurate, complete, and compliant.\", \"Through independent review you gain a clear view of the company financial position, strengthening trust with banks, partners, and regulators.\"], \"subtitle\": \"confidence and trust in numbers\", \"image_alt\": \"Signing a business document at a desk\", \"action_label\": \"Learn more\"}, {\"key\": \"accounting\", \"url\": \"/racunovodstvo\", \"text\": \"Accurate bookkeeping and timely reporting that empower management to make strategic decisions.\", \"title\": \"Accounting\", \"bullets\": [\"We help keep your business financially organized, transparent, and ready for decisions.\", \"That means accurate data on revenue, costs, and results at any moment, without delays or uncertainty.\", \"Instead of reacting to problems, you can manage the business based on reliable information.\"], \"subtitle\": \"control and clarity in business\", \"image_alt\": \"Working with financial data on a laptop\", \"action_label\": \"Learn more\"}, {\"key\": \"advisory\", \"url\": \"/savjetovanje\", \"text\": \"Financial and tax advisory, along with capital raising — all in one place.\", \"title\": \"Advisory\", \"bullets\": [\"We help companies, investors, and entrepreneurs make better decisions, manage risk, and create long-term value.\", \"We support valuations, due diligence, M&A processes, and financing structuring.\", \"EU funds, bank loans, and tax incentives are connected within the capital raising framework.\"], \"subtitle\": \"growth, optimisation and smarter financial decisions\", \"image_alt\": \"Business conversation during an advisory meeting\", \"action_label\": \"Learn more\"}]}', '2026-07-08 13:29:21', '2026-08-25 06:32:38'
FROM `content_service_pages` AS `parent`
WHERE `parent`.`code` = 'services'
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `slug` = VALUES(`slug`), `meta_title` = VALUES(`meta_title`), `meta_description` = VALUES(`meta_description`), `payload` = VALUES(`payload`), `updated_at` = VALUES(`updated_at`);

INSERT INTO `content_info_page_translations` (`page_id`, `locale`, `title`, `slug`, `excerpt`, `body_html`, `meta_title`, `meta_description`, `payload`, `created_at`, `updated_at`)
SELECT `parent`.`id`, 'hr', 'Ljudski potencijali', 'karijera', 'Regrutacija, zapošljavanje i usmjeravanje zaposlenika.', '<h2><br></h2>', 'Karijera | Alpha Capitalis', 'Karijera u Alpha Capitalisu: upoznajte naš selekcijski proces i pošaljite nam svoj životopis.', '{\"career_page\": {\"form\": {\"cv\": \"Upload CV-a\", \"email\": \"Email\", \"intro\": \"Ispunite osnovne podatke i učitajte životopis kako bismo vas mogli kontaktirati kada prepoznamo podudaranje s otvorenim pozicijama.\", \"title\": \"Pošalji nam svoj životopis\", \"submit\": \"Pošalji prijavu\", \"cv_help\": \"Podržani formati: PDF, DOC i DOCX. Maksimalna veličina datoteke je 5 MB.\", \"message\": \"Poruka (opcionalno)\", \"cv_empty\": \"Datoteka nije odabrana.\", \"cv_button\": \"Odaberi datoteku\", \"last_name\": \"Prezime\", \"first_name\": \"Ime\", \"accept_terms\": \"Slažem se s obradom osobnih podataka za potrebe selekcijskog postupka.\"}, \"intro\": {\"body\": [\"Tražimo znatiželjne ljude koji žele učiti, preuzimati odgovornost i zajedno s nama graditi nešto dugoročno.\", \"ALPHA CAPITALIS danas okuplja 75 stručnjaka iz područja računovodstva, financija, revizije, EU fondova i savjetovanja. U našem Sky Officeu znanje dijelimo otvoreno, pomažemo jedni drugima i ozbiljan posao gradimo u atmosferi u kojoj ljudi mogu biti svoji.\", \"Od prvog dana radit ćeš na stvarnim poslovnim izazovima, uz mentora, podršku iskusnih kolega i prostor da predložiš bolji način rada. Želimo da posao bude mjesto na kojem rasteš i kojem se rado vraćaš.\"], \"title\": \"Mjesto gdje ljudi i karijere rastu\", \"kicker\": \"Rastemo zajedno\", \"highlight\": \"Tražimo ljude, ne samo životopise.\", \"image_alt\": \"\", \"stat_label\": \"stručnjaka iz računovodstva, financija, revizije i savjetovanja\", \"stat_value\": \"75\", \"button_label\": \"OTVORENE POZICIJE\", \"values_label\": \"Što nudimo\", \"section_title\": \"Karijera u ALPHA CAPITALISU\", \"hero_body_html\": \"<p>ALPHA CAPITALIS danas okuplja 75 stručnjaka iz područja računovodstva, financija, revizije, EU fondova i savjetovanja. U našem Sky Officeu znanje dijelimo otvoreno, pomažemo jedni drugima i ozbiljan posao gradimo u atmosferi u kojoj ljudi mogu biti svoji.</p><p>Od prvog dana radit ćeš na stvarnim poslovnim izazovima, uz mentora, podršku iskusnih kolega i prostor da predložiš bolji način rada. Želimo da posao bude mjesto na kojem rasteš i kojem se rado vraćaš.</p>\"}, \"values\": [\"povjerenje\", \"podršku\", \"priliku za razvoj\", \"prostor za ideje\", \"tim koji ih gura naprijed\"], \"process\": {\"intro\": \"Vjerujemo da se potencijal razvija kroz iskustvo, mentorstvo i prilike. Zato naši zaposlenici od prvog dana aktivno sudjeluju u projektima, surađuju s klijentima i razvijaju stručna znanja kroz rad s različitim industrijama i poslovnim izazovima.\", \"steps\": [{\"step\": \"01\", \"title\": \"Povjerenje\", \"description\": \"Od prvog dana dobivaš prostor sudjelovati u stvarnim projektima i preuzimati odgovornost uz jasnu podršku tima.\"}, {\"step\": \"02\", \"title\": \"Podrška\", \"description\": \"Učiš kroz mentorstvo, suradnju s iskusnim stručnjacima i otvoreno dijeljenje znanja unutar tima.\"}, {\"step\": \"03\", \"title\": \"Prilika za razvoj\", \"description\": \"Radiš s različitim industrijama i poslovnim izazovima, bez čekanja godinama da pokažeš što znaš.\"}, {\"step\": \"04\", \"title\": \"Prostor za ideje\", \"description\": \"Cijenimo proaktivnost, nova rješenja i ljude koji žele aktivno graditi bolji način rada.\"}], \"title\": \"Razvoj koji nije samo fraza\", \"kicker\": \"Zašto ALPHA CAPITALIS?\", \"title_line_one\": \"Razvoj koji nije\", \"title_line_two\": \"samo fraza\"}, \"stories\": [{\"list\": [], \"title\": \"Ljudi zbog kojih ostaješ\", \"kicker\": \"Tim\", \"body_html\": \"<p>Možeš imati odličan posao, ali bez dobrog tima ništa nema smisla.</p><p>U ALPHA CAPITALISU gradimo kulturu međusobnog poštovanja, suradnje i otvorene komunikacije. Vjerujemo u dijeljenje znanja, podršku među kolegama i atmosferu u kojoj ljudi mogu biti profesionalni, ali i svoji.</p><p>Ozbiljni smo u poslu, ali vjerujemo da dobra atmosfera i kvalitetni odnosi čine veliku razliku.</p>\", \"list_text\": \"\", \"paragraphs\": [\"Možeš imati odličan posao, ali bez dobrog tima ništa nema smisla.\", \"U ALPHA CAPITALISU gradimo kulturu međusobnog poštovanja, suradnje i otvorene komunikacije. Vjerujemo u dijeljenje znanja, podršku među kolegama i atmosferu u kojoj ljudi mogu biti profesionalni, ali i svoji.\", \"Ozbiljni smo u poslu, ali vjerujemo da dobra atmosfera i kvalitetni odnosi čine veliku razliku.\"]}, {\"list\": [], \"title\": \"Okruženje koje te potiče na više\", \"kicker\": \"Izazovi\", \"body_html\": \"<p>Radimo s poduzetnicima, obiteljskim tvrtkama i kompanijama koje rastu i razvijaju se. Zato ni naš posao nije rutinski.</p><p>Svaki projekt donosi nove izazove, nova znanja i priliku da razvijaš širu poslovnu perspektivu.</p><p>Ako voliš dinamiku, odgovornost i kontinuirani razvoj - osjećat ćeš se kao doma.</p>\", \"list_text\": \"\", \"paragraphs\": [\"Radimo s poduzetnicima, obiteljskim tvrtkama i kompanijama koje rastu i razvijaju se. Zato ni naš posao nije rutinski.\", \"Svaki projekt donosi nove izazove, nova znanja i priliku da razvijaš širu poslovnu perspektivu.\", \"Ako voliš dinamiku, odgovornost i kontinuirani razvoj - osjećat ćeš se kao doma.\"]}, {\"list\": [\"znanje\", \"iskustvo\", \"odnose\", \"samostalnost\", \"karijeru\"], \"title\": \"Rastemo zajedno\", \"kicker\": \"Rast\", \"body_html\": \"<p>ALPHA CAPITALIS nije mjesto gdje samo dolaziš odraditi posao.</p><p>Naš cilj je stvoriti okruženje u kojem ljudi dugoročno žele ostati, razvijati se i biti ponosni na ono što zajedno gradimo.</p>\", \"list_text\": \"znanje\\niskustvo\\nodnose\\nsamostalnost\\nkarijeru\", \"paragraphs\": [\"ALPHA CAPITALIS nije mjesto gdje samo dolaziš odraditi posao.\", \"Naš cilj je stvoriti okruženje u kojem ljudi dugoročno žele ostati, razvijati se i biti ponosni na ono što zajedno gradimo.\"]}], \"application\": {\"title\": \"Otvorene pozicije\", \"kicker\": \"Prijave\", \"body_html\": \"<p>Tražimo ambiciozne, odgovorne i proaktivne ljude koji žele razvijati svoje znanje i karijeru u okruženju koje potiče rast.</p><p>Ne vidiš otvorenu poziciju?</p><p>Uvijek smo otvoreni za kvalitetne ljude. Ako vjeruješ da bi bio dobar dio ALPHA CAPITALIS tima, pošalji nam svoj životopis i predstavi se. Možda upravo ti budeš naše sljedeće veliko pojačanje.</p>\", \"highlight\": \"Pronađi svoje mjesto u našem timu\", \"paragraphs\": [\"Tražimo ambiciozne, odgovorne i proaktivne ljude koji žele razvijati svoje znanje i karijeru u okruženju koje potiče rast.\", \"Ne vidiš otvorenu poziciju?\", \"Uvijek smo otvoreni za kvalitetne ljude. Ako vjeruješ da bi bio dobar dio ALPHA CAPITALIS tima, pošalji nam svoj životopis i predstavi se. Možda upravo ti budeš naše sljedeće veliko pojačanje.\"]}, \"values_text\": \"povjerenje\\npodršku\\npriliku za razvoj\\nprostor za ideje\\ntim koji ih gura naprijed\", \"stories_section\": {\"intro\": \"Više od radnog mjesta\", \"title\": \"Život u ALPHA CAPITALISU\"}}}', '2026-03-22 07:22:16', '2026-08-21 08:30:40'
FROM `content_info_pages` AS `parent`
WHERE `parent`.`code` = 'career'
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `slug` = VALUES(`slug`), `excerpt` = VALUES(`excerpt`), `body_html` = VALUES(`body_html`), `meta_title` = VALUES(`meta_title`), `meta_description` = VALUES(`meta_description`), `payload` = VALUES(`payload`), `updated_at` = VALUES(`updated_at`);

INSERT INTO `content_info_page_translations` (`page_id`, `locale`, `title`, `slug`, `excerpt`, `body_html`, `meta_title`, `meta_description`, `payload`, `created_at`, `updated_at`)
SELECT `parent`.`id`, 'en', 'Careers', 'careers', 'We look for people, not just CVs.', '<div class=\"ac-career-layout\">\n    <section class=\"ac-career-section ac-career-section--intro\">\n        <p class=\"ac-career-eyebrow\">Human potential</p>\n        <div class=\"ac-career-intro-grid\">\n            <div class=\"ac-career-intro-copy\">\n                <h2>Join our team</h2>\n                <p>ALPHA CAPITALIS has been operating since 2012 with a clear goal: supporting clients in the world of finance through every stage of business growth.</p>\n                <p>We have built a team of experts in finance, audit, accounting and tax who work together to provide an integrated solution for investors, entrepreneurs and managers. Our team members bring years of experience in investment banking, financial advisory, EU funds, audit, restructuring, controlling and management accounting.</p>\n            </div>\n\n            <aside class=\"ac-career-aside\">\n                <p class=\"ac-career-aside-label\">Focus</p>\n                <p class=\"ac-career-aside-value\">Recruitment, hiring and employee development.</p>\n            </aside>\n        </div>\n    </section>\n\n    <section class=\"ac-career-section\">\n        <div class=\"ac-career-heading\">\n            <p class=\"ac-career-kicker\">Hiring process</p>\n            <h2>The ALPHA CAPITALIS selection process</h2>\n            <p>The process is clear, structured and designed to help both the candidate and the team get to know each other properly.</p>\n        </div>\n\n        <div class=\"ac-career-steps\">\n            <article class=\"ac-career-step\">\n                <p class=\"ac-career-step-number\">01</p>\n                <h3>Application review</h3>\n                <p>Your application is reviewed by our people team, who assess the profile and contact candidates whose experience matches an open role.</p>\n            </article>\n\n            <article class=\"ac-career-step\">\n                <p class=\"ac-career-step-number\">02</p>\n                <h3>Knowledge assessment</h3>\n                <p>Candidates who move forward are invited to general and technical testing so we can better understand their expertise and way of thinking.</p>\n            </article>\n\n            <article class=\"ac-career-step\">\n                <p class=\"ac-career-step-number\">03</p>\n                <h3>Interviews</h3>\n                <p>After successful testing, selected candidates have an interview with our people team and then continue with conversations with the relevant team and senior management.</p>\n            </article>\n\n            <article class=\"ac-career-step\">\n                <p class=\"ac-career-step-number\">04</p>\n                <h3>Offer and onboarding</h3>\n                <p>The final stage includes the employment offer, contract signing and onboarding, where you learn more about our business, values, culture and colleagues.</p>\n            </article>\n        </div>\n    </section>\n\n    <section class=\"ac-career-section\">\n        <div class=\"ac-career-cta-grid\">\n            <div>\n                <div class=\"ac-career-heading\">\n                    <p class=\"ac-career-kicker\">Career at Alpha Capitalis</p>\n                    <h2>Become part of ALPHA CAPITALIS</h2>\n                </div>\n            </div>\n\n            <div class=\"ac-career-copy\">\n                <p>Whether you are an experienced professional ready for the next step or a recent graduate looking for a strong start, ALPHA CAPITALIS offers room for personal and professional growth in a dynamic working environment.</p>\n                <p>We encourage professional certifications, knowledge sharing through internal education and rotational development supported by expert mentoring in finance, audit, accounting and tax.</p>\n                <p>We are looking for motivated, high-performing people who want to keep learning and growing, and whose values align with the values of our organisation.</p>\n                <p>Get to know us and become part of the ALPHA CAPITALIS team.</p>\n\n                <div class=\"ac-career-actions\">\n                    <a class=\"ac-career-primary-link\" href=\"__CAREER_MAILTO__\">Send us your CV</a>\n                    <a class=\"ac-career-secondary-link\" href=\"__CONTACT_URL__\">Contact us</a>\n                </div>\n\n                <p class=\"ac-career-direct-line\">You can also send your CV directly to <a href=\"__CAREER_MAILTO__\">info@alphacapitalis.com</a>.</p>\n            </div>\n        </div>\n    </section>\n</div>', 'Careers at ALPHA CAPITALIS | ALPHA CAPITALIS', 'We are looking for curious people who want to learn, take responsibility and build something for the long term together with us.', '{\"career_page\": {\"form\": {\"cv\": \"Upload CV\", \"email\": \"Email\", \"intro\": \"Fill in your basic information and upload your CV so we can contact you when we identify a match with one of our open positions.\", \"title\": \"Send us your CV\", \"submit\": \"Send application\", \"cv_help\": \"Supported formats: PDF, DOC and DOCX. Maximum file size: 5 MB.\", \"message\": \"Message (optional)\", \"cv_empty\": \"No file selected.\", \"cv_button\": \"Choose file\", \"last_name\": \"Last name\", \"first_name\": \"First name\", \"accept_terms\": \"I agree to the processing of my personal data for recruitment purposes.\"}, \"intro\": {\"body\": [\"We are looking for curious people who want to learn, take responsibility and build something for the long term together with us.\", \"Today, ALPHA CAPITALIS brings together 75 experts in accounting, finance, audit, EU funds and advisory. In our Sky Office, we share knowledge openly, help one another and build serious work in an atmosphere where people can be themselves.\", \"With us, you will work on real business challenges, collaborate with experienced professionals and have the opportunity to grow faster than in a classic corporate environment.\"], \"title\": \"A place where people and careers grow\", \"kicker\": \"We grow together\", \"highlight\": \"We look for people, not just CVs.\", \"image_alt\": \"ALPHA CAPITALIS team at a team-building event\", \"stat_label\": \"professionals in accounting, finance, audit and advisory\", \"stat_value\": \"75\", \"button_label\": \"OPEN POSITIONS\", \"values_label\": \"\", \"section_title\": \"Careers at ALPHA CAPITALIS\", \"hero_body_html\": \"<p>Today, ALPHA CAPITALIS brings together 75 professionals in accounting, finance, audit, EU funds and advisory. At our Sky Office, we share knowledge openly, support one another and do serious work in an environment where people can be themselves.</p><p><br></p><p>From day one, you will work on real business challenges, with a mentor, support from experienced colleagues and the freedom to suggest better ways of doing things. We want work to be a place where you grow — and a place you enjoy coming back to.</p>\"}, \"values\": [\"trust\", \"support\", \"opportunities to grow\", \"room for ideas\", \"a team that moves them forward\"], \"process\": {\"intro\": \"We believe potential develops through experience, mentorship and opportunity. That is why, from day one, our people actively participate in projects, work with clients and develop their professional expertise across different industries and business challenges.\", \"steps\": [{\"step\": \"01\", \"title\": \"Trust\", \"description\": \"From day one, you have the opportunity to contribute to real projects and take responsibility, with clear support from the team.\"}, {\"step\": \"02\", \"title\": \"Support\", \"description\": \"You learn through mentorship, collaboration with experienced professionals and open knowledge sharing across the team.\"}, {\"step\": \"03\", \"title\": \"Opportunity to grow\", \"description\": \"You work across different industries and business challenges without having to wait years for the opportunity to show what you can do.\"}, {\"step\": \"04\", \"title\": \"Room for ideas\", \"description\": \"We value initiative, new solutions and people who want to actively shape better ways of working.\"}], \"title\": \"Development that is more than just a phrase\", \"kicker\": \"Why ALPHA CAPITALIS?\", \"title_line_one\": \"Development that is\", \"title_line_two\": \"more than a phrase\"}, \"stories\": [{\"list\": [], \"title\": \"People who make you want to stay\", \"kicker\": \"Team\", \"body_html\": \"<p>You can have a great job, but without a great team, it does not mean much.</p><p><br></p><p>At ALPHA CAPITALIS, we build a culture of mutual respect, collaboration and open communication. We believe in sharing knowledge, supporting one another and creating an environment where people can be professional while still being themselves.</p><p><br></p><p>We take our work seriously, but we also believe that a positive atmosphere and strong relationships make a real difference.</p>\", \"list_text\": \"\", \"paragraphs\": [\"You can have a great job, but without a good team it does not mean much.\", \"At ALPHA CAPITALIS, we build a culture of mutual respect, collaboration and open communication. We believe in knowledge sharing, support among colleagues and an atmosphere where people can be professional and still be themselves.\", \"We are serious about work, but we believe a good atmosphere and quality relationships make a real difference.\"]}, {\"list\": [], \"title\": \"An environment that pushes you further\", \"kicker\": \"Challenges\", \"body_html\": \"<p>We work with entrepreneurs, family businesses and companies that are growing and evolving. That means our work is never routine.</p><p><br></p><p>Every project brings new challenges, new knowledge and an opportunity to develop a broader business perspective.</p><p><br></p><p>If you enjoy a dynamic environment, responsibility and continuous development, you will feel right at home.</p>\", \"list_text\": \"\", \"paragraphs\": [\"We work with entrepreneurs, family businesses and growing companies. That is why our work is not routine.\", \"Every project brings new challenges, new knowledge and an opportunity to develop a broader business perspective.\", \"If you like dynamics, responsibility and continuous development, you will feel at home.\"]}, {\"list\": [\"knowledge\", \"experience\", \"relationships\", \"independence\", \"career\"], \"title\": \"We grow together\", \"kicker\": \"Growth\", \"body_html\": \"<p>ALPHA CAPITALIS is not a place where you simply come to do a job.</p><p><br></p><p>Our goal is to create an environment where people want to stay for the long term, develop professionally and feel proud of what we are building together.</p>\", \"list_text\": \"knowledge\\nexperience\\nrelationships\\nindependence\\ncareer\", \"paragraphs\": [\"ALPHA CAPITALIS is not a place where you only come to finish tasks.\", \"Our goal is to create an environment where people want to stay long-term, develop and be proud of what we build together.\"]}], \"application\": {\"title\": \"Open positions\", \"kicker\": \"Applications\", \"body_html\": \"<p>We are looking for ambitious, responsible and proactive people who want to develop their knowledge and careers in an environment that encourages growth.</p><p><br></p><p>Don’t see a suitable open position?</p><p><br></p><p>We are always open to meeting talented people. If you believe you would be a great addition to the ALPHA CAPITALIS team, send us your CV and tell us a little about yourself. You might be exactly the person we are looking for next.</p>\", \"highlight\": \"Find your place on our team\", \"paragraphs\": [\"We are looking for ambitious, responsible and proactive people who want to develop their knowledge and career in an environment that encourages growth.\", \"Do not see an open position?\", \"We are always open to quality people. If you believe you would be a good part of the ALPHA CAPITALIS team, send us your CV and introduce yourself.\"]}, \"values_text\": \"trust\\nsupport\\nopportunities to grow\\nroom for ideas\\na team that moves them forward\", \"stories_section\": {\"intro\": \"More than a workplace\", \"title\": \"Life at ALPHA CAPITALIS\"}}}', '2026-03-22 07:22:16', '2026-08-25 07:17:17'
FROM `content_info_pages` AS `parent`
WHERE `parent`.`code` = 'career'
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `slug` = VALUES(`slug`), `excerpt` = VALUES(`excerpt`), `body_html` = VALUES(`body_html`), `meta_title` = VALUES(`meta_title`), `meta_description` = VALUES(`meta_description`), `payload` = VALUES(`payload`), `updated_at` = VALUES(`updated_at`);

INSERT INTO `content_info_page_translations` (`page_id`, `locale`, `title`, `slug`, `excerpt`, `body_html`, `meta_title`, `meta_description`, `payload`, `created_at`, `updated_at`)
SELECT `parent`.`id`, 'hr', 'O nama', 'o-nama', 'Naša priča, vrijednosti, tim i povjerenje koje gradimo s klijentima.', NULL, 'O nama | Alpha Capitalis', 'Upoznajte ALPHA CAPITALIS, našu priču, vrijednosti, tim, društveno odgovorno poslovanje i reference.', '{\"about_page\": {\"why\": {\"quote\": \"Kvalitetna stručna podrška nije samo odgovor kada se problem već pojavi.\", \"title\": \"Uz vas prije, tijekom i nakon svake važne odluke\", \"kicker\": \"Zašto postojimo\", \"body_html\": \"<p>Naš je cilj pomoći klijentima da prevladaju prepreke prije nego što postanu ozbiljan problem, da izbjegnu najteže scenarije kada je to moguće i da, ako se ipak nađu u zahtjevnoj situaciji, zajedno pronađemo put dalje.</p><p>Vjerujemo da kvalitetna stručna podrška znači imati prave ljude uz sebe prije, tijekom i nakon svake važne poslovne odluke.</p>\", \"paragraphs\": [\"Naš je cilj pomoći klijentima da prevladaju prepreke prije nego što postanu ozbiljan problem, da izbjegnu najteže scenarije kada je to moguće i da, ako se ipak nađu u zahtjevnoj situaciji, zajedno pronađemo put dalje.\", \"Vjerujemo da kvalitetna stručna podrška znači imati prave ljude uz sebe prije, tijekom i nakon svake važne poslovne odluke.\"]}, \"hero\": {\"lead\": \"Više od stručne podrške. Partner kroz svaku fazu poslovanja.\", \"title\": \"Naša priča\", \"eyebrow\": \"O nama\", \"image_alt\": \"ALPHA CAPITALIS tim\", \"stat_label\": \"klijenata kojima svakodnevno pružamo podršku\", \"stat_value\": \"700\"}, \"team\": {\"body\": \"Zato u ALPHA CAPITALISU povezujemo stručnjake iz računovodstva, revizije, poreza, financija i poslovnog savjetovanja. Kada je potrebno, za istim izazovom okupljamo različite perspektive i znanja kako bi klijent dobio povezan tim koji razumije širi kontekst njegova poslovanja i može pružiti podršku kroz različite faze razvoja.\", \"intro\": \"Različiti izazovi zahtijevaju različita znanja. Svako poslovanje je drugačije, a ono što je jednoj tvrtki potrebno u fazi osnivanja nije isto što joj je potrebno tijekom rasta, širenja, reorganizacije ili prijenosa poslovanja na novu generaciju.\", \"label\": \"Naš tim\", \"stats\": [{\"label\": \"stručnjaka\", \"value\": \"75\"}, {\"label\": \"članova uprave\", \"value\": \"9\"}, {\"label\": \"klijenata\", \"value\": \"700\"}, {\"label\": \"ureda u Zagrebu, Vinkovcima i Rijeci\", \"value\": \"3\"}], \"title\": \"Tim stručnjaka na jednom mjestu\", \"kicker\": \"TIM\", \"body_html\": \"<p>Različiti izazovi zahtijevaju različita znanja. Svako poslovanje je drugačije, a ono što je jednoj tvrtki potrebno u fazi osnivanja nije isto što joj je potrebno tijekom rasta, širenja, reorganizacije ili prijenosa poslovanja na novu generaciju.</p><p>Zato u ALPHA CAPITALISU povezujemo stručnjake iz računovodstva, revizije, poreza, financija i poslovnog savjetovanja. Kada je potrebno, za istim izazovom okupljamo različite perspektive i znanja kako bi klijent dobio povezan tim koji razumije širi kontekst njegova poslovanja i može pružiti podršku kroz različite faze razvoja.</p>\", \"button_label\": \"Upoznaj cijeli tim\"}, \"story\": {\"title\": \"Više od stručne podrške. Partner kroz svaku fazu poslovanja.\", \"kicker\": \"Naša priča\", \"body_html\": \"<p>ALPHA CAPITALIS okuplja stručnjake iz područja računovodstva, revizije i savjetovanja s jednom zajedničkom idejom – pomoći poduzetnicima da sigurnije prolaze kroz sve faze poslovanja.</p>\\n<p><strong>Jer poslovanje nije ravna linija.</strong></p>\\n<p>Tvrtke rastu, mijenjaju se, ulaze u nova tržišta, zapošljavaju, ulažu, prolaze kroz izazove i donose odluke koje mogu odrediti njihov sljedeći korak. Ponekad je potrebno pronaći priliku za rast. Ponekad zaštititi ono što se godinama gradilo. A ponekad pronaći rješenje kada stvari ne idu prema planu.</p>\\n<p><strong>Upravo zato postojimo.</strong></p>\\n<p>Želimo biti uz poduzetnike kada donose važne odluke, kada prelaze iz jedne faze poslovanja u drugu i kada se susreću s problemima za koje nije dovoljno jedno mišljenje ili jedno područje stručnosti.</p>\\n<p><strong>Jer jedna osoba ne može znati i riješiti sve.</strong></p>\\n<p>Ali <strong>snažan multidisciplinarni tim</strong> može sagledati poslovanje iz više perspektiva, povezati različita znanja i pomoći pronaći cjelovitije rješenje.</p>\\n<p>Zato naši klijenti uz sebe nemaju samo jednog savjetnika. <strong>Imaju tim stručnjaka koji razumije različite dijelove poslovanja</strong> i koji može pružiti podršku onda kada je ona najpotrebnija, od svakodnevnog računovodstva i poreznih pitanja do financijskih odluka, revizije, rasta, promjena i složenijih poslovnih izazova.</p>\", \"paragraphs\": [\"ALPHA CAPITALIS okuplja stručnjake iz područja računovodstva, revizije i savjetovanja s jednom zajedničkom idejom – pomoći poduzetnicima da sigurnije prolaze kroz sve faze poslovanja.\", \"Jer poslovanje nije ravna linija.\", \"Tvrtke rastu, mijenjaju se, ulaze u nova tržišta, zapošljavaju, ulažu, prolaze kroz izazove i donose odluke koje mogu odrediti njihov sljedeći korak. Ponekad je potrebno pronaći priliku za rast. Ponekad zaštititi ono što se godinama gradilo. A ponekad pronaći rješenje kada stvari ne idu prema planu.\", \"Upravo zato postojimo.\", \"Želimo biti uz poduzetnike kada donose važne odluke, kada prelaze iz jedne faze poslovanja u drugu i kada se susreću s problemima za koje nije dovoljno jedno mišljenje ili jedno područje stručnosti.\", \"Jer jedna osoba ne može znati i riješiti sve.\", \"Ali snažan multidisciplinarni tim može sagledati poslovanje iz više perspektiva, povezati različita znanja i pomoći pronaći cjelovitije rješenje.\", \"Zato naši klijenti uz sebe nemaju samo jednog savjetnika. Imaju tim stručnjaka koji razumije različite dijelove poslovanja i koji može pružiti podršku onda kada je ona najpotrebnija, od svakodnevnog računovodstva i poreznih pitanja do financijskih odluka, revizije, rasta, promjena i složenijih poslovnih izazova.\"]}, \"values\": {\"intro\": \"U ALPHA CAPITALISU vrijednosti nisu samo riječi - one određuju kako razmišljamo, kako radimo i kako gradimo odnose. One su prisutne u svakodnevnim odlukama, u načinu na koji surađujemo unutar tima i u odnosu koji gradimo s klijentima.\", \"items\": [{\"lead\": \"Volimo ljude koji žele učiti, pitati, istraživati i brzo se razvijati.\", \"title\": \"Learn fast\", \"body_html\": \"<p>Volimo ljude koji žele učiti, pitati, istraživati i brzo se razvijati.</p><p>Radimo u okruženju koje se stalno mijenja - tržište, zakoni, tehnologija, potrebe klijenata. Zato vjerujemo da je sposobnost brzog učenja jedna od najvažnijih stvari koje možemo imati kao tim.</p><p>Kod nas nije problem ne znati. Problem je ne htjeti naučiti.</p><p>Zato dijelimo znanje, učimo jedni od drugih, razvijamo se kroz praksu i ne čekamo savršeni trenutak da preuzmemo odgovornost. Učimo brzo jer želimo biti bolji - za sebe, za tim i za klijente.</p>\", \"paragraphs\": [\"Radimo u okruženju koje se stalno mijenja - tržište, zakoni, tehnologija, potrebe klijenata. Zato vjerujemo da je sposobnost brzog učenja jedna od najvažnijih stvari koje možemo imati kao tim.\", \"Kod nas nije problem ne znati. Problem je ne htjeti naučiti.\", \"Zato dijelimo znanje, učimo jedni od drugih, razvijamo se kroz praksu i ne čekamo savršeni trenutak da preuzmemo odgovornost. Učimo brzo jer želimo biti bolji - za sebe, za tim i za klijente.\"]}, {\"lead\": \"Ne vjerujemo u kulturu \\\"ostani duže pa će izgledati da puno radiš\\\".\", \"title\": \"Work smart, not hard\", \"body_html\": \"<p>Ne vjerujemo u kulturu &quot;ostani duže pa će izgledati da puno radiš&quot;.</p><p>Vjerujemo u pametan rad. To znači da razmišljamo unaprijed, postavljamo prioritete, tražimo bolja rješenja i ne radimo stvari samo zato što su se uvijek tako radile.</p><p>Volimo ljude koji prepoznaju problem, ali još više one koji predlažu rješenje. Za nas produktivnost nije kaos, nego fokus. Nije više sati, nego bolji način rada.</p><p>Želimo stvarati rezultate bez nepotrebne kompleksnosti - kvalitetno, odgovorno i s jasnim ciljem.</p>\", \"paragraphs\": [\"Vjerujemo u pametan rad. To znači da razmišljamo unaprijed, postavljamo prioritete, tražimo bolja rješenja i ne radimo stvari samo zato što su se uvijek tako radile.\", \"Volimo ljude koji prepoznaju problem, ali još više one koji predlažu rješenje. Za nas produktivnost nije kaos, nego fokus. Nije više sati, nego bolji način rada.\", \"Želimo stvarati rezultate bez nepotrebne kompleksnosti - kvalitetno, odgovorno i s jasnim ciljem.\"]}, {\"lead\": \"Ljudi su uvijek važniji od procesa.\", \"title\": \"Relationship over transaction\", \"body_html\": \"<p>Ljudi su uvijek važniji od procesa.</p><p>Ne gradimo odnose koji traju jedan projekt ili jedan e-mail. Gradimo partnerstva.</p><p>To vrijedi za klijente, ali i za tim. Vjerujemo da se povjerenje gradi dostupnošću, iskrenošću, kvalitetnom komunikacijom i spremnošću da budemo tu kada je važno.</p><p>Volimo dugoročne odnose jer vjerujemo da najbolje stvari nastaju kada postoji povjerenje i kada ljudi stvarno razumiju jedni druge. Na kraju dana, brojke jesu važne, ali ljudi su razlog zašto posao ima smisla.</p>\", \"paragraphs\": [\"Ne gradimo odnose koji traju jedan projekt ili jedan e-mail. Gradimo partnerstva.\", \"To vrijedi za klijente, ali i za tim. Vjerujemo da se povjerenje gradi dostupnošću, iskrenošću, kvalitetnom komunikacijom i spremnošću da budemo tu kada je važno.\", \"Volimo dugoročne odnose jer vjerujemo da najbolje stvari nastaju kada postoji povjerenje i kada ljudi stvarno razumiju jedni druge. Na kraju dana, brojke jesu važne, ali ljudi su razlog zašto posao ima smisla.\"]}], \"label\": \"Naše vrijednosti\", \"title\": \"Jednostavni principi koji vode svaki dan\", \"kicker\": \"Naše vrijednosti\"}, \"culture\": {\"quote\": \"U ALPHA CAPITALISU vjerujemo da kvalitetno poslovanje počinje kvalitetnim odnosima.\", \"title\": \"Kvalitetno poslovanje počinje kvalitetnim odnosima\", \"kicker\": \"Naša kultura\", \"body_html\": \"<p>Gradimo kulturu koja potiče suradnju, profesionalni razvoj, otvorenu komunikaciju i međusobno poštovanje.</p><p>Naš tim čine ljudi različitih iskustava i stručnosti koje povezuje zajednički cilj - pružiti klijentima najbolju moguću podršku.</p><p>Potičemo kontinuirano učenje, razmjenu znanja i razvoj novih ideja jer vjerujemo da upravo ljudi čine najveću razliku.</p><p>Uz profesionalnost, jednako nam je važna pozitivna radna atmosfera, osjećaj pripadnosti i zajednički rast.</p>\", \"paragraphs\": [\"Gradimo kulturu koja potiče suradnju, profesionalni razvoj, otvorenu komunikaciju i međusobno poštovanje.\", \"Naš tim čine ljudi različitih iskustava i stručnosti koje povezuje zajednički cilj - pružiti klijentima najbolju moguću podršku.\", \"Potičemo kontinuirano učenje, razmjenu znanja i razvoj novih ideja jer vjerujemo da upravo ljudi čine najveću razliku.\", \"Uz profesionalnost, jednako nam je važna pozitivna radna atmosfera, osjećaj pripadnosti i zajednički rast.\"]}, \"references\": {\"label\": \"Naše reference\", \"title\": \"Povjerenje klijenata potvrđuje kvalitetu našeg rada\", \"kicker\": \"Reference\", \"body_html\": \"<p>Povjerenje 700 klijenata iz različitih industrija i sektora potvrda je kvalitete i stručnosti koju svakodnevno pružamo.</p><p>Surađujemo s malim, srednjim i velikim poduzećima kojima pružamo podršku u području računovodstva, revizije i poslovnog savjetovanja.</p><p>Naši dugoročni odnosi s klijentima temelje se na povjerenju, dostupnosti, stručnosti i razumijevanju njihovih poslovnih ciljeva.</p><p>Uspjeh naših klijenata ujedno je i najveća potvrda našeg rada.</p>\", \"paragraphs\": [\"Povjerenje 700 klijenata iz različitih industrija i sektora potvrda je kvalitete i stručnosti koju svakodnevno pružamo.\", \"Surađujemo s malim, srednjim i velikim poduzećima kojima pružamo podršku u području računovodstva, revizije i poslovnog savjetovanja.\", \"Naši dugoročni odnosi s klijentima temelje se na povjerenju, dostupnosti, stručnosti i razumijevanju njihovih poslovnih ciljeva.\", \"Uspjeh naših klijenata ujedno je i najveća potvrda našeg rada.\"], \"button_label\": \"Sve reference\"}, \"responsibility\": {\"quote\": \"Vjerujemo da uspjeh ima najveću vrijednost kada stvara prilike za druge.\", \"title\": \"AUXILIUM CAPITALIS - ulaganje u budućnost\", \"kicker\": \"Društveno odgovorno poslovanje\", \"cta_text\": \"Pozivamo pojedince, partnere i tvrtke da nam se pridruže u stvaranju novih prilika za mlade i zajedno pomognemo graditi bolju budućnost.\", \"body_html\": \"<p>Zato smo pokrenuli AUXILIUM CAPITALIS - inicijativu usmjerenu na stipendiranje učenika i pružanje podrške mladima kroz obrazovanje, razvoj i financijsku pismenost.</p><p>Naš cilj je pomoći talentiranim i perspektivnim mladim ljudima da lakše ostvare svoj potencijal, bez obzira na okolnosti iz kojih dolaze.</p><p>Vjerujemo da ulaganje u znanje, prilike i mlade generacije dugoročno mijenja zajednicu na bolje.</p><p>AUXILIUM CAPITALIS nije samo projekt - to je način na koji želimo vraćati zajednici i stvarati konkretan, dugoročan utjecaj.</p>\", \"cta_intro\": \"Želite biti dio ove priče?\", \"cta_status\": \"Otvoreni smo za razgovor i nova partnerstva.\", \"paragraphs\": [\"Zato smo pokrenuli AUXILIUM CAPITALIS - inicijativu usmjerenu na stipendiranje učenika i pružanje podrške mladima kroz obrazovanje, razvoj i financijsku pismenost.\", \"Naš cilj je pomoći talentiranim i perspektivnim mladim ljudima da lakše ostvare svoj potencijal, bez obzira na okolnosti iz kojih dolaze.\", \"Vjerujemo da ulaganje u znanje, prilike i mlade generacije dugoročno mijenja zajednicu na bolje.\", \"AUXILIUM CAPITALIS nije samo projekt - to je način na koji želimo vraćati zajednici i stvarati konkretan, dugoročan utjecaj.\"], \"cta_card_title\": \"Zajedno možemo više.\", \"cta_button_label\": \"Kontaktirajte nas\"}}}', '2026-05-12 11:22:13', '2026-08-25 08:29:04'
FROM `content_info_pages` AS `parent`
WHERE `parent`.`code` = 'about-us'
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `slug` = VALUES(`slug`), `excerpt` = VALUES(`excerpt`), `body_html` = VALUES(`body_html`), `meta_title` = VALUES(`meta_title`), `meta_description` = VALUES(`meta_description`), `payload` = VALUES(`payload`), `updated_at` = VALUES(`updated_at`);

INSERT INTO `content_info_page_translations` (`page_id`, `locale`, `title`, `slug`, `excerpt`, `body_html`, `meta_title`, `meta_description`, `payload`, `created_at`, `updated_at`)
SELECT `parent`.`id`, 'en', 'About us', 'about-us', 'ALPHA CAPITALIS brings together experts in accounting, audit and advisory with one shared purpose — to help entrepreneurs navigate every stage of business with greater confidence.', NULL, 'About us | ALPHA CAPITALIS', 'ALPHA CAPITALIS brings together experts in accounting, audit and advisory with one shared purpose — to help entrepreneurs navigate every stage of business with greater confidence.', '{\"about_page\": {\"why\": {\"quote\": \"Quality professional support is not just about providing an answer once a problem has already arisen.\", \"title\": \"By your side before, during and after every important decision\", \"kicker\": \"Why we exist\", \"body_html\": \"<p>Our goal is to help clients overcome obstacles before they become serious problems, avoid the most difficult scenarios whenever possible and, if they do find themselves in a challenging situation, work together to find a way forward.</p><p>We believe quality professional support means having the right people by your side before, during and after every important business decision.</p>\"}, \"hero\": {\"lead\": \"More than expert support. A partner through every stage of business.\", \"title\": \"Our story\", \"eyebrow\": \"About us\", \"image_alt\": \"ALPHA CAPITALIS team\", \"stat_label\": \"clients we support every day\", \"stat_value\": \"700\"}, \"team\": {\"label\": \"Our team\", \"stats\": [{\"label\": \"professionals\", \"value\": \"75\"}, {\"label\": \"members of management\", \"value\": \"9\"}, {\"label\": \"clients\", \"value\": \"700\"}, {\"label\": \"offices in Zagreb, Vinkovci and Rijeka\", \"value\": \"3\"}], \"title\": \"A team of experts in one place\", \"kicker\": \"Our team\", \"body_html\": \"<p>Different challenges require different expertise. Every business is different, and what a company needs at the start is not the same as what it needs during growth, expansion, reorganisation or the transfer of the business to the next generation.</p><p>That is why at ALPHA CAPITALIS we bring together experts in accounting, audit, tax, finance and business advisory. When needed, we bring different perspectives and areas of expertise together around the same challenge, giving the client an integrated team that understands the broader context of their business and can provide support throughout different stages of development.</p>\", \"button_label\": \"\"}, \"story\": {\"body_html\": \"<p>ALPHA CAPITALIS brings together experts in accounting, audit and advisory with one shared purpose — to help entrepreneurs navigate every stage of business with greater confidence.</p><p>Because business is never a straight line.</p><p>Companies grow, evolve, enter new markets, hire people, invest, face challenges and make decisions that can shape what comes next. Sometimes the priority is finding an opportunity for growth. Sometimes it is protecting what has taken years to build. And sometimes it is finding a solution when things do not go according to plan.</p><p>That is exactly why we are here.</p><p>We want to stand alongside entrepreneurs when they make important decisions, move from one stage of business to another and face challenges that cannot be solved through a single opinion or one area of expertise alone.</p><p>Because no single person can know or solve everything.</p><p>But a strong multidisciplinary team can look at a business from multiple perspectives, connect different areas of expertise and help find a more comprehensive solution.</p><p>That is why our clients do not have just one adviser by their side. They have a team of experts who understand different aspects of business and can provide support when it matters most — from day-to-day accounting and tax matters to financial decisions, audit, growth, transformation and more complex business challenges.</p>\"}, \"values\": {\"intro\": \"At ALPHA CAPITALIS, our values are more than words — they shape how we think, how we work and how we build relationships. They are reflected in our everyday decisions, in the way we collaborate as a team and in the relationships we build with our clients.\", \"items\": [{\"title\": \"Learn fast\", \"body_html\": \"<p>We value people who want to learn, ask questions, explore and develop quickly.</p><p>We work in an environment that is constantly changing — markets, regulations, technology and client needs. That is why we believe the ability to learn quickly is one of the most important qualities we can have as a team.</p><p>Not knowing something is not a problem. Not wanting to learn is.</p><p>That is why we share knowledge, learn from one another, develop through experience and do not wait for the perfect moment to take responsibility. We learn fast because we want to become better — for ourselves, for our team and for our clients.</p>\"}, {\"title\": \"Work smart, not hard\", \"body_html\": \"<p>We do not believe in a culture of “stay longer so it looks like you are working harder.”</p><p>We believe in working smart. That means thinking ahead, setting priorities, looking for better solutions and not doing things simply because they have always been done that way.</p><p>We value people who recognise a problem, but even more those who propose a solution. For us, productivity is not chaos — it is focus. It is not about working more hours, but about finding a better way to work.</p><p>We aim to deliver results without unnecessary complexity — with quality, responsibility and a clear purpose.</p>\"}, {\"title\": \"Relationship over transaction\", \"body_html\": \"<p>People are always more important than processes.</p><p>We do not build relationships that last for one project or one email. We build partnerships.</p><p>That applies to our clients as well as our team. We believe trust is built through availability, honesty, clear communication and a willingness to be there when it matters.</p><p>We value long-term relationships because we believe the best outcomes are created when there is trust and when people genuinely understand one another. At the end of the day, numbers matter — but people are what give business its meaning.</p>\"}], \"label\": \"Our values\", \"title\": \"Simple principles that guide us every day\", \"kicker\": \"Our values\"}}}', '2026-05-12 11:22:13', '2026-08-25 07:17:34'
FROM `content_info_pages` AS `parent`
WHERE `parent`.`code` = 'about-us'
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `slug` = VALUES(`slug`), `excerpt` = VALUES(`excerpt`), `body_html` = VALUES(`body_html`), `meta_title` = VALUES(`meta_title`), `meta_description` = VALUES(`meta_description`), `payload` = VALUES(`payload`), `updated_at` = VALUES(`updated_at`);

