-- The original live snapshot has the Career/gallery/Audit media deployed by the
-- 2026-08-21 live SQL, but it predates the About hero media migration. Link the
-- versioned public asset through the CMS media collection without overwriting a
-- hero image an editor may already have uploaded on live.
SET @ac_about_page_id := (
    SELECT `id`
    FROM `content_info_pages`
    WHERE `code` = 'about-us' OR `layout` = 'about'
    ORDER BY CASE WHEN `code` = 'about-us' THEN 0 ELSE 1 END, `id`
    LIMIT 1
);

INSERT INTO `media` (
    `model_type`, `model_id`, `uuid`, `collection_name`, `name`, `file_name`,
    `mime_type`, `disk`, `conversions_disk`, `size`, `manipulations`,
    `custom_properties`, `generated_conversions`, `responsive_images`,
    `order_column`, `created_at`, `updated_at`
)
SELECT
    'App\\Models\\Content\\Page\\InfoPage', @ac_about_page_id, UUID(),
    'about_hero_image', 'ALPHA CAPITALIS tim', 'o-nama.jpg',
    'image/jpeg', 'public', 'public', 506610, JSON_OBJECT(),
    JSON_OBJECT(
        'bundled_asset_path', 'front-theme/images/about/o-nama.jpg',
        'alt', JSON_OBJECT(
            'hr', 'ALPHA CAPITALIS tim',
            'en', 'ALPHA CAPITALIS team'
        )
    ),
    JSON_OBJECT(), JSON_OBJECT(), 1, NOW(), NOW()
FROM DUAL
WHERE @ac_about_page_id IS NOT NULL
  AND NOT EXISTS (
      SELECT 1
      FROM `media`
      WHERE `model_type` = 'App\\Models\\Content\\Page\\InfoPage'
        AND `model_id` = @ac_about_page_id
        AND `collection_name` = 'about_hero_image'
  );

-- Record the equivalent guarded migrations as applied.
SET @ac_live_batch := (SELECT COALESCE(MAX(`batch`), 0) + 1 FROM `migrations`);
INSERT INTO `migrations` (`migration`, `batch`)
SELECT `pending`.`migration`, @ac_live_batch
FROM (
    SELECT '2026_08_13_140000_refresh_audit_service_page_intro_copy' AS `migration`
    UNION ALL SELECT '2026_08_13_150000_refresh_accounting_service_page_intro_copy'
    UNION ALL SELECT '2026_08_13_153000_refresh_advisory_service_page_intro_copy'
    UNION ALL SELECT '2026_08_13_160000_add_about_hero_image_media'
    UNION ALL SELECT '2026_08_13_161000_add_career_hero_image_media'
    UNION ALL SELECT '2026_08_14_093500_add_home_to_front_navigation_settings'
    UNION ALL SELECT '2026_08_17_120000_create_legal_info_pages'
    UNION ALL SELECT '2026_08_21_090000_apply_client_content_review'
    UNION ALL SELECT '2026_08_21_091000_add_career_gallery_images'
    UNION ALL SELECT '2026_08_21_092000_update_selected_career_and_audit_images'
    UNION ALL SELECT '2026_08_21_093000_reorder_career_gallery_images'
    UNION ALL SELECT '2026_08_21_094000_emphasize_about_story_copy'
