-- Verification report. Expected values: en=active, blocks=6, services=10,
-- info_pages=4, call_categories=6, english_calls=16, about_media=1,
-- form_type=1.
SELECT 'english_active' AS `check_name`, COUNT(*) AS `actual`, 1 AS `expected`
FROM `languages` WHERE `code` = 'en' AND `is_active` = 1
UNION ALL
SELECT 'home_block_translations', COUNT(*), 6
FROM `content_block_translations` AS `t`
JOIN `content_blocks` AS `b` ON `b`.`id` = `t`.`content_block_id`
WHERE `b`.`code` IN ('home-alpha-hero', 'home-alpha-stats', 'home-alpha-services')
  AND `t`.`locale` IN ('hr', 'en')
UNION ALL
SELECT 'service_translations', COUNT(*), 10
FROM `content_service_page_translations` AS `t`
JOIN `content_service_pages` AS `p` ON `p`.`id` = `t`.`service_page_id`
WHERE `p`.`code` IN ('audit', 'eu-fondovi', 'racunovodstvo', 'advisory', 'services')
  AND `t`.`locale` IN ('hr', 'en')
UNION ALL
SELECT 'info_page_translations', COUNT(*), 4
FROM `content_info_page_translations` AS `t`
JOIN `content_info_pages` AS `p` ON `p`.`id` = `t`.`page_id`
WHERE `p`.`code` IN ('career', 'about-us')
  AND `t`.`locale` IN ('hr', 'en')
UNION ALL
SELECT 'call_category_translations', COUNT(*), 6
FROM `category_translations` AS `t`
JOIN `categories` AS `c` ON `c`.`id` = `t`.`category_id`
WHERE `c`.`scope` = 'call'
  AND `c`.`code` IN ('pozivi-u-najavi', 'otvoreni-pozivi', 'zatvoreni-pozivi')
  AND `t`.`locale` IN ('hr', 'en')
UNION ALL
SELECT 'english_call_translations', COUNT(*), 16
FROM `content_call_post_translations` AS `t`
