  AND `t`.`locale` = 'en'
UNION ALL
SELECT 'about_hero_media', COUNT(*), 1
FROM `media` AS `m`
JOIN `content_info_pages` AS `p` ON `p`.`id` = `m`.`model_id`
WHERE `m`.`model_type` = 'App\\Models\\Content\\Page\\InfoPage'
  AND `m`.`collection_name` = 'about_hero_image'
